{
  "name": "Fudbalski Maestro Kviz",
  "description": "Ultimativna fudbalska kviz igra sa nivoima, kategorijama (igrači, stadioni, klubovi, treneri) i dinamičkim generisanjem pitanja pomoću veštačke inteligencije."
}

export enum Category {
  PLAYERS = 'IGRAČI',
  STADIUMS = 'STADIONI',
  CLUBS = 'KLUBOVI',
  NATIONAL_TEAMS = 'NACIONALNI TIMOVI',
  COACHES = 'TRENERI'
}

export interface Question {
  id: string;
  category: Category;
  text: string;
  options: string[];
  correctAnswer: string;
  difficulty: number; // 1 to 10
  explanation?: string;
}

export interface GameState {
  currentLevel: number;
  score: number;
  questionsAnswered: number;
  correctAnswers: number;
  isGameOver: boolean;
  history: {
    questionId: string;
    isCorrect: boolean;
  }[];
}

export interface LevelConfig {
  id: number;
  name: string;
  minDifficulty: number;
  maxDifficulty: number;
  questionsPerLevel: number;
  unlocked: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  count: number = 5
): Promise<Question[]> => {
  const prompt = `Generiši ${count} fudbalskih pitanja na SRPSKOM jeziku. 
  Kategorija: ${category}. 
  Težina: ${difficulty} (od 1-lakše do 10-teže). 
  Svako pitanje mora imati 4 opcije i tačan odgovor. 
  Takođe dodaj kratko objašnjenje zašto je taj odgovor tačan.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              category: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              difficulty: { type: Type.NUMBER },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return parsed.map((q: any) => ({
      ...q,
      category: category,
      difficulty: difficulty
    }));
  } catch (error) {
    console.error("Error generating questions:", error);
    return [];
  }
};

import React, { useState } from 'react';
import { Question } from '../types';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
}

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled }) => {
  const [selected, setSelected] = useState<string | null>(null);

  const handleSelect = (option: string) => {
    if (disabled) return;
    setSelected(option);
    setTimeout(() => {
        onAnswer(option);
        setSelected(null);
    }, 800);
  };

  return (
    <div className="w-full max-w-2xl mx-auto bg-white/10 backdrop-blur-lg rounded-3xl p-6 md:p-10 shadow-2xl border border-white/20 animate-in fade-in zoom-in duration-500">
      <div className="flex justify-between items-center mb-6">
        <span className="px-4 py-1 bg-emerald-500 text-white rounded-full text-sm font-bold tracking-wider">
          {question.category}
        </span>
        <span className="text-white/60 text-sm italic">
          Nivo Težine: {question.difficulty}
        </span>
      </div>

      <h2 className="text-2xl md:text-3xl font-bold text-white mb-8 leading-tight">
        {question.text}
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrong = isSelected && option !== question.correctAnswer;

          return (
            <button
              key={idx}
              onClick={() => handleSelect(option)}
              disabled={disabled}
              className={`
                group relative p-4 rounded-2xl text-left font-semibold transition-all duration-300
                ${isSelected ? 'scale-95' : 'hover:scale-102'}
                ${!selected ? 'bg-white/5 hover:bg-white/20 text-white border border-white/10' : ''}
                ${isCorrect ? 'bg-emerald-500 text-white shadow-[0_0_20px_rgba(16,185,129,0.5)]' : ''}
                ${isWrong ? 'bg-rose-500 text-white shadow-[0_0_20px_rgba(244,63,94,0.5)]' : ''}
                ${selected && !isSelected ? 'opacity-40 bg-white/5 text-white/50' : ''}
              `}
            >
              <div className="flex items-center space-x-3">
                <span className="w-8 h-8 flex items-center justify-center rounded-full bg-black/20 text-xs">
                  {String.fromCharCode(65 + idx)}
                </span>
                <span>{option}</span>
              </div>
            </button>
          );
        })}
      </div>

      {selected && question.explanation && (
         <div className="mt-8 p-4 bg-blue-500/20 border border-blue-500/30 rounded-xl animate-in slide-in-from-bottom-2">
            <p className="text-blue-200 text-sm">
              <span className="font-bold">Info:</span> {question.explanation}
            </p>
         </div>
      )}
    </div>
  );
};

export default QuizCard;

import React, { useState, useEffect, useCallback } from 'react';
import { Category, Question, GameState, LevelConfig } from './types';
import { generateQuestions } from './services/geminiService';
import QuizCard from './components/QuizCard';

const LEVELS: LevelConfig[] = [
  { id: 1, name: "Početnik", minDifficulty: 1, maxDifficulty: 3, questionsPerLevel: 30, unlocked: true },
  { id: 2, name: "Poznavalac", minDifficulty: 4, maxDifficulty: 6, questionsPerLevel: 30, unlocked: false },
  { id: 3, name: "Legenda", minDifficulty: 7, maxDifficulty: 10, questionsPerLevel: 30, unlocked: false },
];

const CATEGORIES = Object.values(Category);

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    currentLevel: 1,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    isGameOver: false,
    history: [],
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [levelProgress, setLevelProgress] = useState(0);

  const fetchBatch = useCallback(async (level: number) => {
    setLoading(true);
    const config = LEVELS.find(l => l.id === level)!;
    // We fetch a mix of categories for variety
    const randomCategory = CATEGORIES[Math.floor(Math.random() * CATEGORIES.length)];
    const difficulty = Math.floor(Math.random() * (config.maxDifficulty - config.minDifficulty + 1)) + config.minDifficulty;

    const newQuestions = await generateQuestions(randomCategory, difficulty, 5);
    setQuestions(prev => [...prev, ...newQuestions]);
    setLoading(false);
  }, []);

  useEffect(() => {
    if (isPlaying && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30) {
      fetchBatch(gameState.currentLevel);
    }
  }, [isPlaying, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.questionsAnswered, fetchBatch]);

  const handleStart = () => {
    setGameState({
      currentLevel: 1,
      score: 0,
      questionsAnswered: 0,
      correctAnswers: 0,
      isGameOver: false,
      history: [],
    });
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setIsPlaying(true);
    setLevelProgress(0);
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    const isCorrect = answer === currentQ.correctAnswer;

    const points = isCorrect ? currentQ.difficulty * 10 : 0;

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      history: [...prev.history, { questionId: currentQ.id, isCorrect }],
      isGameOver: prev.questionsAnswered + 1 >= 30
    }));

    setLevelProgress(((gameState.questionsAnswered + 1) / 30) * 100);

    setTimeout(() => {
        setCurrentQuestionIndex(prev => prev + 1);
    }, 500);
  };

  if (gameState.isGameOver) {
    return (
      <div className="min-h-screen grass-gradient flex items-center justify-center p-6">
        <div className="bg-white/10 backdrop-blur-xl p-10 rounded-3xl border border-white/20 text-center max-w-lg w-full">
          <h1 className="text-4xl font-extrabold text-white mb-4">KRAJ IGRE!</h1>
          <p className="text-xl text-white/80 mb-8">Završili ste Nivo {gameState.currentLevel}</p>

          <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-white/5 p-4 rounded-2xl">
              <p className="text-white/60 text-sm">Tačnih Odgovora</p>
              <p className="text-2xl font-bold text-emerald-400">{gameState.correctAnswers}/30</p>
            </div>
            <div className="bg-white/5 p-4 rounded-2xl">
              <p className="text-white/60 text-sm">Ukupni Skor</p>
              <p className="text-2xl font-bold text-yellow-400">{gameState.score}</p>
            </div>
          </div>

          <button
            onClick={handleStart}
            className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-emerald-500/20"
          >
            Igraj Ponovo
          </button>
        </div>
      </div>
    );
  }

  if (!isPlaying) {
    return (
      <div className="min-h-screen grass-gradient flex flex-col items-center justify-center p-6">
        <div className="text-center mb-12 animate-in fade-in slide-in-from-top-4 duration-1000">
          <div className="inline-block p-4 bg-emerald-500/20 rounded-full mb-6 border border-emerald-500/30">
            <svg className="w-16 h-16 text-emerald-400" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-13h2v6h-2zm0 8h2v2h-2z" />
            </svg>
          </div>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-4 tracking-tight">
            MAESTRO <span className="text-emerald-500 text-outline">KVIZ</span>
          </h1>
          <p className="text-lg md:text-xl text-white/60 max-w-md mx-auto">
            Testiraj svoje znanje o igračima, stadionima, klubovima i legendarnim trenerima.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full">
          {LEVELS.map(level => (
            <div 
              key={level.id}
              className={`
                relative p-8 rounded-3xl border transition-all duration-300
                ${level.unlocked ? 'bg-white/10 border-white/20 hover:scale-105 hover:bg-white/15' : 'bg-black/40 border-white/5 opacity-50 cursor-not-allowed'}
              `}
            >
              {!level.unlocked && (
                <div className="absolute top-4 right-4">
                  <svg className="w-6 h-6 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                  </svg>
                </div>
              )}
              <h3 className="text-white/60 text-sm font-bold mb-1 uppercase tracking-widest">Nivo {level.id}</h3>
              <h2 className="text-2xl font-bold text-white mb-4">{level.name}</h2>
              <p className="text-white/40 text-sm mb-6">30 Pitanja (Težina {level.minDifficulty}-{level.maxDifficulty})</p>

              {level.unlocked && (
                <button
                  onClick={handleStart}
                  className="w-full bg-white text-black font-bold py-3 rounded-xl hover:bg-emerald-400 hover:text-white transition-colors"
                >
                  Započni
                </button>
              )}
            </div>
          ))}
        </div>

        <footer className="mt-20 text-white/20 text-sm">
          Powered by Gemini AI • 2024 Fudbalski Maestro
        </footer>
      </div>
    );
  }

  return (
    <div className="min-h-screen grass-gradient p-4 md:p-8 flex flex-col">
      <header className="max-w-4xl w-full mx-auto flex flex-col md:flex-row justify-between items-center mb-12 gap-4">
        <div className="flex items-center space-x-4">
          <button 
            onClick={() => setIsPlaying(false)}
            className="p-2 bg-white/5 hover:bg-white/10 rounded-full text-white transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <div>
            <h1 className="text-white font-bold text-xl">Fudbalski Maestro</h1>
            <p className="text-white/40 text-xs tracking-widest uppercase">Nivo {gameState.currentLevel}: {LEVELS[gameState.currentLevel-1].name}</p>
          </div>
        </div>

        <div className="flex items-center space-x-8">
          <div className="text-center">
            <p className="text-white/40 text-[10px] uppercase font-bold tracking-tighter">Skor</p>
            <p className="text-2xl font-black text-yellow-400">{gameState.score}</p>
          </div>
          <div className="text-center">
            <p className="text-white/40 text-[10px] uppercase font-bold tracking-tighter">Progres</p>
            <p className="text-2xl font-black text-emerald-400">{gameState.questionsAnswered}<span className="text-white/20">/30</span></p>
          </div>
        </div>
      </header>

      <div className="max-w-4xl w-full mx-auto mb-8 h-2 bg-white/5 rounded-full overflow-hidden border border-white/5 shadow-inner">
        <div 
          className="h-full bg-gradient-to-r from-emerald-600 to-emerald-400 transition-all duration-500 ease-out"
          style={{ width: `${levelProgress}%` }}
        />
      </div>

      <main className="flex-1 flex flex-col items-center justify-center">
        {loading && questions.length <= currentQuestionIndex ? (
          <div className="flex flex-col items-center">
            <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="text-white/60 animate-pulse font-medium">Generišem fudbalska pitanja...</p>
          </div>
        ) : questions[currentQuestionIndex] ? (
          <QuizCard 
            key={questions[currentQuestionIndex].id}
            question={questions[currentQuestionIndex]}
            onAnswer={handleAnswer}
            disabled={false}
          />
        ) : null}
      </main>

      <div className="mt-12 max-w-4xl w-full mx-auto grid grid-cols-5 gap-2">
        {Array.from({ length: 30 }).map((_, i) => {
          const status = gameState.history[i];
          return (
            <div 
              key={i}
              className={`h-1.5 rounded-full transition-colors duration-500
                ${status === undefined ? 'bg-white/10' : status.isCorrect ? 'bg-emerald-500 shadow-[0_0_5px_rgba(16,185,129,0.5)]' : 'bg-rose-500'}
              `}
            />
          );
        })}
      </div>
    </div>
  );
};

export default App;

