import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<Question[]> => {
  const prompt = `Generiši ${count} fudbalskih pitanja na jeziku: ${language}. 
  Kategorija: ${category}. 
  Težina: ${difficulty} (od 1-lakše do 10-teže). 
  Svako pitanje mora imati 4 opcije i tačan odgovor. 
  Takođe dodaj kratko objašnjenje zašto je taj odgovor tačan na istom jeziku (${language}).`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return parsed.map((q: any) => ({
      ...q,
      category: category,
      difficulty: difficulty
    }));
  } catch (error) {
    console.error("Error generating questions:", error);
    return [];
  }
};

