    maxDifficulty: 6, 
    questionsPerLevel: 30, 
    unlocked: false 
  },
  { 
    id: 3, 
    name: { Bosanski: "Legenda", English: "Legend", Deutsch: "Legende" }, 
    minDifficulty: 7, 
    maxDifficulty: 10, 
    questionsPerLevel: 30, 
    unlocked: false 
  },
];

const CATEGORIES = Object.values(Category);

const TRANSLATIONS = {
  score: { Bosanski: "Skor", English: "Score", Deutsch: "Punktestand" },
  progress: { Bosanski: "Progres", English: "Progress", Deutsch: "Fortschritt" },
