  generating: { Bosanski: "Generišem pitanja...", English: "Generating questions...", Deutsch: "Fragen werden generiert..." },
  subTitle: { 
    Bosanski: "Testiraj svoje znanje o igračima, stadionima, klubovima i trenerima.", 
