import React, { useState } from 'react';
import { Question } from '../types';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
}

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled }) => {
  const [selected, setSelected] = useState<string | null>(null);

  const handleSelect = (option: string) => {
    if (disabled) return;
    setSelected(option);
    setTimeout(() => {
        onAnswer(option);
        setSelected(null);
    }, 800);
  };

  return (
    <div className="w-full max-w-2xl mx-auto bg-black/60 backdrop-blur-xl rounded-[2.5rem] p-8 md:p-12 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] border border-white/10 animate-in fade-in zoom-in duration-500">
      <div className="flex justify-between items-center mb-8">
        <span className="px-5 py-1.5 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-full text-xs font-black tracking-widest uppercase">
          {question.category}
        </span>
        <span className="text-white/30 text-[10px] font-bold tracking-widest uppercase">
          DIFFICULTY: {question.difficulty}
        </span>
      </div>

      <h2 className="text-2xl md:text-3xl font-bold text-white mb-10 leading-[1.2] text-center">
        {question.text}
      </h2>

      <div className="grid grid-cols-1 gap-3">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrong = isSelected && option !== question.correctAnswer;

          return (
            <button
              key={idx}
              onClick={() => handleSelect(option)}
              disabled={disabled}
              className={`
                group relative p-5 rounded-2xl text-left font-bold transition-all duration-300 border
                ${isSelected ? 'scale-[0.98]' : 'hover:bg-white/5'}
                ${!selected ? 'bg-white/5 border-white/5 text-white/80' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_0_30px_rgba(16,185,129,0.4)]' : ''}
                ${isWrong ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_30px_rgba(244,63,94,0.4)]' : ''}
                ${selected && !isSelected ? 'opacity-20 border-transparent grayscale' : ''}
              `}
            >
              <div className="flex items-center space-x-4">
                <span className={`w-10 h-10 flex items-center justify-center rounded-xl font-black text-sm transition-colors
                  ${isSelected ? 'bg-black/20' : 'bg-black/40 text-emerald-500'}
                `}>
                  {String.fromCharCode(65 + idx)}
                </span>
                <span className="text-lg">{option}</span>
              </div>
            </button>
          );
        })}
      </div>

      {selected && question.explanation && (
         <div className="mt-10 p-5 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl animate-in slide-in-from-bottom-2 duration-500">
            <p className="text-emerald-300/80 text-sm leading-relaxed text-center italic">
              {question.explanation}
            </p>
         </div>
      )}
    </div>
  );
};

export default QuizCard;

import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";
import { LOCAL_QUESTIONS } from "../data/localQuestions";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getOfflineQuestions = (category: Category, language: Language, count: number): Question[] => {
  const pool = LOCAL_QUESTIONS[language].filter(q => q.category === category || q.category === Category.PLAYERS); // Fallback to players if pool small
  const shuffled = [...pool].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: `offline-${Date.now()}-${Math.random()}`
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<{ questions: Question[], isOffline: boolean }> => {

  // Quick check for internet connection
  if (!navigator.onLine) {
    return { questions: getOfflineQuestions(category, language, count), isOffline: true };
  }

  const prompt = `Generiši ${count} fudbalskih pitanja na jeziku: ${language}. 
  Kategorija: ${category}. 
  Težina: ${difficulty} (od 1-lakše do 10-teže). 
  Svako pitanje mora imati 4 opcije i tačan odgovor. 
  Takođe dodaj kratko objašnjenje zašto je taj odgovor tačan na istom jeziku (${language}).`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response");

    const parsed = JSON.parse(text);
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.warn("Gemini API error, falling back to offline mode:", error);
    return { questions: getOfflineQuestions(category, language, count), isOffline: true };
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Category, Question, GameState, LevelConfig, Language } from './types';
import { generateQuestions } from './services/geminiService';
import QuizCard from './components/QuizCard';

const LEVELS: LevelConfig[] = [
  { 
    id: 1, 
    name: { Bosanski: "Početnik", English: "Beginner", Deutsch: "Anfänger" }, 
    minDifficulty: 1, 
    maxDifficulty: 3, 
    questionsPerLevel: 30, 
    unlocked: true 
