    maxDifficulty: 6, 
    questionsPerLevel: 30, 
    unlocked: false 
  },
  { 
    id: 3, 
    name: { Bosanski: "Legenda", English: "Legend", Deutsch: "Legende" }, 
    minDifficulty: 7, 
    maxDifficulty: 10, 
    questionsPerLevel: 30, 
    unlocked: false 
  },
];

const CATEGORIES = Object.values(Category);

const TRANSLATIONS = {
  score: { Bosanski: "Skor", English: "Score", Deutsch: "Punktestand" },
  progress: { Bosanski: "Progres", English: "Progress", Deutsch: "Fortschritt" },
  gameOver: { Bosanski: "KRAJ IGRE!", English: "GAME OVER!", Deutsch: "SPIEL VORBEI!" },
  finishedLevel: { Bosanski: "Završili ste Nivo", English: "You finished Level", Deutsch: "Du hast Level abgeschlossen" },
  correctAnswersLabel: { Bosanski: "Tačnih Odgovora", English: "Correct Answers", Deutsch: "Richtige Antworten" },
  totalScoreLabel: { Bosanski: "Ukupni Skor", English: "Total Score", Deutsch: "Gesamtpunktzahl" },
  playAgain: { Bosanski: "Igraj Ponovo", English: "Play Again", Deutsch: "Nochmal spielen" },
  start: { Bosanski: "Započni", English: "Start", Deutsch: "Start" },
  generating: { Bosanski: "Generišem pitanja...", English: "Generating questions...", Deutsch: "Fragen werden generiert..." },
  offlineMode: { Bosanski: "OFFLINE MOD", English: "OFFLINE MODE", Deutsch: "OFFLINE-MODUS" },
  subTitle: { 
    Bosanski: "Testiraj svoje znanje o igračima, stadionima, klubovima i trenerima.", 
    English: "Test your knowledge about players, stadiums, clubs and coaches.", 
    Deutsch: "Teste dein Wissen über Spieler, Stadien, Vereine und Trainer." 
  }
};

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    currentLevel: 1,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    isGameOver: false,
    language: 'English',
    history: [],
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [levelProgress, setLevelProgress] = useState(0);
  const [isMuted, setIsMuted] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const fetchBatch = useCallback(async (level: number, lang: Language) => {
    setLoading(true);
    const config = LEVELS.find(l => l.id === level)!;
    const randomCategory = CATEGORIES[Math.floor(Math.random() * CATEGORIES.length)];
    const difficulty = Math.floor(Math.random() * (config.maxDifficulty - config.minDifficulty + 1)) + config.minDifficulty;

    const result = await generateQuestions(randomCategory, difficulty, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setIsOffline(result.isOffline);
    setLoading(false);
  }, []);

  useEffect(() => {
    if (isPlaying && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30) {
      fetchBatch(gameState.currentLevel, gameState.language);
    }
  }, [isPlaying, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.questionsAnswered, gameState.language, fetchBatch]);

  useEffect(() => {
    const handleConnectivityChange = () => setIsOffline(!navigator.onLine);
    window.addEventListener('online', handleConnectivityChange);
    window.addEventListener('offline', handleConnectivityChange);
    return () => {
      window.removeEventListener('online', handleConnectivityChange);
      window.removeEventListener('offline', handleConnectivityChange);
    };
  }, []);

  useEffect(() => {
    if (!audioRef.current) {
      audioRef.current = new Audio('https://cdn.pixabay.com/audio/2022/01/18/audio_d0a13f69d2.mp3');
      audioRef.current.loop = true;
    }
    if (!isMuted) {
      audioRef.current.play().catch(e => console.log("Autoplay blocked"));
    } else {
      audioRef.current.pause();
    }
  }, [isMuted]);

  const handleStart = () => {
    setGameState(prev => ({
      ...prev,
      score: 0,
      questionsAnswered: 0,
      correctAnswers: 0,
      isGameOver: false,
      history: [],
    }));
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setIsPlaying(true);
    setLevelProgress(0);
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    const isCorrect = answer === currentQ.correctAnswer;

    const points = isCorrect ? currentQ.difficulty * 10 : 0;

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      history: [...prev.history, { questionId: currentQ.id, isCorrect }],
      isGameOver: prev.questionsAnswered + 1 >= 30
    }));

    setLevelProgress(((gameState.questionsAnswered + 1) / 30) * 100);

    setTimeout(() => {
        setCurrentQuestionIndex(prev => prev + 1);
    }, 500);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];

  if (gameState.isGameOver) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 grass-pattern">
        <div className="bg-black/60 backdrop-blur-xl p-10 rounded-3xl border border-white/10 text-center max-w-lg w-full shadow-2xl">
          <h1 className="text-4xl font-extrabold text-white mb-4">{t('gameOver')}</h1>
          <p className="text-xl text-white/80 mb-8">{t('finishedLevel')} {gameState.currentLevel}</p>

          <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
              <p className="text-white/60 text-sm">{t('correctAnswersLabel')}</p>
              <p className="text-2xl font-bold text-emerald-400">{gameState.correctAnswers}/30</p>
            </div>
            <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
              <p className="text-white/60 text-sm">{t('totalScoreLabel')}</p>
              <p className="text-2xl font-bold text-yellow-400">{gameState.score}</p>
            </div>
          </div>

          <button
            onClick={handleStart}
            className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-emerald-500/20"
          >
            {t('playAgain')}
          </button>
        </div>
      </div>
    );
  }

  if (!isPlaying) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 grass-pattern">
        {/* Offline Indicator & Language Selector */}
        <div className="absolute top-6 right-6 flex items-center space-x-3">
          {isOffline && (
             <div className="bg-rose-500/20 text-rose-400 border border-rose-500/30 px-3 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase flex items-center space-x-2">
                <span className="w-2 h-2 bg-rose-500 rounded-full animate-pulse"></span>
                <span>{t('offlineMode')}</span>
