          <div className="flex flex-col">
            <h1 className="text-white font-bold text-lg leading-tight flex items-center gap-2">
               TAP FOOTBALL 2026
               {isOffline && (
                 <span className="text-[8px] bg-rose-500/80 px-1.5 py-0.5 rounded text-white font-black uppercase tracking-tighter">OFFLINE</span>
               )}
