export enum Category {
  PLAYERS = 'PLAYERS',
  STADIUMS = 'STADIUMS',
  CLUBS = 'CLUBS',
  NATIONAL_TEAMS = 'NATIONAL_TEAMS',
  COACHES = 'COACHES',
  ALL = 'ALL'
}

export type Language = 'Bosanski' | 'English' | 'Deutsch';

export interface Question {
  id: string;
  category: Category;
  text: string;
  options: string[];
  correctAnswer: string;
  difficulty: number;
  explanation?: string;
}

export interface GameState {
  currentLevel: number;
  selectedCategory: Category;
  score: number;
  questionsAnswered: number;
  correctAnswers: number;
  isGameOver: boolean;
  language: Language;
  history: {
    questionId: string;
    isCorrect: boolean;
  }[];
}

export interface LevelConfig {
  id: number;
  name: Record<Language, string>;
  minDifficulty: number;
  maxDifficulty: number;
  questionsPerLevel: number;
  unlocked: boolean;
}

export interface LeaderboardEntry {
  name: string;
  score: number;
  country: string;
  isUser?: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Question, Language } from '../types';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
  isMuted: boolean;
  language: Language;
}

const TRANSLATIONS = {
  correct: { Bosanski: "TAČNO!", English: "CORRECT!", Deutsch: "RICHTIG!" },
  difficulty: { Bosanski: "TEŽINA", English: "DIFFICULTY", Deutsch: "SCHWIERIGKEIT" }
};

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled, isMuted, language }) => {
  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);

  const clickSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/15/audio_c8c8a73456.mp3'));
  const correctSound = useRef(new Audio('https://cdn.pixabay.com/audio/2021/08/04/audio_0625c1539c.mp3'));
  const wrongSound = useRef(new Audio('https://cdn.pixabay.com/audio/2021/08/04/audio_bbdec0463c.mp3'));

  const playSound = (audio: HTMLAudioElement) => {
    if (!isMuted) {
      audio.currentTime = 0;
      audio.play().catch(e => console.log("Sound play blocked"));
    }
  };

  const handleSelect = (option: string) => {
    if (disabled || selected) return;

    const correct = option === question.correctAnswer;
    setSelected(option);

    if (correct) {
      playSound(correctSound.current);
    } else {
      setIsWrong(true);
      playSound(wrongSound.current);
    }

    setTimeout(() => {
        onAnswer(option);
        setSelected(null);
        setIsWrong(false);
    }, 4500);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 50, scale: 0.9 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95, transition: { duration: 0.3 } }}
      className={`w-full max-w-2xl mx-auto bg-black/60 backdrop-blur-xl rounded-[2.5rem] p-8 md:p-12 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] border border-white/10 ${isWrong ? 'animate-shake border-rose-500/50' : ''}`}
    >
      <div className="flex justify-between items-center mb-8">
        <motion.span 
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="px-5 py-1.5 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-full text-[10px] font-black tracking-widest uppercase"
        >
          {question.category.replace('_', ' ')}
        </motion.span>
        <motion.span 
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="text-white/30 text-[10px] font-bold tracking-widest uppercase"
        >
          {t('difficulty')}: {question.difficulty}
        </motion.span>
      </div>

      <motion.h2 layout className="text-2xl md:text-3xl font-bold text-white mb-10 leading-[1.2] text-center">
        {question.text}
      </motion.h2>

      <div className="grid grid-cols-1 gap-3">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <motion.button
              key={idx}
              whileHover={!selected ? { scale: 1.02, x: 5 } : {}}
              whileTap={!selected ? { scale: 0.98 } : {}}
              onPointerDown={() => !selected && playSound(clickSound.current)}
              onClick={() => handleSelect(option)}
              disabled={disabled || !!selected}
              className={`
                group relative p-5 rounded-2xl text-left font-bold transition-all duration-300 border
                ${!selected ? 'bg-white/5 border-white/5 text-white/80' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_0_30px_rgba(16,185,129,0.4)]' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_30px_rgba(244,63,94,0.4)]' : ''}
                ${showCorrectIfMissed ? 'border-emerald-500/50 text-emerald-400 bg-emerald-500/5' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-20 border-transparent grayscale' : ''}
              `}
            >
              <div className="flex items-center space-x-4">
                <span className={`w-10 h-10 flex items-center justify-center rounded-xl font-black text-sm transition-colors
                  ${isSelected ? 'bg-black/20' : 'bg-black/40 text-emerald-500'}
                `}>
                  {String.fromCharCode(65 + idx)}
                </span>
                <span className="text-lg">{option}</span>
              </div>

              {isCorrect && (
                <motion.div 
                  initial={{ opacity: 0, scale: 0 }}
                  animate={{ opacity: 1, scale: 1.2 }}
                  className="absolute right-6 top-1/2 -translate-y-1/2 text-white font-black italic tracking-tighter"
                >
                  {t('correct')}
                </motion.div>
              )}
            </motion.button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected && question.explanation && (
           <motion.div 
             initial={{ opacity: 0, height: 0, marginTop: 0 }}
             animate={{ opacity: 1, height: 'auto', marginTop: 40 }}
             exit={{ opacity: 0, height: 0 }}
             className="p-5 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl overflow-hidden shadow-inner"
           >
              <p className="text-emerald-300 text-base leading-relaxed text-center font-medium">
                {question.explanation}
              </p>
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default QuizCard;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Category, Question, GameState, LevelConfig, Language, LeaderboardEntry } from './types';
