  correctAnswersLabel: { Bosanski: "Tačnih Odgovora", English: "Correct Answers", Deutsch: "Richtige Antworten" },
  totalScoreLabel: { Bosanski: "Ukupni Skor", English: "Total Score", Deutsch: "Gesamtpunktzahl" },
