                {Object.values(Category).map((cat) => (
                  <motion.button
                    key={cat}
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={() => handleStartQuiz(cat)}
                    className={`p-6 rounded-2xl border font-bold text-center transition-all ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 text-white col-span-full' : 'bg-white/5 border-white/10 text-white/80 hover:bg-white/10'}`}
                  >
                    {catT(cat)}
                  </motion.button>
                ))}
             </div>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="min-h-screen p-4 md:p-8 flex flex-col">
