                <div>
                  <h1 className="text-white font-bold leading-tight">TAP FOOTBALL</h1>
                  <p className="text-emerald-400 text-[9px] font-black uppercase tracking-widest">{catT(gameState.selectedCategory)}</p>
                </div>
              </div>
              <div className="flex items-center space-x-8">
                <div className="text-center"><p className="text-white/40 text-[9px] font-bold uppercase">{t('score')}</p><p className="text-xl font-black text-yellow-400">{gameState.score}</p></div>
                <div className="text-center"><p className="text-white/40 text-[9px] font-bold uppercase">{t('progress')}</p><p className="text-xl font-black text-emerald-400">{gameState.questionsAnswered}/30</p></div>
              </div>
            </header>
            <div className="max-w-4xl w-full mx-auto mb-8 h-1.5 bg-white/5 rounded-full overflow-hidden">
              <motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${levelProgress}%` }} />
            </div>
            <main className="flex-1 flex flex-col items-center justify-center">
              <AnimatePresence mode="wait">
                {loading && questions.length <= currentQuestionIndex ? (
                  <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center">
                    <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-white/60 font-medium text-xs tracking-widest uppercase">{t('generating')}</p>
                  </motion.div>
                ) : questions[currentQuestionIndex] ? (
                  <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={false} isMuted={isMuted} language={gameState.language} />
                ) : null}
              </AnimatePresence>
            </main>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Category, Question, GameState, LevelConfig, Language, LeaderboardEntry } from './types';
import { generateQuestions } from './services/geminiService';
import QuizCard from './components/QuizCard';

const LEVELS: LevelConfig[] = [
