                <button onClick={() => setIsMuted(!isMuted)} className="ml-1 p-1.5 rounded-full bg-white/5 text-white">
                  {isMuted ? <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1V10a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" /></svg> : <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1V10a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>}
                </button>
              </div>
            </div>

            <div className="text-center mb-12 mt-12">
              <h1 className="text-3xl md:text-5xl font-black text-white mb-4 tracking-tighter uppercase">TAP FOOTBALL <span className="text-emerald-500">2026</span></h1>
              <p className="text-sm md:text-base text-white/70 max-w-sm mx-auto font-medium">{t('subTitle')}</p>
