import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Question, Language } from '../types';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
  isMuted: boolean;
  language: Language;
}

const TRANSLATIONS = {
  correct: { Bosanski: "TAČNO!", English: "CORRECT!", Deutsch: "RICHTIG!" },
  difficulty: { Bosanski: "TEŽINA", English: "DIFFICULTY", Deutsch: "SCHWIERIGKEIT" }
};

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled, isMuted, language }) => {
  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);

  const clickSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/15/audio_c8c8a73456.mp3'));
  const correctSound = useRef(new Audio('https://cdn.pixabay.com/audio/2021/08/04/audio_0625c1539c.mp3'));
  // Korištenje robusnijeg fail zvuka
  const wrongSound = useRef(new Audio('https://cdn.pixabay.com/audio/2021/08/04/audio_bbdec0463c.mp3'));

  const playSound = (audio: HTMLAudioElement) => {
    if (!isMuted) {
      audio.currentTime = 0;
      audio.volume = 0.5;
      audio.play().catch(e => console.log("Sound play blocked"));
    }
  };

  const handleSelect = (option: string) => {
    if (disabled || selected) return;

    const correct = option === question.correctAnswer;
    setSelected(option);

    if (correct) {
      playSound(correctSound.current);
    } else {
      setIsWrong(true);
      playSound(wrongSound.current);
    }

    // Pauza prije sljedećeg pitanja
    setTimeout(() => {
        onAnswer(option);
        setSelected(null);
        setIsWrong(false);
    }, 4000);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 30, scale: 0.95 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}
      className={`w-full max-w-xl mx-auto bg-black/70 backdrop-blur-2xl rounded-[2rem] p-6 md:p-10 shadow-2xl border border-white/10 ${isWrong ? 'animate-shake border-rose-500/40' : ''}`}
    >
      <div className="flex justify-between items-center mb-6">
        <motion.span 
          initial={{ opacity: 0, x: -10 }}
          animate={{ opacity: 1, x: 0 }}
          className="px-4 py-1 bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 rounded-full text-[9px] font-black tracking-widest uppercase"
        >
          {question.category.replace('_', ' ')}
        </motion.span>
        <motion.span 
          initial={{ opacity: 0, x: 10 }}
          animate={{ opacity: 1, x: 0 }}
          className="text-white/20 text-[8px] font-black tracking-widest uppercase"
        >
          {t('difficulty')}: {question.difficulty}
        </motion.span>
      </div>

      <motion.h2 layout className="text-xl md:text-2xl font-bold text-white mb-8 leading-snug text-center tracking-tight">
        {question.text}
      </motion.h2>

      <div className="grid grid-cols-1 gap-2.5">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <motion.button
              key={idx}
              whileHover={!selected ? { scale: 1.01, x: 4 } : {}}
              whileTap={!selected ? { scale: 0.98 } : {}}
              onPointerDown={() => !selected && playSound(clickSound.current)}
              onClick={() => handleSelect(option)}
              disabled={disabled || !!selected}
              className={`
                group relative p-4 rounded-2xl text-left font-bold transition-all duration-200 border text-sm
                ${!selected ? 'bg-white/5 border-white/5 text-white/70 hover:border-white/20' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_0_20px_rgba(16,185,129,0.3)]' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_20px_rgba(244,63,94,0.3)]' : ''}
                ${showCorrectIfMissed ? 'border-emerald-500/30 text-emerald-400 bg-emerald-500/5' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-20 border-transparent' : ''}
              `}
            >
              <div className="flex items-center space-x-3">
                <span className={`w-8 h-8 flex items-center justify-center rounded-lg font-black text-xs transition-colors
                  ${isSelected ? 'bg-black/20' : 'bg-black/40 text-emerald-500'}
                `}>
                  {String.fromCharCode(65 + idx)}
                </span>
                <span className="text-base">{option}</span>
              </div>

              {isCorrect && (
                <motion.div 
                  initial={{ opacity: 0, scale: 0 }}
                  animate={{ opacity: 1, scale: 1.1 }}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-white font-black italic tracking-tighter text-xs"
                >
                  {t('correct')}
                </motion.div>
              )}
            </motion.button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected && question.explanation && (
           <motion.div 
             initial={{ opacity: 0, height: 0, marginTop: 0 }}
             animate={{ opacity: 1, height: 'auto', marginTop: 30 }}
             exit={{ opacity: 0, height: 0 }}
             className="p-4 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl overflow-hidden"
           >
              <p className="text-emerald-300 text-xs md:text-sm leading-relaxed text-center font-medium opacity-90">
                {question.explanation}
              </p>
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default QuizCard;

import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";
import { LOCAL_QUESTIONS } from "../data/localQuestions";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getDefaultExplanation = (lang: Language): string => {
  const map: Record<Language, string> = {
    'Bosanski': 'Ovo je tačan odgovor na osnovu sportskih činjenica.',
    'English': 'This is the correct answer based on sports facts.',
    'Deutsch': 'Dies ist die richtige Antwort basierend auf sportlichen Fakten.'
  };
  return map[lang] || map['English'];
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number): Question[] => {
  // Ensure we have a valid language pool
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'];

  // Filter by category if specific, otherwise take all available for that language
  let filtered = langPool.filter(q => category === Category.ALL || q.category === category);

  // Fallback to all questions if specific category empty
  if (filtered.length === 0) {
    filtered = langPool;
  }

  const shuffled = [...filtered].sort(() => 0.5 - Math.random());

  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: `offline-${Date.now()}-${Math.random()}`,
    difficulty: difficulty, // Assign the requested difficulty level for scoring consistency
    explanation: q.explanation || getDefaultExplanation(language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<{ questions: Question[], isOffline: boolean }> => {

  // Quick check for internet connection
  if (!navigator.onLine) {
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }

  const prompt = `Generiši ${count} fudbalskih pitanja na jeziku: ${language}. 
  Kategorija: ${category}. 
  Težina: ${difficulty} (od 1-lakše do 10-teže). 
  Svako pitanje mora imati 4 opcije i tačan odgovor. 
  Takođe obavezno dodaj polje "explanation" sa kratkim objašnjenjem zašto je taj odgovor tačan na istom jeziku (${language}).`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response");

    const parsed = JSON.parse(text);
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.warn("Gemini API error, falling back to offline mode:", error);
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }
};

