  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);

  // Fix: Replaced NodeJS.Timeout with ReturnType<typeof setInterval> to fix namespace error in browser environment
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const clickSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/15/audio_c8c8a73456.mp3'));
  const correctSound = useRef(new Audio('https://cdn.pixabay.com/audio/2021/08/04/audio_0625c1539c.mp3'));
  const wrongSound = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/clang_and_wobble.ogg'));
  const tickSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/10/audio_5e4125f49e.mp3')); // Soft tick

  const playSound = (audio: HTMLAudioElement) => {
    if (!isMuted) {
      audio.currentTime = 0;
      audio.volume = 0.4;
      audio.play().catch(e => console.log("Sound play blocked"));
    }
  };

  useEffect(() => {
    // Reset timer on new question
    setTimeLeft(10);
    if (timerRef.current) clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          handleTimeout();
          return 0;
        }
        if (prev <= 4) playSound(tickSound.current); // Tick on last 3 seconds
        return prev - 1;
      });
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [question.id]);

  const handleTimeout = () => {
    if (selected) return;
    setIsWrong(true);
    playSound(wrongSound.current);
    setSelected(""); // Trigger result state with empty (wrong) answer

    setTimeout(() => {
      onAnswer("");
      setSelected(null);
      setIsWrong(false);
    }, 3000);
  };

  const handleSelect = (option: string) => {
    if (disabled || selected || timeLeft <= 0) return;

    if (timerRef.current) clearInterval(timerRef.current);

    const correct = option === question.correctAnswer;
    setSelected(option);

    if (correct) {
      playSound(correctSound.current);
    } else {
      setIsWrong(true);
      playSound(wrongSound.current);
    }

    setTimeout(() => {
        onAnswer(option);
        setSelected(null);
        setIsWrong(false);
    }, 3500);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 30, scale: 0.95 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, scale: 0.9 }}
      className={`relative w-full max-w-xl mx-auto bg-black/80 backdrop-blur-2xl rounded-[2.5rem] p-6 md:p-10 shadow-2xl border border-white/10 ${isWrong ? 'animate-shake border-rose-500/40' : 'border-white/10'}`}
    >
      {/* Timer Bar */}
      <div className="absolute top-0 left-0 w-full h-1.5 overflow-hidden rounded-t-[2.5rem]">
        <motion.div 
          className={`h-full ${timeLeft <= 3 ? 'bg-rose-500' : 'bg-emerald-500'}`}
          initial={{ width: "100%" }}
          animate={{ width: selected ? "0%" : `${(timeLeft / 10) * 100}%` }}
          transition={{ duration: selected ? 0 : 1, ease: "linear" }}
        />
      </div>

      <div className="flex justify-between items-center mb-6">
        <span className="px-4 py-1.5 bg-white/5 text-white/50 border border-white/10 rounded-full text-[9px] font-black tracking-widest uppercase">
          {question.category.replace('_', ' ')}
        </span>
        <div className="flex items-center space-x-4">
           {/* Time indicator */}
           <div className={`flex items-center space-x-1 ${timeLeft <= 3 ? 'text-rose-500' : 'text-white/40'}`}>
             <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
             <span className="text-[10px] font-black tracking-widest">{timeLeft}s</span>
           </div>

           <div className="flex items-center space-x-2">
             <span className="text-white/20 text-[8px] font-black tracking-widest uppercase">{t('difficulty')}</span>
             <div className="flex space-x-0.5">
               {[...Array(10)].map((_, i) => (
                 <div key={i} className={`w-1.5 h-3 rounded-sm ${i < question.difficulty ? (question.difficulty > 7 ? 'bg-rose-500' : 'bg-emerald-500') : 'bg-white/5'}`} />
               ))}
             </div>
           </div>
        </div>
      </div>

      <h2 className="text-xl md:text-2xl font-bold text-white mb-8 leading-snug text-center tracking-tight min-h-[4rem]">
        {question.text}
      </h2>

      <div className="grid grid-cols-1 gap-3">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <motion.button
              key={idx}
              whileHover={!selected ? { scale: 1.01 } : {}}
              whileTap={!selected ? { scale: 0.98 } : {}}
              onClick={() => handleSelect(option)}
              disabled={disabled || !!selected || timeLeft <= 0}
              className={`
                group relative p-4 rounded-2xl text-left font-bold transition-all duration-300 border text-sm flex items-center
                ${!selected ? 'bg-white/5 border-white/5 text-white/70 hover:bg-white/10 hover:border-white/20' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_0_25px_rgba(16,185,129,0.4)]' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_25px_rgba(244,63,94,0.4)]' : ''}
                ${showCorrectIfMissed ? 'border-emerald-500/50 text-emerald-400 bg-emerald-500/10' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-20 grayscale' : ''}
              `}
            >
              <span className={`w-8 h-8 flex items-center justify-center rounded-lg font-black text-xs mr-4 transition-colors
                ${isSelected ? 'bg-black/20' : 'bg-black/40 text-white/40'}
              `}>
                {String.fromCharCode(65 + idx)}
              </span>
              <span className="text-base flex-1">{option}</span>

              {isCorrect && <span className="ml-2 text-[10px] font-black">{t('correct')}</span>}
              {isWrongOption && <span className="ml-2 text-[10px] font-black">{t('wrong')}</span>}
            </motion.button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected && (
           <motion.div 
             initial={{ opacity: 0, y: 10 }}
             animate={{ opacity: 1, y: 0 }}
             className="mt-8 p-5 bg-white/5 border border-white/5 rounded-2xl"
           >
              {selected === "" && (
                <p className="text-rose-500 font-black text-center text-xs mb-2 uppercase tracking-widest">{t('timesUp')}</p>
              )}
              {question.explanation && (
                <p className="text-white/60 text-xs md:text-sm leading-relaxed text-center font-medium italic">
                  "{question.explanation}"
                </p>
              )}
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default QuizCard;

import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";
import { LOCAL_QUESTIONS } from "../data/localQuestions";

// Fix: Initializing GoogleGenAI using process.env.API_KEY directly as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDefaultExplanation = (lang: Language): string => {
  const map: Record<Language, string> = {
    'Bosanski': 'Ovo je tačan odgovor na osnovu sportskih činjenica.',
    'English': 'This is the correct answer based on sports facts.',
    'Deutsch': 'Dies ist die richtige Antwort basierend auf sportlichen Fakten.'
  };
  return map[lang] || map['English'];
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number): Question[] => {
  // Ensure we have a valid language pool
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'];

  // Filter by category if specific, otherwise take all available for that language
  let filtered = langPool.filter(q => category === Category.ALL || q.category === category);

  // Fallback to all questions if specific category empty
  if (filtered.length === 0) {
    filtered = langPool;
  }

  const shuffled = [...filtered].sort(() => 0.5 - Math.random());

  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: `offline-${Date.now()}-${Math.random()}`,
    difficulty: difficulty, // Assign the requested difficulty level for scoring consistency
    explanation: q.explanation || getDefaultExplanation(language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<{ questions: Question[], isOffline: boolean }> => {

  // Quick check for internet connection
  if (!navigator.onLine) {
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }

  const prompt = `Generiši ${count} fudbalskih pitanja na jeziku: ${language}. 
  Kategorija: ${category}. 
  Težina: ${difficulty} (od 1-lakše do 10-teže). 
  Svako pitanje mora imati 4 opcije i tačan odgovor. 
  Takođe obavezno dodaj polje "explanation" sa kratkim objašnjenjem zašto je taj odgovor tačan na istom jeziku (${language}).`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    // Fix: Access response.text directly (property access) as per guidelines
    const text = response.text;
    if (!text) throw new Error("Empty response");

    const parsed = JSON.parse(text);
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.warn("Gemini API error, falling back to offline mode:", error);
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }
};

