  const timesUpSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/24/audio_98319f7278.mp3'));
  const whooshSound = useRef(new Audio('https://cdn.pixabay.com/audio/2022/03/15/audio_73147895e7.mp3'));

  const playSound = (audio: HTMLAudioElement) => {
    if (!isMuted) {
      audio.currentTime = 0;
      audio.volume = 0.4;
      audio.play().catch(e => console.log("Sound play blocked"));
    }
  };

  useEffect(() => {
    setTimeLeft(10);
    if (timerRef.current) clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          handleTimeout();
          return 0;
        }
        if (prev <= 4) playSound(tickSound.current);
        return prev - 1;
      });
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [question.id]);

  const handleTimeout = () => {
    if (selected) return;
    setIsWrong(true);
    playSound(timesUpSound.current);
    playSound(wrongSound.current);
    setSelected("");

    setTimeout(() => {
      onAnswer("");
      setSelected(null);
      setIsWrong(false);
    }, 3000);
