  [Category.COACHES]: { Bosanski: "TRENERI", English: "COACHES", Deutsch: "TRAINER" },
  [Category.ALL]: { Bosanski: "SVE", English: "ALL", Deutsch: "ALLE" }
};

const TRANSLATIONS = {
  score: { Bosanski: "BODOVI", English: "SCORE", Deutsch: "PUNKTE" },
  progress: { Bosanski: "PROGRES", English: "PROGRESS", Deutsch: "FORTSCHRITT" },
  gameOver: { Bosanski: "KRAJ!", English: "OVER!", Deutsch: "ENDE!" },
  success: { Bosanski: "BRAVO!", English: "WIN!", Deutsch: "SIEG!" },
  finishedLevel: { Bosanski: "Nivo", English: "Level", Deutsch: "Level" },
  correctAnswersLabel: { Bosanski: "Tačno", English: "Correct", Deutsch: "Richtig" },
  totalScoreLabel: { Bosanski: "Ukupno", English: "Total", Deutsch: "Gesamt" },
  playAgain: { Bosanski: "PONAVI", English: "RETRY", Deutsch: "ZURÜCK" },
