const TRANSLATIONS = {
  score: { Bosanski: "BODOVI", English: "SCORE", Deutsch: "PUNKTE" },
  progress: { Bosanski: "PROGRES", English: "PROGRESS", Deutsch: "FORTSCHRITT" },
