const BASE_MOCK_LEADERBOARD: LeaderboardEntry[] = [
  { name: "Edin_Dž", score: 2850, country: "🇧🇦" },
  { name: "Marco_R", score: 2720, country: "🇩🇪" },
  { name: "Luka_M", score: 2540, country: "🇭🇷" },
];

const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => {
    const saved = localStorage.getItem('quiz_muted');
    return saved ? JSON.parse(saved) : false;
  });

  const [levels, setLevels] = useState<LevelConfig[]>(() => {
    const saved = localStorage.getItem('quiz_levels');
    return saved ? JSON.parse(saved) : INITIAL_LEVELS;
  });

  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    const saved = localStorage.getItem('quiz_leaderboard');
    return saved ? JSON.parse(saved) : BASE_MOCK_LEADERBOARD;
  });

  const [hasInteracted, setHasInteracted] = useState(false);
  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'Bosanski',
    history: [],
  });

  const [step, setStep] = useState<'HOME' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [levelProgress, setLevelProgress] = useState(0);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => localStorage.setItem('quiz_muted', JSON.stringify(isMuted)), [isMuted]);
  useEffect(() => localStorage.setItem('quiz_levels', JSON.stringify(levels)), [levels]);
  useEffect(() => localStorage.setItem('quiz_nickname', gameState.nickname), [gameState.nickname]);

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number, history: GameState['history']) => {
    setLoading(true);
    const finalCategory = category === Category.ALL 
      ? Object.values(Category).filter(c => c !== Category.ALL)[Math.floor(Math.random() * 5)]
      : category;

    const baseDiff = (levels.find(l => l.id === level) || levels[0]).minDifficulty;
    const result = await generateQuestions(finalCategory, baseDiff, lang, 5);

    setQuestions(prev => [...prev, ...result.questions]);
    setIsOffline(result.isOffline);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.history);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, gameState.history, fetchBatch]);

  useEffect(() => {
    if (!audioRef.current) {
      audioRef.current = new Audio('https://cdn.pixabay.com/audio/2022/01/18/audio_d0a13f69d2.mp3');
      audioRef.current.loop = true;
      audioRef.current.volume = 0.05;
    }
    if (hasInteracted && !isMuted && step !== 'QUIZ') {
      audioRef.current.play().catch(() => {});
    } else {
      audioRef.current.pause();
    }
  }, [isMuted, step, hasInteracted]);

  const handleStartQuiz = (category: Category) => {
    setGameState(prev => ({ ...prev, selectedCategory: category, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
    setLevelProgress(0);
    setHasInteracted(true);
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const points = isCorrect ? (currentQ.difficulty || 1) * 10 : 0;
    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isWon = (gameState.questionsAnswered + 1 >= 30) && newMistakes < 5;
    const isLost = newMistakes >= 5;
    const isOver = isWon || isLost;

    if (isOver) {
      const finalScore = gameState.score + points;
      setLeaderboard(prev => {
        const name = gameState.nickname || 'Player';
        const updated = [...prev, { name, score: finalScore, country: '👤', isUser: true }];
        return updated.sort((a, b) => b.score - a.score).slice(0, 10);
      });
      if (isWon) {
        setLevels(prev => prev.map(lvl => lvl.id === gameState.currentLevel + 1 ? { ...lvl, unlocked: true } : lvl));
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      history: [...prev.history, { questionId: currentQ.id, isCorrect }],
      isGameOver: isOver
    }));

    setLevelProgress(((gameState.questionsAnswered + 1) / 30) * 100);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];

  // Helper for accuracy
  const accuracy = gameState.questionsAnswered > 0 
    ? Math.round((gameState.correctAnswers / gameState.questionsAnswered) * 100) 
    : 0;

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white">
      <AnimatePresence mode="wait">
        {gameState.isGameOver ? (
          <motion.div 
            key="game-over" 
            initial={{ opacity: 0, y: 50 }} 
            animate={{ opacity: 1, y: 0 }} 
            exit={{ opacity: 0 }} 
            className="flex-1 flex flex-col items-center justify-center p-6"
          >
            <div className={`bg-black/80 backdrop-blur-3xl p-8 rounded-[2.5rem] border ${gameState.mistakes >= 5 ? 'border-rose-500/20 shadow-rose-500/10' : 'border-emerald-500/20 shadow-emerald-500/10'} text-center w-full max-sm shadow-2xl relative overflow-hidden`}>
              <div className={`absolute top-0 left-0 w-full h-1 ${gameState.mistakes >= 5 ? 'bg-rose-500' : 'bg-emerald-500'}`} />

              <motion.div 
                initial={{ scale: 0 }} 
                animate={{ scale: 1 }} 
                transition={{ type: 'spring', damping: 10, stiffness: 100, delay: 0.2 }}
                className="mb-4 text-4xl"
              >
                {gameState.mistakes >= 5 ? '💔' : '🏆'}
              </motion.div>

              <h1 className={`text-3xl font-black mb-1 uppercase tracking-tighter ${gameState.mistakes >= 5 ? 'text-rose-500' : 'text-emerald-400'}`}>
                {gameState.mistakes >= 5 ? t('gameOver') : t('success')}
              </h1>
              <p className="text-[12px] text-white/40 mb-8 font-bold tracking-widest uppercase">
                {t('finishedLevel')} {gameState.currentLevel}
              </p>

              <div className="grid grid-cols-2 gap-3 mb-8">
                <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                  <p className="text-[8px] font-black text-white/30 uppercase mb-1">{t('correctAnswersLabel')}</p>
                  <p className="text-xl font-black text-emerald-400">{gameState.correctAnswers}</p>
                </div>
                <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                  <p className="text-[8px] font-black text-white/30 uppercase mb-1">{t('attemptedLabel')}</p>
                  <p className="text-xl font-black text-white/60">{gameState.questionsAnswered}</p>
                </div>
                <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                  <p className="text-[8px] font-black text-white/30 uppercase mb-1">{t('accuracyLabel')}</p>
                  <p className="text-xl font-black text-blue-400">{accuracy}%</p>
                </div>
                <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                  <p className="text-[8px] font-black text-white/30 uppercase mb-1">{t('totalScoreLabel')}</p>
                  <p className="text-xl font-black text-yellow-400">{gameState.score}</p>
                </div>
              </div>

              <motion.button 
                whileTap={{ scale: 0.95 }}
                onClick={() => setStep('HOME')} 
                className={`w-full ${gameState.mistakes >= 5 ? 'bg-rose-600' : 'bg-emerald-500'} text-white font-black py-4 rounded-2xl shadow-xl uppercase text-[10px] tracking-[0.2em] transition-all`}
              >
                {t('playAgain')}
              </motion.button>
            </div>
          </motion.div>
        ) : step === 'HOME' ? (
          <motion.div key="home" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center pt-6 p-4">

            <div className="w-full flex justify-between items-center mb-10 px-2">
              <button onClick={() => setIsMuted(!isMuted)} className="text-lg opacity-40 hover:opacity-100 transition-all active:scale-90">{isMuted ? '🔇' : '🔊'}</button>
              <div className="flex gap-1 bg-black/40 p-1 rounded-full border border-white/5 backdrop-blur-md">
                {(['Bosanski', 'English', 'Deutsch'] as Language[]).map(lang => (
                  <button key={lang} onClick={() => { setGameState(prev => ({ ...prev, language: lang })); setHasInteracted(true); }} 
                    className={`px-3 py-1 rounded-full text-[8px] font-black transition-all ${gameState.language === lang ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'text-white/20'}`}>
                    {lang.substring(0, 2).toUpperCase()}
                  </button>
                ))}
              </div>
            </div>

            <div className="text-center mb-8">
              <h1 className="text-4xl font-black tracking-tighter uppercase leading-none mb-1">TAP FOOTBALL</h1>
              <p className="text-[9px] font-bold text-emerald-500 tracking-[0.3em] uppercase">{t('subTitle')}</p>
            </div>

            <div className="w-full max-w-xs space-y-2.5 mb-8">
              {levels.map((level) => (
                <motion.div 
                  key={level.id} 
                  whileTap={level.unlocked ? { scale: 0.98 } : {}}
                  onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} 
                  className={`relative p-5 rounded-[1.5rem] border transition-all cursor-pointer ${level.unlocked ? 'bg-black/60 border-white/10 active:border-emerald-500/50' : 'bg-black/20 border-white/5 opacity-30 cursor-not-allowed'}`}
                >
                  <div className="flex justify-between items-center">
                    <div>
                      <span className="text-white/20 text-[7px] font-black uppercase tracking-widest mb-0.5 block">LVL {level.id}</span>
                      <h2 className="text-sm font-black uppercase tracking-tight">{level.name[gameState.language]}</h2>
                    </div>
                    {level.unlocked ? <span className="text-emerald-500 text-xs font-black">START</span> : <span className="text-white/20 text-xs">🔒</span>}
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="w-full max-w-xs bg-black/40 backdrop-blur-xl rounded-[1.5rem] border border-white/5 p-5">
              <h3 className="text-white/30 font-black text-[8px] tracking-[0.2em] uppercase text-center mb-4">{t('leaderboard')}</h3>
              <div className="space-y-2">
                {leaderboard.slice(0, 3).map((user, i) => (
                  <div key={i} className={`flex items-center justify-between p-2.5 rounded-xl bg-white/5 border border-white/5`}>
                    <div className="flex items-center space-x-2">
                      <span className="text-white/20 font-black text-[9px]">#{i+1}</span>
                      <span className="text-sm">{user.country}</span>
                      <span className="font-bold text-[10px] truncate max-w-[80px]">{user.name}</span>
                    </div>
                    <span className="text-emerald-500 font-black text-[10px]">{user.score}</span>
                  </div>
                ))}
              </div>
            </div>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nickname" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="bg-black/60 backdrop-blur-3xl p-8 rounded-[2.5rem] border border-white/10 text-center w-full max-w-sm shadow-2xl">
              <h2 className="text-xl font-black mb-6 uppercase tracking-tight">{t('enterNickname')}</h2>
              <input 
                type="text" 
                value={gameState.nickname} 
                onChange={(e) => setGameState(prev => ({ ...prev, nickname: e.target.value.substring(0, 15) }))} 
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-base font-bold mb-6 focus:outline-none focus:border-emerald-500 text-center transition-all" 
              />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} className={`w-full font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest transition-all ${gameState.nickname.trim() ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-white/5 text-white/20'}`}>
                {t('start')}
              </button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat-select" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
             <h2 className="text-xl font-black mb-8 uppercase tracking-tighter text-white/60">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-3 w-full max-w-xs">
                {Object.values(Category).map((cat) => (
                  <motion.button 
                    key={cat} 
                    whileTap={{ scale: 0.95 }}
                    onClick={() => handleStartQuiz(cat)} 
                    className={`p-4 rounded-2xl border font-black text-[8px] uppercase tracking-widest transition-all ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 text-white col-span-2 shadow-lg shadow-emerald-500/20' : 'bg-white/5 border-white/5 text-white/40 hover:bg-white/10'}`}
                  >
                    {CATEGORY_TRANSLATIONS[cat][gameState.language]}
                  </motion.button>
                ))}
             </div>
             <button onClick={() => setStep('HOME')} className="mt-8 text-[9px] font-black text-white/20 uppercase tracking-[0.2em] active:text-white transition-all">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-md mx-auto">
            <header className="flex justify-between items-center mb-3 bg-black/60 p-3 rounded-2xl border border-white/10 backdrop-blur-xl">
              <button onClick={() => setStep('HOME')} className="text-[8px] font-black text-white/40 bg-white/5 px-2.5 py-2 rounded-xl transition-all active:scale-90">NAZAD</button>
              <div className="flex space-x-4">
                <div className="text-center">
                  <p className="text-white/20 text-[6px] font-black uppercase mb-0.5">{t('lives')}</p>
                  <p className="text-[10px] tracking-tighter">{[...Array(5)].map((_, i) => (i < (5 - gameState.mistakes) ? '❤️' : '🖤'))}</p>
                </div>
                <div className="text-center">
                  <p className="text-white/20 text-[6px] font-black uppercase mb-0.5">{t('score')}</p>
                  <p className="text-[10px] font-black text-yellow-400 leading-none">{gameState.score}</p>
                </div>
                <div className="text-center">
                  <p className="text-white/20 text-[6px] font-black uppercase mb-0.5">Q</p>
                  <p className="text-[10px] font-black text-emerald-400 leading-none">{gameState.questionsAnswered}/30</p>
                </div>
              </div>
            </header>

            <div className="w-full mb-5 h-1 bg-white/5 rounded-full overflow-hidden">
              <motion.div className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]" initial={{ width: 0 }} animate={{ width: `${levelProgress}%` }} />
            </div>

            <main className="flex-1 flex items-center justify-center">
              <AnimatePresence mode="wait">
                {loading && questions.length <= currentQuestionIndex ? (
                  <div className="text-center p-8 bg-black/20 rounded-3xl backdrop-blur-md border border-white/5">
                    <div className="w-8 h-8 border-3 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
                    <p className="text-white/30 text-[9px] font-black uppercase tracking-[0.3em]">{t('generating')}</p>
                  </div>
                ) : questions[currentQuestionIndex] ? (
                  <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={false} isMuted={isMuted} language={gameState.language} />
                ) : null}
              </AnimatePresence>
            </main>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Footer copyright */}
      <footer className="w-full py-4 text-center">
        <p className="text-[7px] font-black text-white/10 uppercase tracking-[0.3em]">
          tapfootball@gmail.com
        </p>
      </footer>
    </div>
  );
};

export default App;

