  refreshing: { Bosanski: "...", English: "...", Deutsch: "..." },
  subTitle: { 
    Bosanski: "Vrhunski fudbalski kviz", 
    English: "The ultimate football quiz", 
    Deutsch: "Das ultimative Fußball-Quiz" 
  }
