const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => JSON.parse(localStorage.getItem('quiz_levels') || JSON.stringify(INITIAL_LEVELS)));
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => JSON.parse(localStorage.getItem('quiz_leaderboard') || '[]'));
  const [hasInteracted, setHasInteracted] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [showCopied, setShowCopied] = useState(false);
  const [loading, setLoading] = useState(false);

  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'Bosanski',
    history: [],
  });

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  // Sync state
  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    localStorage.setItem('quiz_levels', JSON.stringify(levels));
  }, [levels]);

  useEffect(() => {
    localStorage.setItem('quiz_nickname', gameState.nickname);
  }, [gameState.nickname]);

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number) => {
    setLoading(true);
    const config = levels.find(l => l.id === level) || levels[0];

    // Scaling difficulty within level
    const progressRatio = progress / 30;
    const dynamicDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
    );

    const finalCategory = category === Category.ALL 
      ? Object.values(Category).filter(c => c !== Category.ALL)[Math.floor(Math.random() * 5)]
      : category;

    const result = await generateQuestions(finalCategory, dynamicDiff, lang, 5);

    setQuestions(prev => [...prev, ...result.questions]);
    setIsOffline(result.isOffline);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch]);

  useEffect(() => {
    const shouldPlayBg = hasInteracted && step !== 'QUIZ';
    audioService.setBgMusic(shouldPlayBg);
  }, [hasInteracted, step]);

  const handleStartQuiz = (category: Category) => {
    setGameState(prev => ({ 
      ...prev, 
      selectedCategory: category, 
      score: 0, 
      questionsAnswered: 0, 
      correctAnswers: 0, 
      mistakes: 0, 
      isGameOver: false, 
      history: [] 
    }));
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
    setHasInteracted(true);
  };

  const handleRetry = () => {
    handleStartQuiz(gameState.selectedCategory);
  };

  const handleNextLevel = () => {
    if (gameState.currentLevel < INITIAL_LEVELS.length) {
      const nextLvl = gameState.currentLevel + 1;
      setGameState(prev => ({ ...prev, currentLevel: nextLvl }));
      handleStartQuiz(gameState.selectedCategory);
    } else {
      setStep('HOME');
    }
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;

    // Combo system
    const newStreak = isCorrect ? streak + 1 : 0;
    const multiplier = Math.min(3, 1 + Math.floor(newStreak / 5) * 0.5);
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * multiplier) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isWon = (gameState.questionsAnswered + 1 >= 30) && newMistakes < 5;
    const isLost = newMistakes >= 5;
    const isOver = isWon || isLost;

    if (isOver) {
      const finalScore = gameState.score + points;
      setLeaderboard(prev => {
        const name = gameState.nickname || 'Player';
        const updated = [...prev, { name, score: finalScore, country: '👤', isUser: true }];
        const sorted = updated.sort((a, b) => b.score - a.score).slice(0, 10);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(sorted));
        return sorted;
      });
      if (isWon) {
        setLevels(prev => prev.map(lvl => lvl.id === gameState.currentLevel + 1 ? { ...lvl, unlocked: true } : lvl));
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      history: [...prev.history, { questionId: currentQ.id, isCorrect }],
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];
  const accuracy = gameState.questionsAnswered > 0 ? Math.round((gameState.correctAnswers / gameState.questionsAnswered) * 100) : 0;
  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;

  const handleShare = async () => {
    const shareText = TRANSLATIONS.shareText[gameState.language].replace('{score}', gameState.score.toString());
    const currentUrl = window.location.href;
    const isUrlValid = currentUrl.startsWith('http');
    if (navigator.share) {
      try { await navigator.share({ title: 'TAP FOOTBALL QUIZ 2026', text: shareText, ...(isUrlValid ? { url: currentUrl } : {}) }); }
      catch { copyFallback(shareText); }
    } else { copyFallback(shareText); }
  };

  const copyFallback = async (text: string) => {
    try { await navigator.clipboard.writeText(text); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch {}
  };

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white">
      {/* Offline Status */}
      <AnimatePresence>
        {isOffline && (
          <motion.div initial={{ y: -50 }} animate={{ y: 0 }} exit={{ y: -50 }} className="fixed top-0 left-0 w-full z-[100] bg-amber-500/90 backdrop-blur-md px-4 py-2 flex items-center justify-center space-x-3 shadow-lg">
            <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 1.5 }} className="w-2 h-2 rounded-full bg-white" />
            <div className="text-center">
              <span className="text-[10px] font-black text-amber-950 uppercase tracking-[0.1em] block">{t('offlineMode')}</span>
              <span className="text-[7px] font-bold text-amber-900 uppercase opacity-70">{t('offlineDesc')}</span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {gameState.isGameOver ? (
          <motion.div key="game-over" variants={screenVariants} initial="initial" animate="animate" exit="exit" className="flex-1 flex flex-col items-center justify-center p-6 relative">
            {isWin && <Confetti />}
            <div className={`bg-black/95 backdrop-blur-3xl p-8 rounded-[3rem] border ${isWin ? 'border-emerald-500/40' : 'border-rose-500/40'} text-center w-full max-w-md shadow-2xl relative overflow-hidden`}>
              <div className={`absolute top-0 left-0 w-full h-1.5 ${isWin ? 'bg-emerald-500 shadow-[0_0_15px_#10b981]' : 'bg-rose-500 shadow-[0_0_15px_#ef4444]'}`} />
              <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="mb-6 inline-block p-5 bg-white/5 rounded-full border border-white/10 text-5xl">
                {isWin ? '🏆' : '💔'}
              </motion.div>
              <h1 className={`text-4xl font-black mb-1 uppercase tracking-tighter ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>
                {isWin ? t('success') : t('gameOver')}
              </h1>
              <p className="text-[14px] text-white/40 mb-10 font-black uppercase tracking-[0.2em]">
                {isWin ? t('levelUp') : t('failed')}
              </p>
              <div className="grid grid-cols-2 gap-3 mb-10">
                {[
                  { label: t('correctAnswersLabel'), value: gameState.correctAnswers, color: 'text-emerald-400' },
                  { label: t('accuracyLabel'), value: `${accuracy}%`, color: 'text-blue-400' },
                  { label: t('totalScoreLabel'), value: gameState.score, color: 'text-yellow-400' },
                  { label: 'LVL', value: gameState.currentLevel, color: 'text-white/60' }
                ].map(stat => (
                  <div key={stat.label} className="bg-white/5 p-4 rounded-3xl border border-white/5">
                    <span className="text-[8px] font-black text-white/30 uppercase block mb-1">{stat.label}</span>
                    <p className={`text-xl font-black ${stat.color}`}>{stat.value}</p>
                  </div>
                ))}
              </div>
              <div className="space-y-4">
                <button 
                  onClick={isWin ? handleNextLevel : handleRetry} 
                  className={`w-full ${isWin ? 'bg-emerald-500 shadow-emerald-500/30' : 'bg-white text-black'} font-black py-5 rounded-2xl shadow-xl uppercase text-xs tracking-widest active:scale-[0.98] transition-all`}
                >
                  {isWin ? t('nextLevel') : t('retry')}
                </button>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => setStep('HOME')} className="bg-white/5 text-white/70 font-black py-4 rounded-2xl border border-white/10 uppercase text-[10px] tracking-widest active:scale-[0.98] transition-all">
                    {t('playAgain')}
                  </button>
                  <button onClick={handleShare} className="bg-white/5 text-white/70 font-black py-4 rounded-2xl border border-white/10 uppercase text-[10px] tracking-widest active:scale-[0.98] transition-all">
                    {showCopied ? t('copied') : t('shareBtn')}
                  </button>
                </div>
              </div>
            </div>
          </motion.div>
        ) : step === 'HOME' ? (
          <motion.div key="home" variants={screenVariants} initial="initial" animate="animate" exit="exit" className="flex-1 flex flex-col items-center pt-12 p-4">
            <div className="w-full flex justify-between items-center mb-10 px-4 max-w-sm">
              <button onClick={() => setIsMuted(!isMuted)} className="text-xl active:scale-90 transition-all">{isMuted ? '🔇' : '🔊'}</button>
              <div className="flex gap-1 bg-black/40 p-1 rounded-full border border-white/10 backdrop-blur-md">
                {(['Bosanski', 'English', 'Deutsch'] as Language[]).map(lang => (
                  <button key={lang} onClick={() => { setGameState(prev => ({ ...prev, language: lang })); setHasInteracted(true); }} 
                    className={`px-3 py-1 rounded-full text-[9px] font-black transition-all ${gameState.language === lang ? 'bg-emerald-500 text-white' : 'text-white/30'}`}>
                    {lang.substring(0, 2).toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
            <div className="text-center mb-12">
              <motion.div initial={{ scale: 0.8 }} animate={{ scale: 1 }} className="inline-block mb-4 p-4 bg-emerald-500/10 rounded-full border border-emerald-500/20 shadow-2xl shadow-emerald-500/10">
                <span className="text-4xl">⚽</span>
              </motion.div>
              <h1 className="text-5xl font-black tracking-tighter uppercase leading-none mb-2">TAP FOOTBALL</h1>
              <p className="text-[10px] font-bold text-emerald-500 tracking-[0.4em] uppercase">{t('subTitle')}</p>
            </div>
            <div className="w-full max-w-xs space-y-3 mb-10">
              {levels.map((level) => (
                <motion.div key={level.id} whileHover={level.unlocked ? { x: 5 } : {}} whileTap={level.unlocked ? { scale: 0.98 } : {}}
                  onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} 
                  className={`relative p-5 rounded-[1.8rem] border transition-all cursor-pointer overflow-hidden ${level.unlocked ? 'bg-black/60 border-white/20 shadow-lg active:border-emerald-500' : 'bg-black/20 border-white/5 opacity-40 grayscale cursor-not-allowed'}`}
                >
                  {level.unlocked && <div className="absolute top-0 right-0 p-2 text-[8px] font-black text-emerald-500/40">30 Q</div>}
                  <div className="flex justify-between items-center">
                    <div>
                      <span className="text-white/30 text-[8px] font-black uppercase tracking-widest mb-1 block">LVL {level.id}</span>
                      <h2 className="text-base font-black uppercase tracking-tight">{level.name[gameState.language]}</h2>
                    </div>
                    {level.unlocked ? <span className="w-8 h-8 flex items-center justify-center rounded-full bg-emerald-500 text-white shadow-lg">▶</span> : <span>🔒</span>}
                  </div>
