              <div className="space-y-4">
                <button onClick={isWin ? () => { if (gameState.currentLevel < 3) { setGameState(p => ({...p, currentLevel: p.currentLevel + 1})); handleStartQuiz(gameState.selectedCategory); } else { setStep('HOME'); } } : () => handleStartQuiz(gameState.selectedCategory)} 
