            </main>
          </motion.div>
        )}
      </AnimatePresence>
      <footer className="py-6 text-center mt-auto">
        <p className="text-[8px] font-black text-white/10 uppercase tracking-[0.4em]">TAP FOOTBALL QUIZ 2026</p>
      </footer>
    </div>
  );
};

