class AudioService {
  private sfx: Record<string, HTMLAudioElement> = {};
  private bgMusic: HTMLAudioElement | null = null;
  private isMuted: boolean = false;

  constructor() {
    if (typeof window !== 'undefined') {
      this.sfx.correct = new Audio(SFX_URLS.correct);
      this.sfx.wrong = new Audio(SFX_URLS.wrong);
      this.sfx.tick = new Audio(SFX_URLS.tick);

      this.bgMusic = new Audio(SFX_URLS.bg);
      this.bgMusic.loop = true;
      this.bgMusic.volume = 0.15; // Adjusted for better presence without being distracting
    }
  }

  setMute(muted: boolean) {
    this.isMuted = muted;
    if (this.bgMusic) {
      if (muted) {
        this.bgMusic.pause();
      } else if (this.bgMusic.paused && !muted) {
        // We don't play automatically here as it might trigger before interaction
      }
    }
  }

  playSfx(type: 'correct' | 'wrong' | 'tick', volume: number = 0.3) {
    if (this.isMuted) return;
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
      audio.volume = volume;
      audio.play().catch(err => console.debug('Audio play blocked:', err));
    }
  }

  stopSfx(type: 'correct' | 'wrong' | 'tick') {
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
  }

  setBgMusic(playing: boolean) {
    if (!this.bgMusic) return;
    if (playing && !this.isMuted) {
      this.bgMusic.play().catch(err => {
        console.debug('BG Music blocked or failed:', err);
        // Retry logic is usually handled by subsequent user interactions
      });
    } else {
      this.bgMusic.pause();
    }
  }
}

