              <div className="flex gap-2 bg-black/40 p-2 rounded-full border border-white/10 backdrop-blur-md">
                {(['Bosanski', 'English', 'Deutsch'] as Language[]).map(lang => (
                  <button key={lang} onClick={(e) => { e.stopPropagation(); setGameState(prev => ({ ...prev, language: lang })); handleInteraction(); }} 
                    className={`text-xl p-1 rounded-full transition-all hover:scale-110 active:scale-90 ${gameState.language === lang ? 'bg-emerald-500/20 scale-125' : 'opacity-40'}`}>
                    {LANGUAGE_FLAGS[lang]}
                  </button>
                ))}
