            </div>

            <div className="text-center mb-16">
              <motion.h1 
                initial={{ y: 20, opacity: 0 }} 
                animate={{ y: 0, opacity: 1 }}
                className="text-6xl font-black tracking-tighter uppercase leading-none mb-4"
              >
                TAP FOOTBALL<br/><span className="text-emerald-500">2026</span>
              </motion.h1>
              <p className="text-[12px] font-bold text-white/40 tracking-[0.4em] uppercase">{t('subTitle')}</p>
