            <div className="flex flex-col items-center space-y-8 w-full max-w-xs">
              <motion.button 
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => { handleInteraction(); setStep('LEVEL_SELECT'); }}
