              </motion.button>

              <button 
                onClick={(e) => { e.stopPropagation(); setShowLeaderboard(true); handleInteraction(); }}
                className="group flex items-center space-x-3 bg-white/5 border border-white/10 px-8 py-4 rounded-2xl hover:bg-white/10 active:scale-95 transition-all"
              >
                <span className="text-2xl">🏆</span>
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">{t('leaderboard')}</span>
              </button>
            </div>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" variants={screenVariants} initial="initial" animate="animate" exit="exit" className="flex-1 flex flex-col items-center pt-12 p-4">
             <div className="text-center mb-10">
