             </div>

             <div className="w-full max-w-xs space-y-4">
              {levels.map((level) => (
                <motion.div key={level.id} whileTap={level.unlocked ? { scale: 0.98 } : {}}
                  onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} 
                  className={`relative p-6 rounded-[2rem] border transition-all cursor-pointer ${level.unlocked ? 'bg-black/60 border-white/20 active:border-emerald-500 shadow-xl' : 'bg-black/20 border-white/5 opacity-40 grayscale cursor-not-allowed'}`}
                >
                  <div className="flex justify-between items-center">
                    <div>
                      <span className="text-white/30 text-[8px] font-black uppercase tracking-widest mb-1 block">LEVEL {level.id}</span>
                      <h2 className="text-lg font-black uppercase tracking-tight">{level.name[gameState.language]}</h2>
