                    <div className="flex items-center space-x-3">
                       {level.unlocked ? (
                         <div className="w-10 h-10 rounded-full bg-emerald-500/10 flex items-center justify-center border border-emerald-500/30 text-emerald-500 font-black text-xs">GO</div>
