                </div>
              </div>
              <div className="flex flex-col items-end">
                <p className="text-white/20 text-[7px] font-black uppercase mb-1 tracking-widest">Q {gameState.questionsAnswered + 1}/30</p>
                <div className={`px-2 py-0.5 rounded-full text-[9px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/5 text-white/20'}`}>
                   {t('streak')} x{streak}
                </div>
              </div>
            </header>

            <div className="w-full mb-8 h-1.5 bg-white/5 rounded-full overflow-hidden shadow-inner">
              <motion.div className="h-full bg-emerald-500 shadow-[0_0_15px_#10b981]" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 30) * 100}%` }} />
            </div>

            <main className="flex-1 flex items-center justify-center relative">
              <AnimatePresence mode="wait">
                {loading && questions.length <= currentQuestionIndex ? (
                  <div className="text-center">
                    <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto mb-6" />
                    <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em]">{t('generating')}</p>
                  </div>
                ) : questions[currentQuestionIndex] ? (
                  <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={false} isMuted={isMuted} language={gameState.language} />
                ) : null}
              </AnimatePresence>
            </main>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }} 
            className="fixed inset-0 z-[110] bg-black/90 backdrop-blur-2xl flex flex-col items-center justify-center p-6"
            onClick={() => setShowLeaderboard(false)}
          >
            <motion.div 
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              className="bg-black/60 border border-white/10 w-full max-w-sm rounded-[3rem] p-8 flex flex-col shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="text-center mb-8">
                <span className="text-4xl mb-2 block">🏆</span>
                <h3 className="text-white font-black text-xl tracking-tight uppercase">{t('leaderboard')}</h3>
              </div>

              <div className="space-y-2 flex-1 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                {leaderboard.map((user, i) => (
                  <div key={`${user.timestamp}-${i}`} className={`flex items-center justify-between px-4 py-3 rounded-2xl border ${user.isUser ? 'bg-emerald-500/20 border-emerald-500/40' : 'bg-white/5 border-white/5'}`}>
                    <div className="flex items-center space-x-3">
                      <span className={`font-black text-[10px] w-6 ${i === 0 ? 'text-yellow-400' : i === 1 ? 'text-slate-300' : i === 2 ? 'text-amber-600' : 'text-white/20'}`}>
                        {i + 1}.
                      </span>
                      <div className="flex flex-col">
                        <span className="font-bold text-sm leading-none mb-1">{user.name}</span>
                        <span className="text-[7px] text-white/30 font-black uppercase tracking-wider">{getTimeAgo(user.timestamp, gameState.language)}</span>
                      </div>
                    </div>
                    <span className="text-emerald-400 font-black text-sm">{user.score}</span>
                  </div>
                ))}
              </div>

              <button 
                onClick={() => setShowLeaderboard(false)}
                className="mt-8 w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all"
              >
                {t('close')}
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-6 text-center mt-auto">
        <p className="text-[8px] font-black text-white/10 uppercase tracking-[0.4em]">TAP FOOTBALL QUIZ 2026</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Category, Question, GameState, LevelConfig, Language, LeaderboardEntry } from './types';
import { generateQuestions } from './services/geminiService';
import { audioService } from './services/audioService';
import QuizCard from './components/QuizCard';

const INITIAL_LEVELS: LevelConfig[] = [
