  lives: { Bosanski: "ŽIVOTI", English: "LIVES", Deutsch: "LEBEN" },
  subTitle: { 
    Bosanski: "Vrhunski fudbalski kviz 2026", 
    English: "The ultimate football quiz 2026", 
    Deutsch: "Das ultimative Fußball-Quiz 2026" 
  },
  streak: { Bosanski: "NIZ", English: "STREAK", Deutsch: "STREAK" },
  rank: { Bosanski: "RANK", English: "RANK", Deutsch: "RANK" },
  newRecord: { Bosanski: "NOVI REKORD!", English: "NEW RECORD!", Deutsch: "NEUER REKORD!" },
  justNow: { Bosanski: "SADA", English: "NOW", Deutsch: "JETZT" },
  pickLevel: { Bosanski: "Izaberi nivo", English: "Select Level", Deutsch: "Level wählen" },
  shareBtn: { Bosanski: "PODIJELI REZULTAT", English: "SHARE SCORE", Deutsch: "TEILEN" },
  shareText: {
    Bosanski: "Moj rezultat je {score} u TAP FOOTBALL QUIZ 2026! Možeš li bolje?",
    English: "My score is {score} in TAP FOOTBALL QUIZ 2026! Can you do better?",
    Deutsch: "Mein Punktestand ist {score} in TAP FOOTBALL QUIZ 2026! Kannst du das toppen?"
  },
  copied: { Bosanski: "Kopirano!", English: "Copied!", Deutsch: "Kopiert!" }
};

const LANGUAGE_FLAGS: Record<Language, string> = {
  'Bosanski': '🇧🇦',
  'English': '🇬🇧',
  'Deutsch': '🇩🇪'
};

const CATEGORY_TRANSLATIONS: Record<Category, Record<Language, string>> = {
  [Category.PLAYERS]: { Bosanski: "IGRAČI", English: "PLAYERS", Deutsch: "SPIELER" },
  [Category.STADIUMS]: { Bosanski: "STADIONI", English: "STADIUMS", Deutsch: "STADIEN" },
  [Category.CLUBS]: { Bosanski: "KLUBOVI", English: "CLUBS", Deutsch: "VEREINE" },
  [Category.NATIONAL_TEAMS]: { Bosanski: "REPREZENTACIJE", English: "TEAMS", Deutsch: "TEAMS" },
  [Category.COACHES]: { Bosanski: "TRENERI", English: "COACHES", Deutsch: "TRAINER" },
  [Category.ALL]: { Bosanski: "SVE", English: "ALL", Deutsch: "ALLE" }
};

const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => JSON.parse(localStorage.getItem('quiz_levels') || JSON.stringify(INITIAL_LEVELS)));
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    const saved = localStorage.getItem('quiz_leaderboard');
    return saved ? JSON.parse(saved) : BASE_LEADERBOARD;
  });

  const [hasInteracted, setHasInteracted] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [loading, setLoading] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);

  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'English',
    history: [],
  });

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ' | 'SCREENSHOT_UTILITY'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  const handleInteraction = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.setBgMusic(!isMuted);
    }
  };

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number) => {
    setLoading(true);
    const config = levels.find(l => l.id === level) || levels[0];
    const progressRatio = progress / 30;
    const dynamicDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
    );

    const result = await generateQuestions(category, dynamicDiff, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setIsOffline(result.isOffline);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch]);

  const handleStartQuiz = (category: Category) => {
    handleInteraction();
    setGameState(prev => ({ 
      ...prev, 
      selectedCategory: category, 
      score: 0, 
      questionsAnswered: 0, 
      correctAnswers: 0, 
      mistakes: 0, 
      isGameOver: false, 
      history: [] 
    }));
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;
    const multiplier = Math.min(3, 1 + Math.floor(newStreak / 5) * 0.5);
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * multiplier) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 30) || newMistakes >= 5;

    if (isOver) {
      const finalScore = gameState.score + points;
      const newEntry: LeaderboardEntry = {
        name: gameState.nickname || 'Player',
        score: finalScore,
        country: LANGUAGE_FLAGS[gameState.language],
        timestamp: Date.now(),
        isUser: true
      };
      setLeaderboard(prev => {
        const updated = [...prev, newEntry].sort((a, b) => b.score - a.score).slice(0, 20);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(updated));
        return updated;
      });
      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setLevels(prev => {
          const updated = prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l);
          localStorage.setItem('quiz_levels', JSON.stringify(updated));
          return updated;
        });
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const handleShare = async () => {
    const text = t('shareText').replace('{score}', gameState.score.toString());
    const url = window.location.href;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'TAP FOOTBALL QUIZ 2026',
          text: text,
          url: url,
        });
      } catch (err) {
        console.error('Share failed:', err);
      }
    } else {
      // Fallback: Copy to clipboard
      navigator.clipboard.writeText(`${text} ${url}`);
      alert(t('copied'));
    }
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];
  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;

  // Mock Question for screenshots
  const MOCK_QUESTION: Question = {
    id: 'mock-1',
    category: Category.CLUBS,
    text: "Which club has won the most UEFA Champions League titles as of 2024?",
    options: ["AC Milan", "Liverpool", "Real Madrid", "Bayern Munich"],
    correctAnswer: "Real Madrid",
    difficulty: 5,
    explanation: "Real Madrid holds the record with 15 European Cup/Champions League titles."
  };

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white" onClick={handleInteraction}>
      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div 
            key="landing" 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0, scale: 1.1 }}
            className="flex-1 flex flex-col items-center justify-center p-6 relative"
          >
            <div className="absolute top-12 flex flex-col items-center">
              <div className="flex gap-4 bg-white/5 backdrop-blur-xl p-3 rounded-full border border-white/10 mb-2">
                {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => (
                  <button 
                    key={lang} 
                    onClick={(e) => { e.stopPropagation(); setGameState(prev => ({ ...prev, language: lang })); handleInteraction(); }}
                    className={`text-2xl transition-all duration-300 transform ${gameState.language === lang ? 'scale-125 drop-shadow-[0_0_8px_rgba(255,255,255,0.8)] opacity-100' : 'opacity-30 grayscale hover:grayscale-0 hover:opacity-100 hover:scale-110'}`}
                  >
                    {LANGUAGE_FLAGS[lang]}
                  </button>
                ))}
              </div>
            </div>

            <div className="text-center mb-20">
              <motion.h1 
                initial={{ y: 30, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ delay: 0.2 }}
                className="text-6xl md:text-8xl font-black tracking-tighter uppercase leading-none drop-shadow-2xl"
              >
                TAP FOOTBALL<br/><span className="text-emerald-500">2026</span>
              </motion.h1>
              <motion.p 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.4 }}
                className="text-[10px] md:text-xs font-bold text-white/40 tracking-[0.5em] uppercase mt-4"
              >
                {t('subTitle')}
              </motion.p>
            </div>

            <div className="w-full max-w-xs space-y-4">
              <motion.button 
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => { handleInteraction(); setStep('LEVEL_SELECT'); }}
                className="w-full bg-emerald-500 text-white font-black py-6 rounded-3xl shadow-[0_20px_50px_rgba(16,185,129,0.3)] uppercase text-sm tracking-[0.2em] btn-glow"
              >
                {t('startGame')}
              </motion.button>

              <button 
                onClick={() => setShowLeaderboard(true)}
                className="w-full bg-white/5 border border-white/10 text-white/60 font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md"
              >
                🏆 {t('leaderboard')}
              </button>

              <button 
                onClick={() => setStep('SCREENSHOT_UTILITY')}
                className="w-full mt-10 text-[9px] font-black text-white/20 uppercase tracking-[0.5em] hover:text-white/40"
              >
                📷 Store Assets Generator
              </button>
            </div>

            <button 
              onClick={() => setIsMuted(!isMuted)} 
              className="absolute bottom-12 right-8 text-xl p-4 bg-black/40 rounded-full border border-white/10 backdrop-blur-md"
            >
              {isMuted ? '🔇' : '🔊'}
            </button>
          </motion.div>
        ) : step === 'SCREENSHOT_UTILITY' ? (
          <motion.div 
            key="utility"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="fixed inset-0 z-[200] bg-[#051622] overflow-y-auto p-8 custom-scrollbar"
          >
             <div className="max-w-4xl mx-auto space-y-32 flex flex-col items-center">
                <header className="w-full flex justify-between items-center border-b border-white/10 pb-6 mb-10">
                   <div>
                    <h2 className="text-2xl font-black italic tracking-tighter text-emerald-500">PLAY STORE ASSET GENERATOR</h2>
                    <p className="text-[10px] text-white/40 font-bold uppercase tracking-widest">Use browser "Inspect (F12)" -> Mobile Mode for best captures</p>
                   </div>
                   <button onClick={() => setStep('HOME')} className="bg-white text-black font-black px-8 py-3 rounded-full text-[10px] uppercase tracking-widest hover:bg-emerald-500 hover:text-white transition-all">Exit Generator</button>
                </header>

                {/* ASSET 1: THE BRAND */}
                <div className="flex flex-col items-center text-center">
                  <h3 className="text-emerald-500 font-black text-xs uppercase tracking-[0.3em] mb-4">Screenshot 1: The Brand</h3>
                  <div className="w-[360px] h-[640px] bg-black rounded-[3rem] border-[8px] border-white/10 relative overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.5)]">
                    <div className="absolute inset-0 stadium-bg opacity-40" />
                    <div className="absolute top-10 left-0 w-full px-6 z-10">
                       <h2 className="text-white font-black text-2xl tracking-tighter uppercase leading-none italic">THE ULTIMATE<br/><span className="text-emerald-500">FOOTBALL CHALLENGE</span></h2>
                    </div>
                    <div className="relative h-full flex flex-col items-center justify-center px-10">
                       <h1 className="text-5xl font-black text-center uppercase tracking-tighter leading-tight mb-2">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></h1>
                       <p className="text-[8px] font-bold text-white/40 tracking-[0.4em] uppercase mb-16">Global Trivia Experience</p>
                       <div className="w-full space-y-4">
                          <div className="w-full bg-emerald-500 h-14 rounded-2xl flex items-center justify-center font-black text-xs uppercase tracking-widest">Start Game</div>
                          <div className="w-full bg-white/5 border border-white/10 h-12 rounded-xl flex items-center justify-center font-black text-[9px] uppercase tracking-widest text-white/50">Leaderboards</div>
                       </div>
                    </div>
                  </div>
                </div>

                {/* ASSET 2: GAMEPLAY */}
                <div className="flex flex-col items-center text-center">
                  <h3 className="text-emerald-500 font-black text-xs uppercase tracking-[0.3em] mb-4">Screenshot 2: AI Gameplay</h3>
                  <div className="w-[360px] h-[640px] bg-black rounded-[3rem] border-[8px] border-white/10 relative overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.5)]">
                    <div className="absolute inset-0 stadium-bg opacity-20" />
                    <div className="absolute top-10 left-0 w-full px-6 z-10">
                       <h2 className="text-white font-black text-2xl tracking-tighter uppercase leading-none italic">DYNAMIC<br/><span className="text-emerald-500">AI QUESTIONS</span></h2>
                    </div>
                    <div className="relative h-full flex flex-col p-4 pt-32">
                      <header className="flex justify-between items-center bg-black/80 p-3 rounded-2xl border border-white/10 backdrop-blur-xl mb-4">
                         <div><p className="text-white/20 text-[6px] font-black uppercase">LVL 2</p><p className="text-xs font-black text-yellow-400">1,450</p></div>
                         <div className="flex gap-0.5 text-[8px]">❤️❤️<span className="opacity-20">❤️❤️❤️</span></div>
                         <div className="text-right"><p className="text-white/20 text-[6px] font-black uppercase">Q 12/30</p><span className="bg-orange-500 px-1 py-0.5 rounded text-[7px] font-black italic">STREAK x4</span></div>
                      </header>
                      <QuizCard question={MOCK_QUESTION} onAnswer={() => {}} disabled={true} isMuted={true} language="English" />
                    </div>
                  </div>
                </div>

                {/* ASSET 3: PROGRESSION */}
                <div className="flex flex-col items-center text-center">
                  <h3 className="text-emerald-500 font-black text-xs uppercase tracking-[0.3em] mb-4">Screenshot 3: Progression</h3>
                  <div className="w-[360px] h-[640px] bg-black rounded-[3rem] border-[8px] border-white/10 relative overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.5)]">
                    <div className="absolute inset-0 stadium-bg opacity-30" />
                    <div className="absolute top-10 left-0 w-full px-6 z-10">
                       <h2 className="text-white font-black text-2xl tracking-tighter uppercase leading-none italic">CHOOSE YOUR<br/><span className="text-emerald-500">EXPERTISE LEVEL</span></h2>
                    </div>
                    <div className="relative h-full flex flex-col p-6 pt-36 space-y-3">
                       {INITIAL_LEVELS.map(l => (
                         <div key={l.id} className={`p-4 rounded-3xl border ${l.id === 1 ? 'bg-black/80 border-emerald-500' : 'bg-black/40 border-white/10 opacity-60'} flex justify-between items-center`}>
                           <div>
                            <span className="text-[7px] font-black text-white/30 uppercase">LEVEL {l.id}</span>
                            <h4 className="text-sm font-black uppercase">{l.name.English}</h4>
                           </div>
                           <span className="text-xs">{l.id === 1 ? 'GO →' : '🔒'}</span>
                         </div>
                       ))}
                       <div className="grid grid-cols-2 gap-2 mt-6">
                         <div className="bg-emerald-500/20 border border-emerald-500/40 p-3 rounded-2xl text-center"><p className="text-[7px] font-bold">PLAYERS</p></div>
                         <div className="bg-white/5 border border-white/10 p-3 rounded-2xl text-center opacity-40"><p className="text-[7px] font-bold">STADIUMS</p></div>
                         <div className="bg-white/5 border border-white/10 p-3 rounded-2xl text-center opacity-40"><p className="text-[7px] font-bold">CLUBS</p></div>
                         <div className="bg-white/5 border border-white/10 p-3 rounded-2xl text-center opacity-40"><p className="text-[7px] font-bold">COACHES</p></div>
                       </div>
                    </div>
                  </div>
                </div>

                <footer className="w-full text-center pb-20 opacity-40">
                   <p className="text-[9px] font-black uppercase tracking-widest">Tip: Right-click on the frames above and select "Save Image As" if using a capture tool, or just screenshot this page.</p>
                </footer>
             </div>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div 
            key="level-select" 
            initial={{ opacity: 0, x: 50 }} 
            animate={{ opacity: 1, x: 0 }} 
            className="flex-1 flex flex-col items-center pt-20 p-6"
          >
            <h2 className="text-3xl font-black uppercase tracking-tighter mb-10">{t('pickLevel')}</h2>
            <div className="w-full max-w-sm space-y-4">
              {levels.map(level => (
                <motion.div 
                  key={level.id}
                  whileTap={level.unlocked ? { scale: 0.98 } : {}}
                  onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))}
                  className={`p-6 rounded-[2rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/60 border-emerald-500/30 shadow-xl' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}
                >
                  <div>
                    <span className="text-white/30 text-[9px] font-black uppercase tracking-widest block mb-1">LVL {level.id}</span>
                    <h3 className="text-xl font-black uppercase">{level.name[gameState.language]}</h3>
                  </div>
                  {level.unlocked ? <span className="text-emerald-500 font-black">GO →</span> : <span className="text-white/20">🔒</span>}
                </motion.div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="mt-12 text-[10px] font-black text-white/30 uppercase tracking-[0.3em] hover:text-white transition-all">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="bg-black/80 backdrop-blur-3xl p-10 rounded-[3rem] border border-white/10 w-full max-w-sm text-center">
              <h2 className="text-2xl font-black mb-8 uppercase tracking-tight">{t('enterNickname')}</h2>
              <input 
                type="text" 
                value={gameState.nickname} 
                onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-white text-lg font-bold mb-8 focus:outline-none focus:border-emerald-500 text-center"
              />
              <button 
                onClick={() => setStep('CATEGORY_SELECT')}
                disabled={!gameState.nickname.trim()}
                className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest disabled:opacity-20"
              >
                {t('start')}
              </button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
             <h2 className="text-2xl font-black mb-10 uppercase tracking-tighter text-white/50">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                {Object.values(Category).map(cat => (
                  <button key={cat} onClick={() => handleStartQuiz(cat)} className={`p-5 rounded-2xl border font-black text-[9px] uppercase tracking-[0.2em] transition-all ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 text-white col-span-2' : 'bg-black/60 border-white/10 text-white/60 hover:border-white/30'}`}>
                    {CATEGORY_TRANSLATIONS[cat][gameState.language]}
                  </button>
                ))}
             </div>
