              className="absolute bottom-12 right-8 text-xl p-4 bg-black/40 rounded-full border border-white/10 backdrop-blur-md hover:bg-white/10 transition-colors"
            >
              {isMuted ? '🔇' : '🔊'}
            </button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div 
