  const [loading, setLoading] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [unlockedToast, setUnlockedToast] = useState<Achievement | null>(null);

  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'English',
    history: [],
  });

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
  }, [userStats]);

  const checkAchievements = useCallback((newStats: UserStats, currentStreak: number, isPerfect: boolean = false) => {
    const newUnlocks: string[] = [];
    ACHIEVEMENTS.forEach(ach => {
      if (newStats.unlockedAchievements.includes(ach.id)) return;

      let condition = false;
      if (ach.type === 'total_correct') condition = newStats.totalCorrect >= ach.requirement;
      if (ach.type === 'streak') condition = currentStreak >= ach.requirement;
      if (ach.type === 'perfect_game') condition = isPerfect;
      if (ach.type === 'level_completed') condition = newStats.levelsCompleted.includes(ach.requirement);

      if (condition) {
        newUnlocks.push(ach.id);
        setUnlockedToast(ach);
        audioService.playSfx('correct', 1); // Extra loud for celebration
        setTimeout(() => setUnlockedToast(null), 4000);
      }
    });

    if (newUnlocks.length > 0) {
      setUserStats(prev => ({ ...prev, unlockedAchievements: [...prev.unlockedAchievements, ...newUnlocks] }));
    }
  }, []);

  const handleInteraction = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.setBgMusic(!isMuted);
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newMute = !isMuted;
    setIsMuted(newMute);
    audioService.setBgMusic(!newMute);
  };

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number) => {
    setLoading(true);
    const config = levels.find(l => l.id === level) || levels[0];
    const progressRatio = progress / 30;
    const dynamicDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
    );

    const result = await generateQuestions(category, dynamicDiff, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch]);

  const handleStartQuiz = (category: Category) => {
    handleInteraction();
    setGameState(prev => ({ ...prev, selectedCategory: category, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * (1 + Math.floor(newStreak / 5) * 0.5)) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 30) || newMistakes >= 5;

    // Update Global Stats
    const updatedStats = {
      ...userStats,
      totalPoints: userStats.totalPoints + points,
      totalCorrect: isCorrect ? userStats.totalCorrect + 1 : userStats.totalCorrect,
      totalAnswered: userStats.totalAnswered + 1,
      maxStreak: Math.max(userStats.maxStreak, newStreak)
    };
    setUserStats(updatedStats);

    // Check Achievements on every answer
    checkAchievements(updatedStats, newStreak);

    if (isOver) {
      const isPerfect = newMistakes === 0 && (gameState.questionsAnswered + 1 >= 30);
      if (isPerfect) checkAchievements(updatedStats, newStreak, true);

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setUserStats(prev => ({
          ...prev,
          levelsCompleted: [...new Set([...prev.levelsCompleted, gameState.currentLevel])]
        }));
      }

      setLeaderboard(prev => {
        const updated = [...prev, { name: gameState.nickname || 'Player', score: gameState.score + points, country: LANGUAGE_FLAGS[gameState.language], timestamp: Date.now(), isUser: true }].sort((a, b) => b.score - a.score).slice(0, 20);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(updated));
        return updated;
      });

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setLevels(prev => {
          const updated = prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l);
          localStorage.setItem('quiz_levels', JSON.stringify(updated));
          return updated;
        });
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const handleShare = async () => {
    const text = t('shareText').replace('{score}', gameState.score.toString());
    const url = window.location.href;
    if (navigator.share) { try { await navigator.share({ title: 'TAP FOOTBALL QUIZ 2026', text: text, url: url }); } catch {} }
    else { navigator.clipboard.writeText(`${text} ${url}`); alert(t('copied')); }
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];
  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white" onClick={handleInteraction}>
      <AnimatePresence>
        {unlockedToast && (
          <motion.div initial={{ y: -100, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ y: -100, opacity: 0 }} className="fixed top-0 left-1/2 -translate-x-1/2 z-[200] w-full max-w-xs pointer-events-none px-4">
            <div className="bg-emerald-500 rounded-2xl p-4 shadow-[0_20px_40px_rgba(16,185,129,0.4)] border border-emerald-400 flex items-center space-x-4">
              <span className="text-3xl">{unlockedToast.icon}</span>
              <div>
                <p className="text-[10px] font-black text-white/60 uppercase tracking-widest leading-none mb-1">{t('unlockedToast')}</p>
                <p className="text-sm font-bold uppercase">{unlockedToast.name[gameState.language]}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div key="landing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 1.1 }} className="flex-1 flex flex-col items-center justify-center p-6 relative">
            <div className="absolute top-12 flex flex-col items-center">
              <div className="flex gap-4 bg-white/5 backdrop-blur-xl p-3 rounded-full border border-white/10 mb-2">
                {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => (
                  <button key={lang} onClick={(e) => { e.stopPropagation(); setGameState(prev => ({ ...prev, language: lang })); }} className={`text-2xl transition-all duration-300 transform ${gameState.language === lang ? 'scale-125 drop-shadow-[0_0_8px_rgba(255,255,255,0.8)]' : 'opacity-30 grayscale hover:grayscale-0 hover:opacity-100'}`}>{LANGUAGE_FLAGS[lang]}</button>
                ))}
              </div>
            </div>

            <div className="text-center mb-12">
              <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="w-20 h-20 mx-auto mb-6 drop-shadow-[0_0_30px_rgba(16,185,129,0.5)]" />
              <motion.h1 className="text-6xl md:text-8xl font-black tracking-tighter uppercase leading-none drop-shadow-2xl">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></motion.h1>
              <motion.p className="text-[10px] md:text-xs font-bold text-white/40 tracking-[0.5em] uppercase mt-4">{t('subTitle')}</motion.p>
            </div>

            <div className="w-full max-w-xs space-y-4">
              <motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }} onClick={() => setStep('LEVEL_SELECT')} className="w-full bg-emerald-500 text-white font-black py-6 rounded-3xl shadow-[0_20px_50px_rgba(16,185,129,0.3)] uppercase text-sm tracking-[0.2em] btn-glow">{t('startGame')}</motion.button>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setShowLeaderboard(true)} className="bg-white/5 border border-white/10 text-white/60 font-black py-4 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏆 RANK</button>
                <button onClick={() => setShowTrophyRoom(true)} className="bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black py-4 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏅 ROOM</button>
              </div>
            </div>

            <button onClick={toggleMute} className="absolute bottom-12 right-8 text-xl p-4 bg-black/40 rounded-full border border-white/10 backdrop-blur-md">{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center pt-20 p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter mb-10">{t('pickLevel')}</h2>
            <div className="w-full max-w-sm space-y-4">
              {levels.map(level => (
                <motion.div key={level.id} onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} className={`p-6 rounded-[2rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/60 border-emerald-500/30' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}>
                  <div><span className="text-white/30 text-[9px] font-black uppercase block mb-1">LVL {level.id}</span><h3 className="text-xl font-black uppercase">{level.name[gameState.language]}</h3></div>
                  {level.unlocked ? <span className="text-emerald-500 font-black">GO →</span> : <span>🔒</span>}
                </motion.div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="mt-12 text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="bg-black/80 p-10 rounded-[3rem] border border-white/10 w-full max-w-sm text-center">
              <h2 className="text-2xl font-black mb-8 uppercase">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-white text-lg font-bold mb-8 focus:outline-none focus:border-emerald-500 text-center" />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest disabled:opacity-20">{t('start')}</button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
             <h2 className="text-2xl font-black mb-10 uppercase tracking-tighter text-white/50">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                {Object.values(Category).map(cat => (
                  <button key={cat} onClick={() => handleStartQuiz(cat)} className={`p-5 rounded-2xl border font-black text-[9px] uppercase tracking-widest ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 col-span-2' : 'bg-black/60 border-white/10 text-white/60'}`}>{CATEGORY_TRANSLATIONS[cat][gameState.language]}</button>
                ))}
             </div>
             <button onClick={() => setStep('LEVEL_SELECT')} className="mt-10 text-[10px] font-black text-white/30 uppercase">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-md mx-auto pt-14">
            {gameState.isGameOver ? (
              <div className="flex-1 flex flex-col items-center justify-center">
                <div className={`bg-black/95 backdrop-blur-3xl p-8 rounded-[3rem] border ${isWin ? 'border-emerald-500/40' : 'border-rose-500/40'} text-center w-full shadow-2xl`}>
                  <img src={GAME_LOGO} className="w-16 h-16 mx-auto mb-4" />
                  <h1 className={`text-4xl font-black mt-4 mb-2 uppercase ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                  <div className="grid grid-cols-2 gap-3 my-8">
                    <div className="bg-white/5 p-4 rounded-3xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('correctAnswersLabel')}</span><p className="text-xl font-black text-emerald-400">{gameState.correctAnswers}</p></div>
                    <div className="bg-white/5 p-4 rounded-3xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span><p className="text-xl font-black text-white">{gameState.score}</p></div>
                  </div>
                  <div className="space-y-4">
                    <button onClick={handleShare} className="w-full bg-white/10 border border-white/10 text-white font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">📤 {t('shareBtn')}</button>
                    <button onClick={() => setStep('HOME')} className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest">{t('playAgain')}</button>
                    <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full bg-white/5 text-white/70 font-black py-4 rounded-2xl border border-white/10 uppercase text-[10px] tracking-widest">{t('retry')}</button>
                  </div>
                </div>
              </div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-6 bg-black/60 p-4 rounded-3xl border border-white/10 backdrop-blur-xl">
                   <div className="flex flex-col"><p className="text-white/20 text-[7px] font-black uppercase">LVL {gameState.currentLevel}</p><p className="text-lg font-black text-yellow-400 leading-none">{gameState.score}</p></div>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[7px] font-black uppercase">{t('lives')}</p><div className="flex space-x-1">{[...Array(5)].map((_, i) => (<span key={i} className={`text-xs ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : ''}`}>❤️</span>))}</div></div>
                   <div className="flex flex-col items-end"><p className="text-white/20 text-[7px] font-black uppercase">Q {gameState.questionsAnswered + 1}/30</p><div className={`px-2 py-0.5 rounded-full text-[9px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/5 text-white/20'}`}>x{streak}</div></div>
                </header>
                <div className="w-full mb-8 h-1.5 bg-white/5 rounded-full overflow-hidden"><motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 30) * 100}%` }} /></div>
                <div className="flex-1 flex items-center justify-center">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? (
                      <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center justify-center space-y-6">
                        <div className="relative"><div className="w-20 h-20 border-4 border-emerald-500/10 rounded-full" /><div className="absolute top-0 w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(16,185,129,0.3)]" /></div>
                        <p className="text-emerald-500 font-black text-xs uppercase tracking-[0.5em] animate-pulse">{t('generating')}</p>
                      </motion.div>
                    ) : questions[currentQuestionIndex] ? (
                      <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={false} isMuted={isMuted} language={gameState.language} />
                    ) : null}
                  </AnimatePresence>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6" onClick={() => setShowLeaderboard(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="bg-black/60 border border-white/10 w-full max-w-sm rounded-[3rem] p-8" onClick={e => e.stopPropagation()}>
              <h3 className="text-center text-white font-black text-xl uppercase mb-8">{t('leaderboard')}</h3>
              <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar mb-8">
                {leaderboard.map((user, i) => (
                  <div key={i} className={`flex items-center justify-between px-4 py-3 rounded-2xl border ${user.isUser ? 'bg-emerald-500/20 border-emerald-500/40' : 'bg-white/5 border-white/5'}`}>
                    <div className="flex items-center space-x-3"><span className="font-black text-[10px] w-4 opacity-30">{i + 1}.</span><span className="font-bold text-sm">{user.name}</span></div>
                    <span className="text-emerald-400 font-black text-sm">{user.score}</span>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowLeaderboard(false)} className="w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showTrophyRoom && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6" onClick={() => setShowTrophyRoom(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="bg-black/60 border border-yellow-500/20 w-full max-w-sm rounded-[3rem] p-8" onClick={e => e.stopPropagation()}>
              <div className="text-center mb-8"><span className="text-4xl block mb-2">🏆</span><h3 className="text-white font-black text-xl uppercase tracking-tighter">{t('trophyRoom')}</h3></div>
              <div className="grid grid-cols-2 gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar mb-8">
                {ACHIEVEMENTS.map((ach) => {
                  const isUnlocked = userStats.unlockedAchievements.includes(ach.id);
                  return (
                    <div key={ach.id} className={`p-4 rounded-2xl border flex flex-col items-center text-center ${isUnlocked ? 'bg-yellow-500/10 border-yellow-500/30 shadow-[0_0_15px_rgba(234,179,8,0.1)]' : 'bg-white/5 border-white/5 opacity-40 grayscale'}`}>
                      <span className="text-3xl mb-2">{ach.icon}</span>
                      <p className="text-[9px] font-black uppercase mb-1 leading-none">{ach.name[gameState.language]}</p>
                      <p className="text-[7px] font-medium text-white/40 leading-tight">{ach.description[gameState.language]}</p>
                    </div>
                  );
                })}
              </div>
              <button onClick={() => setShowTrophyRoom(false)} className="w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-8 text-center mt-auto"><p className="text-[8px] font-black text-white/10 uppercase tracking-[0.5em]">TAP FOOTBALL QUIZ 2026</p></footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Category, Question, GameState, LevelConfig, Language, LeaderboardEntry, Achievement, UserStats } from './types';
import { generateQuestions } from './services/geminiService';
import { audioService } from './services/audioService';
import QuizCard from './components/QuizCard';

const INITIAL_LEVELS: LevelConfig[] = [
  { id: 1, name: { Bosanski: "Početnik", English: "Beginner", Deutsch: "Anfänger" }, minDifficulty: 1, maxDifficulty: 3, questionsPerLevel: 30, unlocked: true },
  { id: 2, name: { Bosanski: "Ekspert", English: "Expert", Deutsch: "Experte" }, minDifficulty: 4, maxDifficulty: 7, questionsPerLevel: 30, unlocked: false },
  { id: 3, name: { Bosanski: "Legenda", English: "Legend", Deutsch: "Legende" }, minDifficulty: 8, maxDifficulty: 10, questionsPerLevel: 30, unlocked: false },
];

const ACHIEVEMENTS: Achievement[] = [
  { id: 'first_goal', icon: '⚽', name: { Bosanski: "Prvi Gol", English: "First Goal", Deutsch: "Erstes Tor" }, description: { Bosanski: "Odgovori na 1 pitanje tačno", English: "Answer 1 question correctly", Deutsch: "Beantworten Sie 1 Frage richtig" }, requirement: 1, type: 'total_correct' },
  { id: 'hattrick', icon: '🎩', name: { Bosanski: "Hattrick", English: "Hattrick", Deutsch: "Hattrick" }, description: { Bosanski: "Niz od 3 tačna odgovora", English: "Get a 3-streak", Deutsch: "Erhalten Sie eine 3er-Serie" }, requirement: 3, type: 'streak' },
  { id: 'clean_sheet', icon: '🧤', name: { Bosanski: "Mreža Mirovala", English: "Clean Sheet", Deutsch: "Weiße Weste" }, description: { Bosanski: "Završi partiju bez greške", English: "Finish a game with 0 mistakes", Deutsch: "Beende ein Spiel ohne Fehler" }, requirement: 1, type: 'perfect_game' },
  { id: 'pro_striker', icon: '🔥', name: { Bosanski: "Pro Napadač", English: "Pro Striker", Deutsch: "Pro-Stürmer" }, description: { Bosanski: "Niz od 10 tačnih odgovora", English: "Get a 10-streak", Deutsch: "Erhalten Sie eine 10er-Serie" }, requirement: 10, type: 'streak' },
  { id: 'centurion', icon: '💯', name: { Bosanski: "Centurion", English: "Centurion", Deutsch: "Centurion" }, description: { Bosanski: "100 tačnih odgovora ukupno", English: "100 total correct answers", Deutsch: "100 insgesamt richtige Antworten" }, requirement: 100, type: 'total_correct' },
  { id: 'world_class', icon: '🌍', name: { Bosanski: "Svjetska Klasa", English: "World Class", Deutsch: "Weltklasse" }, description: { Bosanski: "Završi 2. nivo", English: "Complete Level 2", Deutsch: "Level 2 abschließen" }, requirement: 2, type: 'level_completed' },
];

const BASE_LEADERBOARD: LeaderboardEntry[] = [
  { name: "Edin_Dž", score: 2850, country: "🇧🇦", timestamp: Date.now() - 3600000 },
  { name: "Marco_R", score: 2720, country: "🇩🇪", timestamp: Date.now() - 7200000 },
  { name: "Luka_M", score: 2540, country: "🇭🇷", timestamp: Date.now() - 10800000 },
];

const TRANSLATIONS = {
  score: { Bosanski: "BODOVI", English: "SCORE", Deutsch: "PUNKTE" },
  gameOver: { Bosanski: "KRAJ IGRE!", English: "GAME OVER!", Deutsch: "SPIEL VORBEI!" },
  success: { Bosanski: "BRAVO!", English: "SUCCESS!", Deutsch: "BRAVO!" },
  correctAnswersLabel: { Bosanski: "Tačno", English: "Correct", Deutsch: "Richtig" },
  totalScoreLabel: { Bosanski: "Bodovi", English: "Points", Deutsch: "Punkte" },
  playAgain: { Bosanski: "POČETNA", English: "HOME", Deutsch: "START" },
  retry: { Bosanski: "POKUŠAJ PONOVO", English: "TRY AGAIN", Deutsch: "WIEDERHOLEN" },
  start: { Bosanski: "KRENI", English: "START", Deutsch: "START" },
  startGame: { Bosanski: "ZAPOČNI IGRU", English: "START GAME", Deutsch: "JETZT SPIELEN" },
  generating: { Bosanski: "Učitavam...", English: "Loading...", Deutsch: "Laden..." },
  selectCategory: { Bosanski: "Izaberi kategoriju", English: "Pick category", Deutsch: "Kategorie" },
  enterNickname: { Bosanski: "Nadimak", English: "Nickname", Deutsch: "Name" },
  leaderboard: { Bosanski: "RANKING 2026", English: "RANKING 2026", Deutsch: "RANKING 2026" },
  back: { Bosanski: "NAZAD", English: "BACK", Deutsch: "ZURÜCK" },
  close: { Bosanski: "ZATVORI", English: "CLOSE", Deutsch: "SCHLIESSEN" },
  lives: { Bosanski: "ŽIVOTI", English: "LIVES", Deutsch: "LEBEN" },
  subTitle: { Bosanski: "Vrhunski fudbalski kviz 2026", English: "The ultimate football quiz 2026", Deutsch: "Das ultimative Fußball-Quiz 2026" },
  pickLevel: { Bosanski: "Izaberi nivo", English: "Select Level", Deutsch: "Level wählen" },
  shareBtn: { Bosanski: "PODIJELI REZULTAT", English: "SHARE SCORE", Deutsch: "TEILEN" },
  shareText: { Bosanski: "Moj rezultat je {score} u TAP FOOTBALL QUIZ 2026! Možeš li bolje?", English: "My score is {score} in TAP FOOTBALL QUIZ 2026! Can you do better?", Deutsch: "Mein Punktestand ist {score} in TAP FOOTBALL QUIZ 2026! Kannst du das toppen?" },
  copied: { Bosanski: "Kopirano!", English: "Copied!", Deutsch: "Kopiert!" },
  trophyRoom: { Bosanski: "TROFEJNA SALA", English: "TROPHY ROOM", Deutsch: "TROPHÄENRAUM" },
  unlockedToast: { Bosanski: "OTKLJUČANO!", English: "UNLOCKED!", Deutsch: "FREIGESCHALTET!" }
};

const LANGUAGE_FLAGS: Record<Language, string> = { 'Bosanski': '🇧🇦', 'English': '🇬🇧', 'Deutsch': '🇩🇪' };
const CATEGORY_TRANSLATIONS: Record<Category, Record<Language, string>> = {
  [Category.PLAYERS]: { Bosanski: "IGRAČI", English: "PLAYERS", Deutsch: "SPIELER" },
  [Category.STADIUMS]: { Bosanski: "STADIONI", English: "STADIUMS", Deutsch: "STADIEN" },
  [Category.CLUBS]: { Bosanski: "KLUBOVI", English: "CLUBS", Deutsch: "VEREINE" },
  [Category.NATIONAL_TEAMS]: { Bosanski: "REPREZENTACIJE", English: "TEAMS", Deutsch: "TEAMS" },
  [Category.COACHES]: { Bosanski: "TRENERI", English: "COACHES", Deutsch: "TRAINER" },
  [Category.ALL]: { Bosanski: "SVE", English: "ALL", Deutsch: "ALLE" }
};

const GAME_LOGO = "https://cdn-icons-png.flaticon.com/512/53/53283.png";

const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => JSON.parse(localStorage.getItem('quiz_levels') || JSON.stringify(INITIAL_LEVELS)));
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    const saved = localStorage.getItem('quiz_leaderboard');
    return saved ? JSON.parse(saved) : BASE_LEADERBOARD;
  });

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('quiz_user_stats');
    return saved ? JSON.parse(saved) : { totalPoints: 0, totalCorrect: 0, totalAnswered: 0, maxStreak: 0, levelsCompleted: [], unlockedAchievements: [] };
  });

  const [hasInteracted, setHasInteracted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [unlockedToast, setUnlockedToast] = useState<Achievement | null>(null);

  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'English',
    history: [],
  });

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
  }, [userStats]);

  const checkAchievements = useCallback((newStats: UserStats, currentStreak: number, isPerfect: boolean = false) => {
    const newUnlocks: string[] = [];
    ACHIEVEMENTS.forEach(ach => {
      if (newStats.unlockedAchievements.includes(ach.id)) return;

      let condition = false;
      if (ach.type === 'total_correct') condition = newStats.totalCorrect >= ach.requirement;
      if (ach.type === 'streak') condition = currentStreak >= ach.requirement;
      if (ach.type === 'perfect_game') condition = isPerfect;
      if (ach.type === 'level_completed') condition = newStats.levelsCompleted.includes(ach.requirement);

      if (condition) {
        newUnlocks.push(ach.id);
        setUnlockedToast(ach);
        audioService.playSfx('correct', 1);
        setTimeout(() => setUnlockedToast(null), 4000);
      }
    });

    if (newUnlocks.length > 0) {
      setUserStats(prev => ({ ...prev, unlockedAchievements: [...prev.unlockedAchievements, ...newUnlocks] }));
    }
  }, []);

  const handleInteraction = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.setBgMusic(!isMuted);
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newMute = !isMuted;
    setIsMuted(newMute);
    audioService.setBgMusic(!newMute);
  };

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number) => {
    setLoading(true);
    const config = levels.find(l => l.id === level) || levels[0];
    const progressRatio = progress / 30;
    const dynamicDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
    );

    const result = await generateQuestions(category, dynamicDiff, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch]);

  const handleStartQuiz = (category: Category) => {
    handleInteraction();
    setGameState(prev => ({ ...prev, selectedCategory: category, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * (1 + Math.floor(newStreak / 5) * 0.5)) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 30) || newMistakes >= 5;

    const updatedStats = {
      ...userStats,
      totalPoints: userStats.totalPoints + points,
      totalCorrect: isCorrect ? userStats.totalCorrect + 1 : userStats.totalCorrect,
      totalAnswered: userStats.totalAnswered + 1,
      maxStreak: Math.max(userStats.maxStreak, newStreak)
    };
    setUserStats(updatedStats);
    checkAchievements(updatedStats, newStreak);

    if (isOver) {
      const isPerfect = newMistakes === 0 && (gameState.questionsAnswered + 1 >= 30);
      if (isPerfect) checkAchievements(updatedStats, newStreak, true);

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setUserStats(prev => ({
          ...prev,
          levelsCompleted: [...new Set([...prev.levelsCompleted, gameState.currentLevel])]
        }));
      }

      setLeaderboard(prev => {
        const updated = [...prev, { name: gameState.nickname || 'Player', score: gameState.score + points, country: LANGUAGE_FLAGS[gameState.language], timestamp: Date.now(), isUser: true }].sort((a, b) => b.score - a.score).slice(0, 20);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(updated));
        return updated;
      });

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setLevels(prev => {
          const updated = prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l);
          localStorage.setItem('quiz_levels', JSON.stringify(updated));
          return updated;
        });
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const handleShare = async () => {
    const text = t('shareText').replace('{score}', gameState.score.toString());
    const url = window.location.href;
    if (navigator.share) { try { await navigator.share({ title: 'TAP FOOTBALL QUIZ 2026', text: text, url: url }); } catch {} }
    else { navigator.clipboard.writeText(`${text} ${url}`); alert(t('copied')); }
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];
  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white" onClick={handleInteraction}>
      <AnimatePresence>
        {unlockedToast && (
          <motion.div initial={{ y: -100, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ y: -100, opacity: 0 }} className="fixed top-0 left-1/2 -translate-x-1/2 z-[200] w-full max-w-xs pointer-events-none px-4">
            <div className="bg-emerald-500 rounded-2xl p-4 shadow-[0_20px_40px_rgba(16,185,129,0.4)] border border-emerald-400 flex items-center space-x-4">
              <span className="text-3xl">{unlockedToast.icon}</span>
              <div>
                <p className="text-[10px] font-black text-white/60 uppercase tracking-widest leading-none mb-1">{t('unlockedToast')}</p>
                <p className="text-sm font-bold uppercase">{unlockedToast.name[gameState.language]}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div key="landing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 1.1 }} className="flex-1 flex flex-col items-center justify-center p-6 relative">
            <div className="absolute top-8 flex flex-col items-center">
              <div className="flex gap-4 bg-white/5 backdrop-blur-xl p-2.5 rounded-full border border-white/10 mb-2">
                {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => (
                  <button key={lang} onClick={(e) => { e.stopPropagation(); setGameState(prev => ({ ...prev, language: lang })); }} className={`text-xl transition-all duration-300 transform ${gameState.language === lang ? 'scale-125 drop-shadow-[0_0_8px_rgba(255,255,255,0.8)]' : 'opacity-30 grayscale hover:grayscale-0 hover:opacity-100'}`}>{LANGUAGE_FLAGS[lang]}</button>
                ))}
              </div>
            </div>

            <div className="text-center mb-8">
              <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="w-12 h-12 mx-auto mb-4 drop-shadow-[0_0_30px_rgba(16,185,129,0.5)]" />
              <motion.h1 className="text-5xl md:text-7xl font-black tracking-tighter uppercase leading-none drop-shadow-2xl">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></motion.h1>
              <motion.p className="text-[9px] md:text-xs font-bold text-white/40 tracking-[0.5em] uppercase mt-3">{t('subTitle')}</motion.p>
            </div>

            <div className="w-full max-w-xs space-y-4">
              <motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }} onClick={() => setStep('LEVEL_SELECT')} className="w-full bg-emerald-500 text-white font-black py-5 rounded-3xl shadow-[0_20px_50px_rgba(16,185,129,0.3)] uppercase text-sm tracking-[0.2em] btn-glow">{t('startGame')}</motion.button>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setShowLeaderboard(true)} className="bg-white/5 border border-white/10 text-white/60 font-black py-3.5 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏆 RANK</button>
                <button onClick={() => setShowTrophyRoom(true)} className="bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black py-3.5 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏅 ROOM</button>
              </div>
            </div>

            <button onClick={toggleMute} className="absolute bottom-8 right-8 text-base p-2.5 bg-black/40 rounded-full border border-white/10 backdrop-blur-md flex items-center justify-center w-10 h-10">{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center pt-20 p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter mb-10">{t('pickLevel')}</h2>
            <div className="w-full max-w-sm space-y-4">
              {levels.map(level => (
                <motion.div key={level.id} onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} className={`p-6 rounded-[2rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/60 border-emerald-500/30' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}>
                  <div><span className="text-white/30 text-[9px] font-black uppercase block mb-1">LVL {level.id}</span><h3 className="text-xl font-black uppercase">{level.name[gameState.language]}</h3></div>
                  {level.unlocked ? <span className="text-emerald-500 font-black">GO →</span> : <span>🔒</span>}
                </motion.div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="mt-12 text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="bg-black/80 p-10 rounded-[3rem] border border-white/10 w-full max-w-sm text-center">
              <h2 className="text-2xl font-black mb-8 uppercase">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-white text-lg font-bold mb-8 focus:outline-none focus:border-emerald-500 text-center" />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest disabled:opacity-20">{t('start')}</button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
             <h2 className="text-2xl font-black mb-10 uppercase tracking-tighter text-white/50">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                {Object.values(Category).map(cat => (
                  <button key={cat} onClick={() => handleStartQuiz(cat)} className={`p-5 rounded-2xl border font-black text-[9px] uppercase tracking-widest ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 col-span-2' : 'bg-black/60 border-white/10 text-white/60'}`}>{CATEGORY_TRANSLATIONS[cat][gameState.language]}</button>
                ))}
             </div>
             <button onClick={() => setStep('LEVEL_SELECT')} className="mt-10 text-[10px] font-black text-white/30 uppercase">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-md mx-auto pt-14">
            {gameState.isGameOver ? (
              <div className="flex-1 flex flex-col items-center justify-center">
                <div className={`bg-black/95 backdrop-blur-3xl p-8 rounded-[3rem] border ${isWin ? 'border-emerald-500/40' : 'border-rose-500/40'} text-center w-full shadow-2xl`}>
                  <img src={GAME_LOGO} className="w-10 h-10 mx-auto mb-4" />
                  <h1 className={`text-4xl font-black mt-4 mb-2 uppercase ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                  <div className="grid grid-cols-2 gap-3 my-8">
                    <div className="bg-white/5 p-4 rounded-3xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('correctAnswersLabel')}</span><p className="text-xl font-black text-emerald-400">{gameState.correctAnswers}</p></div>
                    <div className="bg-white/5 p-4 rounded-3xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span><p className="text-xl font-black text-white">{gameState.score}</p></div>
                  </div>
                  <div className="space-y-4">
                    <button onClick={handleShare} className="w-full bg-white/10 border border-white/10 text-white font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">📤 {t('shareBtn')}</button>
                    <button onClick={() => setStep('HOME')} className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest">{t('playAgain')}</button>
                    <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full bg-white/5 text-white/70 font-black py-4 rounded-2xl border border-white/10 uppercase text-[10px] tracking-widest">{t('retry')}</button>
                  </div>
                </div>
              </div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-6 bg-black/60 p-4 rounded-3xl border border-white/10 backdrop-blur-xl">
                   <div className="flex flex-col"><p className="text-white/20 text-[7px] font-black uppercase">LVL {gameState.currentLevel}</p><p className="text-lg font-black text-yellow-400 leading-none">{gameState.score}</p></div>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[7px] font-black uppercase">{t('lives')}</p><div className="flex space-x-1">{[...Array(5)].map((_, i) => (<span key={i} className={`text-xs ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : ''}`}>❤️</span>))}</div></div>
                   <div className="flex flex-col items-end"><p className="text-white/20 text-[7px] font-black uppercase">Q {gameState.questionsAnswered + 1}/30</p><div className={`px-2 py-0.5 rounded-full text-[9px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/5 text-white/20'}`}>x{streak}</div></div>
                </header>
                <div className="w-full mb-8 h-1.5 bg-white/5 rounded-full overflow-hidden"><motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 30) * 100}%` }} /></div>
                <div className="flex-1 flex items-center justify-center">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? (
                      <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center justify-center space-y-6">
                        <div className="relative"><div className="w-20 h-20 border-4 border-emerald-500/10 rounded-full" /><div className="absolute top-0 w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(16,185,129,0.3)]" /></div>
                        <p className="text-emerald-500 font-black text-xs uppercase tracking-[0.5em] animate-pulse">{t('generating')}</p>
                      </motion.div>
                    ) : questions[currentQuestionIndex] ? (
                      <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={false} isMuted={isMuted} language={gameState.language} />
                    ) : null}
                  </AnimatePresence>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6" onClick={() => setShowLeaderboard(false)}>
