const GAME_LOGO = "https://cdn-icons-png.flaticon.com/512/53/53283.png";

const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => JSON.parse(localStorage.getItem('quiz_levels') || JSON.stringify(INITIAL_LEVELS)));
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    const saved = localStorage.getItem('quiz_leaderboard');
    return saved ? JSON.parse(saved) : BASE_LEADERBOARD;
  });

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('quiz_user_stats');
    return saved ? JSON.parse(saved) : { totalPoints: 0, totalCorrect: 0, totalAnswered: 0, maxStreak: 0, levelsCompleted: [], unlockedAchievements: [] };
  });

  const [hasInteracted, setHasInteracted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [unlockedToast, setUnlockedToast] = useState<Achievement | null>(null);

  const [gameState, setGameState] = useState<GameState>({
    nickname: localStorage.getItem('quiz_nickname') || '',
    currentLevel: 1,
    selectedCategory: Category.ALL,
    score: 0,
    questionsAnswered: 0,
    correctAnswers: 0,
    mistakes: 0,
    isGameOver: false,
    language: 'English',
    history: [],
  });

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
  }, [userStats]);

  const checkAchievements = useCallback((newStats: UserStats, currentStreak: number, isPerfect: boolean = false) => {
    const newUnlocks: string[] = [];
    ACHIEVEMENTS.forEach(ach => {
      if (newStats.unlockedAchievements.includes(ach.id)) return;

      let condition = false;
      if (ach.type === 'total_correct') condition = newStats.totalCorrect >= ach.requirement;
      if (ach.type === 'streak') condition = currentStreak >= ach.requirement;
      if (ach.type === 'perfect_game') condition = isPerfect;
      if (ach.type === 'level_completed') condition = newStats.levelsCompleted.includes(ach.requirement);

      if (condition) {
        newUnlocks.push(ach.id);
        setUnlockedToast(ach);
        audioService.playSfx('correct', 1);
        setTimeout(() => setUnlockedToast(null), 4000);
      }
    });

    if (newUnlocks.length > 0) {
      setUserStats(prev => ({ ...prev, unlockedAchievements: [...prev.unlockedAchievements, ...newUnlocks] }));
    }
  }, []);

  const handleInteraction = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.setBgMusic(!isMuted);
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newMute = !isMuted;
    setIsMuted(newMute);
    audioService.setBgMusic(!newMute);
  };

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number) => {
    setLoading(true);
    const config = levels.find(l => l.id === level) || levels[0];
    const progressRatio = progress / 30;
    const dynamicDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
    );

    const result = await generateQuestions(category, dynamicDiff, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch]);

  const handleStartQuiz = (category: Category) => {
    handleInteraction();
    setGameState(prev => ({ ...prev, selectedCategory: category, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setStep('QUIZ');
  };

  const handleAnswer = (answer: string) => {
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * (1 + Math.floor(newStreak / 5) * 0.5)) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 30) || newMistakes >= 5;

    const updatedStats = {
      ...userStats,
      totalPoints: userStats.totalPoints + points,
      totalCorrect: isCorrect ? userStats.totalCorrect + 1 : userStats.totalCorrect,
      totalAnswered: userStats.totalAnswered + 1,
      maxStreak: Math.max(userStats.maxStreak, newStreak)
    };
    setUserStats(updatedStats);
    checkAchievements(updatedStats, newStreak);

    if (isOver) {
      const isPerfect = newMistakes === 0 && (gameState.questionsAnswered + 1 >= 30);
      if (isPerfect) checkAchievements(updatedStats, newStreak, true);

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setUserStats(prev => ({
          ...prev,
          levelsCompleted: [...new Set([...prev.levelsCompleted, gameState.currentLevel])]
        }));
      }

      setLeaderboard(prev => {
        const updated = [...prev, { name: gameState.nickname || 'Player', score: gameState.score + points, country: LANGUAGE_FLAGS[gameState.language], timestamp: Date.now(), isUser: true }].sort((a, b) => b.score - a.score).slice(0, 20);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(updated));
        return updated;
      });

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setLevels(prev => {
          const updated = prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l);
          localStorage.setItem('quiz_levels', JSON.stringify(updated));
          return updated;
        });
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const handleShare = async () => {
    const accuracy = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);
    const text = t('shareText')
      .replace('{score}', gameState.score.toString())
      .replace('{accuracy}', accuracy.toString());

    // Fixed sharing URL: Ensuring it's a full URL including protocol and host
    const url = window.location.origin + window.location.pathname;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'TAP FOOTBALL 2026',
          text: text,
          url: url,
        });
      } catch (err) {
        console.error('Share failed:', err);
      }
    } else {
      // Fallback for browsers that don't support Web Share API
      const shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text + " " + url)}`;
      window.open(shareUrl, '_blank');
      navigator.clipboard.writeText(`${text} ${url}`);
      alert(t('copied'));
    }
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][gameState.language];
  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;
  const accuracyPercent = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);

  return (
    <div className="min-h-screen grass-pattern overflow-hidden font-['Outfit'] flex flex-col relative text-white" onClick={handleInteraction}>
      <AnimatePresence>
        {unlockedToast && (
          <motion.div initial={{ y: -100, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ y: -100, opacity: 0 }} className="fixed top-0 left-1/2 -translate-x-1/2 z-[200] w-full max-w-xs pointer-events-none px-4">
            <div className="bg-emerald-500 rounded-2xl p-4 shadow-[0_20px_40px_rgba(16,185,129,0.4)] border border-emerald-400 flex items-center space-x-4">
              <span className="text-3xl">{unlockedToast.icon}</span>
              <div>
                <p className="text-[10px] font-black text-white/60 uppercase tracking-widest leading-none mb-1">{t('unlockedToast')}</p>
                <p className="text-sm font-bold uppercase">{unlockedToast.name[gameState.language]}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div key="landing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 1.1 }} className="flex-1 flex flex-col items-center justify-center p-6 relative">
            <div className="absolute top-8 flex flex-col items-center">
              <div className="flex gap-4 bg-white/5 backdrop-blur-xl p-2.5 rounded-full border border-white/10 mb-2">
                {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => (
                  <button key={lang} onClick={(e) => { e.stopPropagation(); setGameState(prev => ({ ...prev, language: lang })); }} className={`text-xl transition-all duration-300 transform ${gameState.language === lang ? 'scale-125 drop-shadow-[0_0_8px_rgba(255,255,255,0.8)]' : 'opacity-30 grayscale hover:grayscale-0 hover:opacity-100'}`}>{LANGUAGE_FLAGS[lang]}</button>
                ))}
              </div>
            </div>

            <div className="text-center mb-8">
              <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="w-12 h-12 mx-auto mb-4 drop-shadow-[0_0_30px_rgba(16,185,129,0.5)]" />
              <motion.h1 className="text-5xl md:text-7xl font-black tracking-tighter uppercase leading-none drop-shadow-2xl">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></motion.h1>
              <motion.p className="text-[9px] md:text-xs font-bold text-white/40 tracking-[0.5em] uppercase mt-3">{t('subTitle')}</motion.p>
            </div>

            <div className="w-full max-w-xs space-y-4">
              <motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }} onClick={() => setStep('LEVEL_SELECT')} className="w-full bg-emerald-500 text-white font-black py-5 rounded-3xl shadow-[0_20px_50px_rgba(16,185,129,0.3)] uppercase text-sm tracking-[0.2em] btn-glow">{t('startGame')}</motion.button>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setShowLeaderboard(true)} className="bg-white/5 border border-white/10 text-white/60 font-black py-3.5 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏆 RANK</button>
                <button onClick={() => setShowTrophyRoom(true)} className="bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black py-3.5 rounded-2xl uppercase text-[9px] tracking-widest backdrop-blur-md">🏅 ROOM</button>
              </div>
            </div>

            <button onClick={toggleMute} className="absolute bottom-8 right-8 text-base p-2.5 bg-black/40 rounded-full border border-white/10 backdrop-blur-md flex items-center justify-center w-10 h-10">{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center pt-20 p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter mb-10">{t('pickLevel')}</h2>
            <div className="w-full max-w-sm space-y-4">
              {levels.map(level => (
                <motion.div key={level.id} onClick={() => level.unlocked && (setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} className={`p-6 rounded-[2rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/60 border-emerald-500/30' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}>
                  <div><span className="text-white/30 text-[9px] font-black uppercase block mb-1">LVL {level.id}</span><h3 className="text-xl font-black uppercase">{level.name[gameState.language]}</h3></div>
                  {level.unlocked ? <span className="text-emerald-500 font-black">GO →</span> : <span>🔒</span>}
                </motion.div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="mt-12 text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="bg-black/80 p-10 rounded-[3rem] border border-white/10 w-full max-w-sm text-center">
              <h2 className="text-2xl font-black mb-8 uppercase">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-white text-lg font-bold mb-8 focus:outline-none focus:border-emerald-500 text-center" />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-widest disabled:opacity-20">{t('start')}</button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
             <h2 className="text-2xl font-black mb-10 uppercase tracking-tighter text-white/50">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                {Object.values(Category).map(cat => (
                  <button key={cat} onClick={() => handleStartQuiz(cat)} className={`p-5 rounded-2xl border font-black text-[9px] uppercase tracking-widest ${cat === Category.ALL ? 'bg-emerald-500 border-emerald-400 col-span-2' : 'bg-black/60 border-white/10 text-white/60'}`}>{CATEGORY_TRANSLATIONS[cat][gameState.language]}</button>
                ))}
             </div>
             <button onClick={() => setStep('LEVEL_SELECT')} className="mt-10 text-[10px] font-black text-white/30 uppercase">{t('back')}</button>
          </motion.div>
