          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-md mx-auto pt-14">
            {gameState.isGameOver ? (
              <motion.div 
                initial={{ y: 20, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                className="flex-1 flex flex-col items-center justify-center"
              >
                <div className={`bg-black/95 backdrop-blur-3xl p-8 rounded-[3rem] border ${isWin ? 'border-emerald-500/40 shadow-[0_0_50px_rgba(16,185,129,0.2)]' : 'border-rose-500/40 shadow-[0_0_50px_rgba(244,63,94,0.2)]'} text-center w-full shadow-2xl overflow-hidden relative`}>
                  {/* Decorative backgrounds */}
                  <div className={`absolute -top-10 -right-10 w-32 h-32 rounded-full blur-3xl opacity-20 ${isWin ? 'bg-emerald-500' : 'bg-rose-500'}`} />

                  <motion.img 
                    initial={{ scale: 0, rotate: -180 }}
                    animate={{ scale: 1, rotate: 0 }}
                    transition={{ type: "spring", damping: 10 }}
                    src={GAME_LOGO} 
                    className="w-10 h-10 mx-auto mb-4 relative z-10" 
                  />

                  <motion.h1 
                    initial={{ y: 10, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.2 }}
                    className={`text-4xl font-black mt-4 mb-2 uppercase tracking-tighter ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}
                  >
                    {isWin ? t('success') : t('gameOver')}
                  </h1 >

                  <div className="grid grid-cols-2 gap-2.5 my-8">
                    <motion.div initial={{ x: -10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.3 }} className="bg-white/5 p-4 rounded-3xl border border-white/5">
                      <span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span>
                      <p className="text-xl font-black text-white">{gameState.score}</p>
                    </motion.div>
                    <motion.div initial={{ x: 10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.4 }} className="bg-white/5 p-4 rounded-3xl border border-white/5">
                      <span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('accuracyLabel')}</span>
                      <p className={`text-xl font-black ${accuracyPercent > 80 ? 'text-emerald-400' : accuracyPercent > 50 ? 'text-yellow-400' : 'text-rose-400'}`}>{accuracyPercent}%</p>
                    </motion.div>
                    <motion.div initial={{ x: -10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.5 }} className="bg-white/5 p-4 rounded-3xl border border-white/5">
                      <span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('correctAnswersLabel')}</span>
                      <p className="text-xl font-black text-emerald-400">{gameState.correctAnswers}</p>
                    </motion.div>
                    <motion.div initial={{ x: 10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.6 }} className="bg-white/5 p-4 rounded-3xl border border-white/5">
                      <span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('attemptedLabel')}</span>
                      <p className="text-xl font-black text-white/60">{gameState.questionsAnswered}</p>
                    </motion.div>
                  </div>

                  <div className="space-y-4 relative z-10">
                    <motion.button 
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={handleShare} 
                      className="w-full bg-white/10 border border-white/10 text-white font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 hover:bg-white/20 transition-all"
                    >
                      <span className="text-lg">📤</span> {t('shareBtn')}
                    </motion.button>

                    <motion.button 
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={() => setStep('HOME')} 
                      className="w-full bg-emerald-500 font-black py-5 rounded-2xl uppercase text-xs tracking-[0.2em] shadow-lg shadow-emerald-500/20"
                    >
                      {t('playAgain')}
                    </motion.button>

                    <button 
                      onClick={() => handleStartQuiz(gameState.selectedCategory)} 
                      className="w-full bg-transparent text-white/40 font-black py-3 rounded-2xl uppercase text-[9px] tracking-widest hover:text-white transition-colors"
                    >
                      {t('retry')}
                    </button>
                  </div>
                </div>
              </motion.div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-6 bg-black/60 p-4 rounded-3xl border border-white/10 backdrop-blur-xl">
                   <div className="flex flex-col"><p className="text-white/20 text-[7px] font-black uppercase">LVL {gameState.currentLevel}</p><p className="text-lg font-black text-yellow-400 leading-none">{gameState.score}</p></div>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[7px] font-black uppercase">{t('lives')}</p><div className="flex space-x-1">{[...Array(5)].map((_, i) => (<span key={i} className={`text-xs ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : ''}`}>❤️</span>))}</div></div>
                   <div className="flex flex-col items-end"><p className="text-white/20 text-[7px] font-black uppercase">Q {gameState.questionsAnswered + 1}/30</p><div className={`px-2 py-0.5 rounded-full text-[9px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/5 text-white/20'}`}>x{streak}</div></div>
