                {leaderboard.map((user, i) => (
                  <div key={i} className={`flex items-center justify-between px-4 py-3 rounded-2xl border ${user.isUser ? 'bg-emerald-500/20 border-emerald-500/40' : 'bg-white/5 border-white/5'}`}>
                    <div className="flex items-center space-x-3"><span className="font-black text-[10px] w-4 opacity-30">{i + 1}.</span><span className="font-bold text-sm">{user.name}</span></div>
                    <span className="text-emerald-400 font-black text-sm">{user.score}</span>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowLeaderboard(false)} className="w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showTrophyRoom && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6" onClick={() => setShowTrophyRoom(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="bg-black/60 border border-yellow-500/20 w-full max-w-sm rounded-[3rem] p-8" onClick={e => e.stopPropagation()}>
              <div className="text-center mb-8"><span className="text-4xl block mb-2">🏆</span><h3 className="text-white font-black text-xl uppercase tracking-tighter">{t('trophyRoom')}</h3></div>
              <div className="grid grid-cols-2 gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar mb-8">
                {ACHIEVEMENTS.map((ach) => {
                  const isUnlocked = userStats.unlockedAchievements.includes(ach.id);
                  return (
                    <div key={ach.id} className={`p-4 rounded-2xl border flex flex-col items-center text-center ${isUnlocked ? 'bg-yellow-500/10 border-yellow-500/30 shadow-[0_0_15px_rgba(234,179,8,0.1)]' : 'bg-white/5 border-white/5 opacity-40 grayscale'}`}>
                      <span className="text-3xl mb-2">{ach.icon}</span>
                      <p className="text-[9px] font-black uppercase mb-1 leading-none">{ach.name[gameState.language]}</p>
                      <p className="text-[7px] font-medium text-white/40 leading-tight">{ach.description[gameState.language]}</p>
                    </div>
                  );
                })}
              </div>
              <button onClick={() => setShowTrophyRoom(false)} className="w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-8 text-center mt-auto"><p className="text-[8px] font-black text-white/10 uppercase tracking-[0.5em]">TAP FOOTBALL QUIZ 2026</p></footer>
    </div>
  );
};

