  // Novi zvuk zvižduka za kraj vremena
  timesUp: 'https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3',
  // Lagana i neutralna no-copyright tema (Dreaming Big - Mixkit)
  bg: 'https://assets.mixkit.co/music/preview/mixkit-dreaming-big-31.mp3',
  // Blaži ambijent stadiona radi lakše atmosfere
  stadium: 'https://assets.mixkit.co/active_storage/sfx/201/201-preview.mp3'
};

class AudioService {
  private sfx: Record<string, HTMLAudioElement> = {};
  private bgMusic: HTMLAudioElement | null = null;
  private stadiumAmbience: HTMLAudioElement | null = null;
  private isMuted: boolean = false;
  private hasStarted: boolean = false;

  constructor() {
    if (typeof window !== 'undefined') {
      this.sfx.correct = new Audio(SFX_URLS.correct);
      this.sfx.wrong = new Audio(SFX_URLS.wrong);
      this.sfx.tick = new Audio(SFX_URLS.tick);
      this.sfx.timesUp = new Audio(SFX_URLS.timesUp);

      this.bgMusic = new Audio(SFX_URLS.bg);
      this.bgMusic.loop = true;
      this.bgMusic.volume = 0.08;

      this.stadiumAmbience = new Audio(SFX_URLS.stadium);
      this.stadiumAmbience.loop = true;
      this.stadiumAmbience.volume = 0.03;
    }
  }

  setMute(muted: boolean) {
    this.isMuted = muted;
    if (this.bgMusic && this.stadiumAmbience) {
      if (muted) {
        this.bgMusic.pause();
        this.stadiumAmbience.pause();
      } else if (this.hasStarted) {
        this.bgMusic.play().catch(e => console.debug('Resume blocked:', e));
        this.stadiumAmbience.play().catch(e => console.debug('Ambience blocked:', e));
      }
    }
  }

  playSfx(type: 'correct' | 'wrong' | 'tick' | 'timesUp', volume: number = 0.3) {
    if (this.isMuted) return;
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
      audio.volume = volume;
      audio.play().catch(err => console.debug('SFX blocked:', err));
    }
  }

  stopSfx(type: 'correct' | 'wrong' | 'tick' | 'timesUp') {
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
  }

  setBgMusic(playing: boolean) {
    if (!this.bgMusic || !this.stadiumAmbience) return;
    if (playing && !this.isMuted) {
      this.hasStarted = true;
      this.bgMusic.play().catch(err => console.debug('BG Music blocked:', err));
      this.stadiumAmbience.play().catch(err => console.debug('Ambience blocked:', err));
    } else {
      this.bgMusic.pause();
      this.stadiumAmbience.pause();
    }
  }
}

export const audioService = new AudioService();

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Question, Language } from '../types';
import { audioService } from '../services/audioService';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
  isMuted: boolean;
  language: Language;
  isPaused?: boolean;
}

const TRANSLATIONS = {
  correct: { Bosanski: "TAČNO!", English: "CORRECT!", Deutsch: "RICHTIG!" },
  wrong: { Bosanski: "NETAČNO!", English: "WRONG!", Deutsch: "FALSCH!" },
  difficulty: { Bosanski: "TEŽINA", English: "DIFF", Deutsch: "DIFF" },
  timesUp: { Bosanski: "VRIJEME!", English: "TIME!", Deutsch: "ZEIT!" }
};

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled, isMuted, language, isPaused }) => {
  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    if (isPaused || selected) {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
      return;
    }

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          audioService.stopSfx('tick');
          audioService.playSfx('timesUp', 0.8); // Glasan zvižduk za kraj
          handleTimeout();
          return 0;
        }

        // Logika hitnosti zvuka
        const nextVal = prev - 1;
        if (nextVal <= 3) {
          audioService.playSfx('tick', 0.8); // Visoka hitnost (glasnije)
        } else if (nextVal <= 6) {
          audioService.playSfx('tick', 0.4); // Srednja hitnost
        } else {
          audioService.playSfx('tick', 0.15); // Niska hitnost (suptilno kucanje)
        }

        return nextVal;
      });
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
    };
  }, [question.id, isPaused, selected]);

  useEffect(() => {
    setTimeLeft(10);
    setSelected(null);
    setIsWrong(false);
  }, [question.id]);

  const handleTimeout = () => {
    if (selected) return;
    setIsWrong(true);
    // Zvuk 'wrong' svira odmah nakon zvižduka da potvrdi grešku
    setTimeout(() => audioService.playSfx('wrong', 0.5), 200);
    setSelected("");
    setTimeout(() => { onAnswer(""); }, 2500);
  };

  const handleSelect = (option: string) => {
    if (disabled || selected || timeLeft <= 0 || isPaused) return;
    if (timerRef.current) clearInterval(timerRef.current);
    audioService.stopSfx('tick');

    const correct = option === question.correctAnswer;
    setSelected(option);

    if (correct) {
      audioService.playSfx('correct');
    } else {
      setIsWrong(true);
      audioService.playSfx('wrong');
    }

    setTimeout(() => { onAnswer(option); }, 3000);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      className={`relative w-full bg-black/80 backdrop-blur-3xl rounded-2xl md:rounded-3xl p-4 md:p-5 border border-white/10 shadow-2xl ${isWrong ? 'animate-shake border-rose-500/30' : ''}`}
    >
      <div className="absolute top-0 left-0 w-full h-0.5 overflow-hidden rounded-t-3xl">
        <motion.div className={`h-full ${timeLeft <= 3 ? 'bg-rose-500' : 'bg-emerald-500'}`}
          initial={{ width: "100%" }} animate={{ width: selected ? "0%" : `${(timeLeft / 10) * 100}%` }}
          transition={{ duration: selected || isPaused ? 0 : 1, ease: "linear" }}
        />
      </div>

      <div className="flex justify-between items-center mb-3 md:mb-4">
        <span className="bg-white/5 text-white/40 border border-white/5 px-1.5 py-0.5 rounded-full text-[6px] font-black uppercase tracking-widest">{question.category}</span>
        <div className="flex items-center space-x-1.5">
          <span className={`text-[8px] font-black tabular-nums ${timeLeft <= 3 ? 'text-rose-500 animate-pulse' : 'text-white/40'}`}>{timeLeft}s</span>
          <div className="flex space-x-0.5">
            {[...Array(5)].map((_, i) => (
              <div key={i} className={`w-0.5 h-1.5 md:w-1 md:h-2 rounded-full ${i < question.difficulty / 2 ? 'bg-emerald-500' : 'bg-white/5'}`} />
            ))}
          </div>
        </div>
      </div>

      <h2 className="text-xs md:text-sm font-bold text-white text-center mb-4 md:mb-6 leading-relaxed min-h-[2.5rem] md:min-h-[3rem] px-1">
        {question.text}
      </h2>

      <div className="grid grid-cols-1 gap-1.5 md:gap-2">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <button key={idx} onClick={() => handleSelect(option)} disabled={!!selected || isPaused}
              className={`p-2.5 md:p-3 rounded-lg md:rounded-xl border text-[10px] md:text-xs font-bold transition-all text-left flex items-center min-h-[44px]
                ${!selected ? 'bg-white/5 border-white/5 text-white/70 active:scale-98' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white' : ''}
                ${showCorrectIfMissed ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-10 grayscale' : ''}
              `}
            >
              <span className="w-4 h-4 md:w-5 md:h-5 flex items-center justify-center rounded bg-black/20 text-[8px] md:text-[9px] mr-2.5 md:mr-3 shrink-0">{String.fromCharCode(65 + idx)}</span>
              <span className="flex-1 truncate">{option}</span>
            </button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected !== null && (
           <motion.div initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} className="mt-3 md:mt-4 p-2.5 md:p-3 bg-white/5 border border-white/5 rounded-lg md:rounded-xl">
              {selected === "" && <p className="text-rose-500 font-black text-center text-[7px] md:text-[8px] uppercase mb-1">{t('timesUp')}</p>}
              <p className="text-white/40 text-[8px] md:text-[10px] text-center italic font-medium leading-tight">"{question.explanation}"</p>
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

