const App: React.FC = () => {
  // --- STATE WITH LOCAL STORAGE PERSISTENCE ---
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => {
