                ))}
             </div>
             <button onClick={() => setStep('LEVEL_SELECT')} className="mt-8 md:mt-10 text-[9px] md:text-[10px] font-black text-white/30 uppercase">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-3 md:p-4 w-full max-w-md mx-auto pt-10 md:pt-14">
            {gameState.isGameOver ? (
              <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center">
                <div className={`bg-black/95 backdrop-blur-3xl p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] border ${isWin ? 'border-emerald-500/40 shadow-[0_0_50px_rgba(16,185,129,0.2)]' : 'border-rose-500/40 shadow-[0_0_50px_rgba(244,63,94,0.2)]'} text-center w-full shadow-2xl overflow-hidden relative`}>
                  <div className={`absolute -top-10 -right-10 w-32 h-32 rounded-full blur-3xl opacity-20 ${isWin ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                  <motion.img initial={{ scale: 0, rotate: -180 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: "spring", damping: 10 }} src={GAME_LOGO} className="w-8 h-8 md:w-10 md:h-10 mx-auto mb-4 relative z-10" />
                  <motion.h1 initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.2 }} className={`text-3xl md:text-4xl font-black mt-2 mb-2 uppercase tracking-tighter ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</motion.h1>
                  <div className="grid grid-cols-2 gap-2 my-4 md:my-8">
                    <motion.div initial={{ x: -10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.3 }} className="bg-white/5 p-3 md:p-4 rounded-2xl border border-white/5"><span className="text-[6px] md:text-[7px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span><p className="text-lg md:text-xl font-black text-white">{gameState.score}</p></motion.div>
                    <motion.div initial={{ x: 10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.4 }} className="bg-white/5 p-3 md:p-4 rounded-2xl border border-white/5"><span className="text-[6px] md:text-[7px] font-black text-white/30 uppercase block mb-1">{t('accuracyLabel')}</span><p className={`text-lg md:text-xl font-black ${accuracyPercent > 80 ? 'text-emerald-400' : accuracyPercent > 50 ? 'text-yellow-400' : 'text-rose-400'}`}>{accuracyPercent}%</p></motion.div>
                    <motion.div initial={{ x: -10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.5 }} className="bg-white/5 p-3 md:p-4 rounded-2xl border border-white/5"><span className="text-[6px] md:text-[7px] font-black text-white/30 uppercase block mb-1">{t('correctAnswersLabel')}</span><p className="text-lg md:text-xl font-black text-emerald-400">{gameState.correctAnswers}</p></motion.div>
                    <motion.div initial={{ x: 10, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.6 }} className="bg-white/5 p-3 md:p-4 rounded-2xl border border-white/5"><span className="text-[6px] md:text-[7px] font-black text-white/30 uppercase block mb-1">{t('attemptedLabel')}</span><p className="text-lg md:text-xl font-black text-white/60">{gameState.questionsAnswered}</p></motion.div>
                  </div>
                  <div className="space-y-3 relative z-10">
                    <motion.button whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={handleShare} className="w-full bg-white/10 border border-white/10 text-white font-black py-3 rounded-xl uppercase text-[8px] md:text-[10px] tracking-widest flex items-center justify-center gap-2 hover:bg-white/20 transition-all">📤 {t('shareBtn')}</motion.button>
                    <motion.button whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => setStep('HOME')} className="w-full bg-emerald-500 font-black py-4 rounded-xl uppercase text-[10px] md:text-xs tracking-widest shadow-lg shadow-emerald-500/20">{t('playAgain')}</motion.button>
                    <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full bg-transparent text-white/40 font-black py-2 rounded-xl uppercase text-[8px] tracking-widest hover:text-white transition-colors">{t('retry')}</button>
                  </div>
                </div>
              </motion.div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-4 bg-black/60 p-2 md:p-3 rounded-2xl md:rounded-3xl border border-white/10 backdrop-blur-xl relative">
                   <button onClick={() => setIsPaused(true)} className="w-8 h-8 md:w-10 md:h-10 bg-white/10 border border-white/20 rounded-full flex items-center justify-center text-white text-xs font-black shadow-lg backdrop-blur-md">⏸</button>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[6px] md:text-[7px] font-black uppercase">LVL {gameState.currentLevel}</p><p className="text-base md:text-lg font-black text-yellow-400 leading-none">{gameState.score}</p></div>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[6px] md:text-[7px] font-black uppercase">{t('lives')}</p><div className="flex space-x-0.5">{[...Array(5)].map((_, i) => (<span key={i} className={`text-[10px] ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : ''}`}>❤️</span>))}</div></div>
                   <div className="flex flex-col items-center"><p className="text-white/20 text-[6px] md:text-[7px] font-black uppercase">Q {gameState.questionsAnswered + 1}/30</p><div className={`px-1.5 py-0.5 rounded-full text-[7px] md:text-[9px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/5 text-white/20'}`}>x{streak}</div></div>
                </header>
                <div className="w-full mb-6 h-1 bg-white/5 rounded-full overflow-hidden"><motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 30) * 100}%` }} /></div>
                <div className="flex-1 flex items-center justify-center">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? (
                      <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center justify-center space-y-4">
                        <div className="relative"><div className="w-16 h-16 border-4 border-emerald-500/10 rounded-full" /><div className="absolute top-0 w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(16,185,129,0.3)]" /></div>
                        <p className="text-emerald-500 font-black text-[10px] uppercase tracking-[0.4em] animate-pulse">{t('generating')}</p>
                      </motion.div>
                    ) : questions[currentQuestionIndex] ? (
                      <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={isPaused} isMuted={isMuted} language={gameState.language} isPaused={isPaused} />
                    ) : null}
                  </AnimatePresence>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isPaused && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[150] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-6" onClick={() => setIsPaused(false)}>
            <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="bg-black/40 border border-white/10 w-full max-w-[280px] rounded-[2rem] p-8 text-center" onClick={e => e.stopPropagation()}>
               <span className="text-3xl block mb-4">⏸</span>
               <h3 className="text-xl font-black uppercase mb-8 tracking-tighter">GAME PAUSED</h3>
               <div className="space-y-3">
                 <button onClick={() => setIsPaused(false)} className="w-full bg-emerald-500 text-white font-black py-4 rounded-xl uppercase text-xs tracking-widest">{t('resume')}</button>
                 <button onClick={handleExitGame} className="w-full bg-rose-500/20 border border-rose-500/30 text-rose-500 font-black py-3 rounded-xl uppercase text-[9px] tracking-widest">{t('exit')}</button>
               </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-4" onClick={() => setShowLeaderboard(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="bg-black/60 border border-white/10 w-full max-w-[320px] rounded-[2rem] p-6" onClick={e => e.stopPropagation()}>
              <h3 className="text-center text-white font-black text-lg uppercase mb-6">{t('leaderboard')}</h3>
              <div className="space-y-2 max-h-[300px] md:max-h-[400px] overflow-y-auto pr-1 custom-scrollbar mb-6">
                {leaderboard.map((user, i) => (
                  <div key={i} className={`flex items-center justify-between px-3 py-2.5 rounded-xl border ${user.isUser ? 'bg-emerald-500/20 border-emerald-500/40' : 'bg-white/5 border-white/5'}`}>
                    <div className="flex items-center space-x-2"><span className="font-black text-[8px] w-3 opacity-30">{i + 1}.</span><span className="font-bold text-xs">{user.name}</span></div>
                    <span className="text-emerald-400 font-black text-xs">{user.score}</span>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowLeaderboard(false)} className="w-full bg-white text-black font-black py-3.5 rounded-xl uppercase text-[9px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showTrophyRoom && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-4" onClick={() => setShowTrophyRoom(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="bg-black/60 border border-yellow-500/20 w-full max-w-[320px] rounded-[2rem] p-6" onClick={e => e.stopPropagation()}>
              <div className="text-center mb-6"><span className="text-3xl block mb-2">🏆</span><h3 className="text-white font-black text-lg uppercase tracking-tighter">{t('trophyRoom')}</h3></div>
              <div className="grid grid-cols-2 gap-2 max-h-[300px] md:max-h-[400px] overflow-y-auto pr-1 custom-scrollbar mb-6">
                {ACHIEVEMENTS.map((ach) => {
                  const isUnlocked = userStats.unlockedAchievements.includes(ach.id);
                  return (
                    <div key={ach.id} className={`p-3 rounded-xl border flex flex-col items-center text-center ${isUnlocked ? 'bg-yellow-500/10 border-yellow-500/30 shadow-[0_0_15px_rgba(234,179,8,0.1)]' : 'bg-white/5 border-white/5 opacity-40 grayscale'}`}>
