const SFX_URLS = {
  correct: 'https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3',
  wrong: 'https://assets.mixkit.co/active_storage/sfx/2019/2019-preview.mp3',
  tick: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
  timesUp: 'https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3'
};

const BGM_URL = 'https://assets.mixkit.co/music/preview/mixkit-sport-motivation-beat-582.mp3';

class AudioService {
  private sfx: Record<string, HTMLAudioElement> = {};
  private bgm: HTMLAudioElement | null = null;
  private isMuted: boolean = false;
  private shouldBePlaying: boolean = false;
  private isUnlocked: boolean = false;

  constructor() {
    if (typeof window !== 'undefined') {
      this.sfx.correct = new Audio(SFX_URLS.correct);
      this.sfx.wrong = new Audio(SFX_URLS.wrong);
      this.sfx.tick = new Audio(SFX_URLS.tick);
      this.sfx.timesUp = new Audio(SFX_URLS.timesUp);

      this.bgm = new Audio(BGM_URL);
      this.bgm.loop = true;
      this.bgm.volume = 0.15;
    }
  }

  // Poziva se pri prvoj interakciji korisnika da "otključa" audio
  unlock() {
    if (this.isUnlocked) return;
    this.isUnlocked = true;

    // Reprodukujemo tišinu da otključamo audio kontekst
    Object.values(this.sfx).forEach(a => {
      a.play().then(() => {
        a.pause();
        a.currentTime = 0;
      }).catch(() => {});
    });

    if (this.bgm) {
      this.bgm.play().then(() => {
        if (!this.shouldBePlaying || this.isMuted) {
          this.bgm?.pause();
        }
      }).catch(err => console.debug('BGM unlock error:', err));
    }
  }

  setMute(muted: boolean) {
    this.isMuted = muted;
    if (muted) {
      this.bgm?.pause();
    } else if (this.shouldBePlaying) {
      this.playBgmInternal();
    }
  }

  private playBgmInternal() {
    if (this.bgm && !this.isMuted) {
      this.bgm.play().catch(err => {
        console.debug('BGM play blocked (interaction required):', err);
      });
    }
  }

  playSfx(type: 'correct' | 'wrong' | 'tick' | 'timesUp', volume: number = 0.3) {
    if (this.isMuted) return;
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
      audio.volume = volume;
      audio.play().catch(err => console.debug('SFX blocked:', err));
    }
  }

  stopSfx(type: 'correct' | 'wrong' | 'tick' | 'timesUp') {
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
  }

  setBgMusic(playing: boolean) {
    this.shouldBePlaying = playing;
    if (playing) {
      this.playBgmInternal();
    } else {
      this.bgm?.pause();
    }
  }
}

export const audioService = new AudioService();

