              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => { setShowLeaderboard(true); handleInteraction(); }} className="h-14 md:h-16 bg-white/5 border border-white/10 text-white/60 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md">🏆 RANK</button>
                <button onClick={() => { setShowTrophyRoom(true); handleInteraction(); }} className="h-14 md:h-16 bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md">🏅 ROOM</button>
              </div>
            </div>

            <button onClick={toggleMute} className={`mt-8 text-xl p-3 rounded-full border border-white/10 backdrop-blur-md w-14 h-14 flex items-center justify-center transition-all ${isMuted ? 'bg-rose-500/20 text-rose-500' : 'bg-emerald-500/20 text-emerald-500'}`}>{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto">
