                    <span className="text-7xl md:text-8xl block drop-shadow-2xl">
                      {isWin ? '🏆' : '🏟️'}
                    </span>
                    {isWin && (
                      <motion.span 
                        animate={{ scale: [1, 1.2, 1], rotate: [0, 5, -5, 0] }} 
                        transition={{ repeat: Infinity, duration: 2 }}
                        className="absolute -top-2 -right-2 text-3xl"
                      >
                        🌟
                      </motion.span>
                    )}
                  </motion.div>

                  <h1 className={`text-4xl md:text-6xl font-black mb-2 uppercase tracking-tighter leading-none ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>
                    {isWin ? t('success') : t('gameOver')}
                  </h1>
                  <p className="text-[10px] md:text-xs font-bold text-white/30 uppercase tracking-[0.3em] mb-10">
                    {gameState.selectedCategory} • LEVEL {gameState.currentLevel}
