                    <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.3 }} className="bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('accuracyLabel')}</span>
                      <p className={`text-2xl font-black ${accuracyPercent > 80 ? 'text-emerald-400' : 'text-yellow-400'}`}>{accuracyPercent}%</p>
                    </motion.div>
                    <motion.div initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.4 }} className="bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('attemptedLabel')}</span>
                      <p className="text-2xl font-black text-white/60">{gameState.questionsAnswered}</p>
