                          {!isAll && (
                            <span className="text-[8px] font-black text-white/60 uppercase mt-1 tracking-tighter opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0">
                              PLAY NOW
                            </span>
                          )}
                        </div>
                      </div>

                      {/* High-quality highlight border effect */}
                      <div className="absolute inset-0 border-white/5 rounded-[1.8rem] pointer-events-none z-[3]" />
                    </motion.button>
                  );
                })}
             </div>
             <button onClick={() => setStep('LEVEL_SELECT')} className="mb-10 text-[11px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-4 px-8 hover:text-white transition-colors">{t('back')}</button>
          </motion.div>
        ) : (
