                <motion.div key={level.id} onClick={() => level.unlocked && (handleInteraction(), setGameState(prev => ({...prev, currentLevel: level.id})), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} className={`p-5 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/40 border-emerald-500/30 active:scale-95 hover:border-emerald-500/60' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}>
                  <div><span className="text-white/30 text-[9px] md:text-[10px] font-black uppercase block mb-1">LVL {level.id}</span><h3 className="text-xl md:text-3xl font-black uppercase">{level.name[gameState.language]}</h3></div>
                  {level.unlocked ? <span className="text-emerald-500 font-black text-sm md:text-base">GO →</span> : <span className="text-lg">🔒</span>}
