              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => { audioService.playSfx('ui_click'); setShowLeaderboard(true); handleInteraction(); }} className="h-14 md:h-16 bg-white/5 border border-white/10 text-white/60 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md hover:bg-white/10 transition-colors">🏆 RANK</button>
                <button onClick={() => { audioService.playSfx('ui_click'); setShowTrophyRoom(true); handleInteraction(); }} className="h-14 md:h-16 bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md hover:bg-yellow-500/20 transition-colors">🏅 ROOM</button>
              </div>
            </div>
            <button onClick={toggleMute} className={`mt-8 text-xl p-3 rounded-full border border-white/10 backdrop-blur-md w-14 h-14 flex items-center justify-center transition-all ${isMuted ? 'bg-rose-500/20 text-rose-500' : 'bg-emerald-500/20 text-emerald-500'}`}>{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto">
            <h2 className="text-2xl md:text-4xl font-black uppercase tracking-tighter my-8">{t('pickLevel')}</h2>
            <div className="w-full max-sm space-y-3 md:space-y-4 mb-10">
              {levels.map(level => (
                <motion.div key={level.id} onClick={() => { if(level.unlocked) { audioService.playSfx('ui_click'); handleInteraction(); setGameState(prev => ({...prev, currentLevel: level.id})); setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'); } }} className={`p-5 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/40 border-emerald-500/30 active:scale-95 hover:border-emerald-500/60' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}>
