              <button onClick={() => { audioService.playSfx('ui_click'); handleInteraction(); setStep('CATEGORY_SELECT'); }} disabled={!gameState.nickname.trim()} className="w-full h-16 md:h-20 bg-emerald-500 font-black rounded-2xl md:rounded-3xl uppercase text-sm tracking-widest disabled:opacity-20 active:scale-95 transition-all">{t('start')}</button>
