        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto w-full max-w-2xl mx-auto">
             <h2 className="text-2xl md:text-4xl font-black my-8 uppercase tracking-tighter text-white/80 text-center">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 md:grid-cols-3 gap-3 md:gap-5 w-full mb-10 px-2">
                {Object.values(Category).map(cat => {
                  const config = CATEGORY_UI_CONFIG[cat];
                  const isAll = cat === Category.ALL;
                  return (
                    <motion.button 
                      key={cat} 
                      whileHover={{ scale: 1.02, y: -4 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={() => handleStartQuiz(cat)} 
                      className={`relative overflow-hidden group p-1 rounded-[2rem] border-2 transition-all flex flex-col items-center justify-center text-center aspect-square md:aspect-auto md:h-52 ${isAll ? 'col-span-2 md:col-span-3 h-28 md:h-28 aspect-auto flex-row' : ''} border-white/10 shadow-xl`}
                    >
                      <motion.div initial={false} animate={{ scale: 1 }} whileHover={{ scale: 1.15 }} transition={{ duration: 0.6 }} style={{ backgroundImage: `url(${config.image})` }} className="absolute inset-0 bg-cover bg-center z-0" />
                      <div className={`absolute inset-0 bg-gradient-to-b ${config.gradient} opacity-80 z-[1]`} />
                      <div className={`relative z-[2] flex flex-col items-center justify-center w-full h-full p-4 ${isAll ? 'flex-row space-x-4' : ''}`}>
                        <span className={`${isAll ? 'text-3xl' : 'text-4xl md:text-5xl'} mb-3 md:mb-4 drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]`}>
                          {config.icon}
                        </span>
                        <div className="flex flex-col items-center">
                          <h3 className={`font-black uppercase tracking-widest text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] ${isAll ? 'text-sm md:text-lg' : 'text-[10px] md:text-xs'} leading-tight`}>
                            {CATEGORY_TRANSLATIONS[cat][gameState.language]}
                          </h3>
                          {!isAll && (
                            <span className="text-[8px] font-black text-white/60 uppercase mt-1 tracking-tighter opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0">
                              PLAY NOW
                            </span>
                          )}
                        </div>
                      </div>
                      <div className="absolute inset-0 border-white/5 rounded-[1.8rem] pointer-events-none z-[3]" />
                    </motion.button>
                  );
                })}
             </div>
             <button onClick={() => { audioService.playSfx('ui_back'); setStep('LEVEL_SELECT'); }} className="mb-10 text-[11px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-4 px-8 hover:text-white transition-colors">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col w-full max-w-xl mx-auto safe-pt safe-pb h-full">
            {gameState.isGameOver ? (
              <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4 relative">
                {isWin && <Confetti color="bg-emerald-400" />}
                {!isWin && <Confetti color="bg-rose-400" />}
                <div className={`bg-black/90 backdrop-blur-3xl p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] border relative overflow-hidden ${isWin ? 'border-emerald-500/40 shadow-[0_0_80px_rgba(16,185,129,0.2)]' : 'border-rose-500/40 shadow-[0_0_80px_rgba(244,63,94,0.2)]'} text-center w-full max-w-[420px] shadow-2xl`}>
                  <div className={`absolute top-0 left-0 w-full h-2 ${isWin ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                  <motion.div initial={{ scale: 0.5, rotate: -10 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: 'spring', damping: 10 }} className="mb-6 relative">
                    <span className="text-7xl md:text-8xl block drop-shadow-2xl">{isWin ? '🏆' : '🏟️'}</span>
                    {isWin && (<motion.span animate={{ scale: [1, 1.2, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 2 }} className="absolute -top-2 -right-2 text-3xl">🌟</motion.span>)}
                  </motion.div>
                  <h1 className={`text-4xl md:text-6xl font-black mb-2 uppercase tracking-tighter leading-none ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                  <p className="text-[10px] md:text-xs font-bold text-white/30 uppercase tracking-[0.3em] mb-10">{gameState.selectedCategory} • LEVEL {gameState.currentLevel}</p>
                  <div className="grid grid-cols-2 gap-3 mb-10">
                    <motion.div initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.2 }} className="bg-white/5 p-4 rounded-2xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span><p className="text-2xl font-black text-white">{gameState.score}</p></motion.div>
                    <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.3 }} className="bg-white/5 p-4 rounded-2xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('accuracyLabel')}</span><p className={`text-2xl font-black ${accuracyPercent > 80 ? 'text-emerald-400' : 'text-yellow-400'}`}>{accuracyPercent}%</p></motion.div>
                    <motion.div initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.4 }} className="bg-white/5 p-4 rounded-2xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('attemptedLabel')}</span><p className="text-2xl font-black text-white/60">{gameState.questionsAnswered}</p></motion.div>
                    <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ delay: 0.5 }} className="bg-white/5 p-4 rounded-2xl border border-white/5"><span className="text-[8px] font-black text-white/30 uppercase block mb-1">{t('correctAnswersLabel')}</span><p className="text-2xl font-black text-emerald-400">{gameState.correctAnswers}</p></motion.div>
                  </div>
                  <div className="space-y-3 relative z-10">
                    <button onClick={() => { audioService.playSfx('ui_click'); setStep('HOME'); }} className="w-full h-16 bg-emerald-500 text-white font-black rounded-2xl uppercase text-xs tracking-widest active:scale-95 transition-all shadow-lg shadow-emerald-500/20">{t('playAgain')}</button>
                    <button onClick={handleShare} className="w-full h-14 bg-white/10 border border-white/10 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:bg-white/20 transition-all flex items-center justify-center gap-2">📤 {t('shareBtn')}</button>
                    <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full h-12 text-white/40 font-black uppercase text-[10px] tracking-widest hover:text-white transition-colors">{t('retry')}</button>
                  </div>
                </div>
              </motion.div>
            ) : (
              <div className="flex-1 flex flex-col p-4 h-full relative">
                <header className="flex justify-between items-center mb-4 bg-black/40 p-3 md:p-4 rounded-[1.5rem] md:rounded-[2.5rem] border border-white/10 backdrop-blur-xl shrink-0">
                   <div className="flex gap-2">
                     <button onClick={() => { audioService.playSfx('ui_click'); setIsPaused(true); }} className="w-10 h-10 md:w-12 md:h-12 bg-white/5 border border-white/10 rounded-full flex items-center justify-center text-sm active:scale-90 transition-transform">⏸</button>
                     <button onClick={handleExitGame} className="px-3 h-10 md:h-12 bg-rose-500/10 border border-rose-500/20 text-rose-500 rounded-full flex items-center justify-center text-[10px] font-black tracking-widest active:scale-90 transition-transform uppercase">{t('exit')}</button>
                   </div>
                   <div className="text-center">
                     <p className="text-white/30 text-[8px] font-black uppercase mb-0.5">LVL {gameState.currentLevel} • {gameState.score}</p>
                     <div className="flex gap-0.5">{[...Array(5)].map((_, i) => (<span key={i} className={`text-xs ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : 'drop-shadow-glow'}`}>❤️</span>))}</div>
                   </div>
                   <div className="text-right">
                     <p className="text-white/30 text-[8px] font-black uppercase mb-0.5">Q {gameState.questionsAnswered + 1}/30</p>
                     <div className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/10 text-white/30'}`}>x{streak}</div>
                   </div>
                </header>
                <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden mb-6 shrink-0"><motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 30) * 100}%` }} transition={{ duration: 0.5 }} /></div>

                <div className="flex-1 flex flex-col justify-center min-h-0 relative">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? (
                      <motion.div 
                        key="loader" 
                        initial={{ opacity: 0, scale: 0.8 }} 
                        animate={{ opacity: 1, scale: 1 }} 
                        exit={{ opacity: 0, scale: 1.1 }} 
                        className="flex-1 flex flex-col items-center justify-center space-y-8 py-20"
                      >
                        <div className="relative">
                          <motion.div 
                            animate={{ rotate: 360 }} 
                            transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }}
                            className="w-24 h-24 md:w-32 md:h-32 border-[6px] border-emerald-500/10 border-t-emerald-500 rounded-full" 
                          />
                          <motion.div 
                            animate={{ rotate: -360 }} 
                            transition={{ repeat: Infinity, duration: 2, ease: "linear" }}
                            className="absolute top-4 left-4 w-16 h-16 md:w-24 md:h-24 border-[4px] border-emerald-500/5 border-b-emerald-400 rounded-full" 
