  const pool = explanations[lang] || explanations['English'];
  const categoryPool = pool[category] || pool[Category.ALL];

  const text = q.text || "";
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = text.charCodeAt(i) + ((hash << 5) - hash);
  }
  const index = Math.abs(hash) % categoryPool.length;

  return categoryPool[index];
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number): Question[] => {
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'];

  let filtered = langPool.filter(q => category === Category.ALL || q.category === category);
  if (filtered.length === 0) filtered = langPool;

  const shuffled = [...filtered].sort(() => 0.5 - Math.random());

  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: `offline-${Date.now()}-${Math.random()}`,
    difficulty: difficulty,
    explanation: getEnhancedExplanation(q, language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<{ questions: Question[], isOffline: boolean }> => {

  if (!navigator.onLine) {
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }

  // Initialize inside the function to ensure fresh API Key usage
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Strictly English instructions for structural integrity, content in target language
  const prompt = `Generate ${count} football trivia questions in the following language: ${language}.
  Category: ${category}.
  Difficulty level: ${difficulty} (on a scale of 1-10, where 1 is for casual fans and 10 is for hardcore experts).
  Each question must have exactly 4 options and one correct answer.
  IMPORTANT: Include an "explanation" field for each question in ${language} explaining why the answer is correct.
  The JSON keys must be: id, text, options, correctAnswer, explanation.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    let jsonStr = response.text || "";
    // Clean potential markdown leftovers
    jsonStr = jsonStr.replace(/```json/g, '').replace(/```/g, '').trim();

    if (!jsonStr) throw new Error("Empty response");

    const parsed = JSON.parse(jsonStr);
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.warn("Gemini API error for language " + language + ", falling back to offline mode:", error);
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count), 
      isOffline: true 
    };
  }
};

