import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";
import { LOCAL_QUESTIONS } from "../data/localQuestions";

const langNames: Record<Language, string> = {
  'Bosanski': 'Bosnian',
  'English': 'English',
  'Deutsch': 'German'
};

const getEnhancedExplanation = (q: Partial<Question>, lang: Language): string => {
  if (q.explanation) return q.explanation;
  const pool = explanations[lang] || explanations['English'];
  const category = q.category || Category.ALL;
  const categoryPool = pool[category] || pool[Category.ALL];
  const text = q.text || "";
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = text.charCodeAt(i) + ((hash << 5) - hash);
  const index = Math.abs(hash) % categoryPool.length;
  return categoryPool[index];
};

const explanations: Record<Language, Record<string, string[]>> = {
  'Bosanski': {
    [Category.ALL]: ["Ovaj podatak je potvrđen kroz zvaničnu statistiku saveza i klubova."]
  },
  'English': {
    [Category.ALL]: ["This record is officially documented in club and league statistics."]
  },
  'Deutsch': {
    [Category.ALL]: ["Diese Information ist ein wesentlicher Teil der Fußballkultur."]
  }
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number): Question[] => {
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'];
  let filtered = langPool.filter(q => category === Category.ALL || q.category === category);
  if (filtered.length === 0) filtered = langPool;
  const shuffled = [...filtered].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: `offline-${Date.now()}-${Math.random()}`,
    difficulty: difficulty,
    explanation: getEnhancedExplanation(q, language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5
): Promise<{ questions: Question[], isOffline: boolean }> => {
  if (!navigator.onLine) return { questions: getOfflineQuestions(category, language, difficulty, count), isOffline: true };

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const targetLang = langNames[language] || 'English';

  const prompt = `Generate ${count} football trivia questions. 
  The text content must be in the following language: ${targetLang}.
  Category: ${category}.
  Difficulty level: ${difficulty} (1 to 10).
  IMPORTANT: The JSON keys must be exactly: "id", "text", "options", "correctAnswer", "explanation". 
  Do NOT translate the JSON keys.
  Include 4 options and one correct answer for each.
  Provide a brief explanation why the answer is correct in ${targetLang}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    let jsonStr = response.text || "";
    jsonStr = jsonStr.replace(/```json/g, '').replace(/```/g, '').trim();
    if (!jsonStr) throw new Error("Empty response");

    const parsed = JSON.parse(jsonStr);
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.warn(`API error for ${language}, using offline questions.`, error);
    return { questions: getOfflineQuestions(category, language, difficulty, count), isOffline: true };
  }
};

