);

const App: React.FC = () => {
  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(localStorage.getItem('quiz_muted') || 'false'));
  const [levels, setLevels] = useState<LevelConfig[]>(() => {
    const saved = localStorage.getItem('quiz_levels');
    return saved ? JSON.parse(saved) : INITIAL_LEVELS;
  });
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    const saved = localStorage.getItem('quiz_leaderboard');
    return saved ? JSON.parse(saved) : BASE_LEADERBOARD;
  });
  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('quiz_user_stats');
    return saved ? JSON.parse(saved) : { totalPoints: 0, totalCorrect: 0, totalAnswered: 0, maxStreak: 0, levelsCompleted: [], unlockedAchievements: [] };
  });

  const [gameState, setGameState] = useState<GameState>(() => {
    const savedLangRaw = localStorage.getItem('quiz_language');
    const validLangs: Language[] = ['Bosanski', 'English', 'Deutsch'];
    const initialLang: Language = validLangs.includes(savedLangRaw as Language) ? (savedLangRaw as Language) : 'English';

    return {
      nickname: localStorage.getItem('quiz_nickname') || '',
      currentLevel: 1,
      selectedCategory: Category.ALL,
      score: 0,
      questionsAnswered: 0,
      correctAnswers: 0,
      mistakes: 0,
      isGameOver: false,
      language: initialLang,
      history: [],
    };
  });

  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(0);

  useEffect(() => {
    localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
    audioService.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
  }, [userStats]);

  useEffect(() => {
    localStorage.setItem('quiz_levels', JSON.stringify(levels));
  }, [levels]);

  useEffect(() => {
    localStorage.setItem('quiz_nickname', gameState.nickname);
  }, [gameState.nickname]);

  useEffect(() => {
    localStorage.setItem('quiz_language', gameState.language);
  }, [gameState.language]);

  const [hasInteracted, setHasInteracted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [unlockedToast, setUnlockedToast] = useState<Achievement | null>(null);

  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const checkAchievements = useCallback((newStats: UserStats, currentStreak: number, isPerfect: boolean = false) => {
    const newUnlocks: string[] = [];
    ACHIEVEMENTS.forEach(ach => {
      if (newStats.unlockedAchievements.includes(ach.id)) return;

      let condition = false;
      if (ach.type === 'total_correct') condition = newStats.totalCorrect >= ach.requirement;
      if (ach.type === 'streak') condition = currentStreak >= ach.requirement;
      if (ach.type === 'perfect_game') condition = isPerfect;
      if (ach.type === 'level_completed') condition = newStats.levelsCompleted.includes(ach.requirement);

      if (condition) {
        newUnlocks.push(ach.id);
        setUnlockedToast(ach);
        audioService.playSfx('correct', 1);
        setTimeout(() => setUnlockedToast(null), 4000);
      }
    });

    if (newUnlocks.length > 0) {
      setUserStats(prev => ({ ...prev, unlockedAchievements: [...prev.unlockedAchievements, ...newUnlocks] }));
    }
  }, []);

  const handleInteraction = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.unlock();
      audioService.setBgMusic(true);
    }
  };

  const toggleMute = () => {
    handleInteraction();
    setIsMuted(prev => !prev);
  };

  const fetchBatch = useCallback(async (
    levelId: number, 
    category: Category, 
    lang: Language, 
    progress: number,
    correct: number,
    currentStreak: number,
    totalTimeLeftInSession: number
  ) => {
    setLoading(true);
    const config = levels.find(l => l.id === levelId) || levels[0];

    const progressRatio = progress / 30;
    let dynamicDiff = config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio;

    const accuracy = progress > 0 ? correct / progress : 1;
    const accuracyModifier = (accuracy - 0.75) * 3;

    const streakBonus = Math.floor(currentStreak / 3) * 0.5;

    const avgTimeLeft = progress > 0 ? totalTimeLeftInSession / progress : 5;
    const speedModifier = (avgTimeLeft - 5) * 0.2;

    dynamicDiff += accuracyModifier + streakBonus + speedModifier;

    const finalDiff = Math.min(
      config.maxDifficulty,
      Math.max(config.minDifficulty, Math.round(dynamicDiff))
    );

    const result = await generateQuestions(category, finalDiff, lang, 5);
    setQuestions(prev => [...prev, ...result.questions]);
    setLoading(false);
  }, [levels]);

  useEffect(() => {
    if (step === 'QUIZ' && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 30 && !gameState.isGameOver) {
      fetchBatch(
        gameState.currentLevel, 
        gameState.selectedCategory, 
        gameState.language, 
        gameState.questionsAnswered,
        gameState.correctAnswers,
        streak,
        sessionTimeLeft
      );
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.correctAnswers, streak, sessionTimeLeft, gameState.isGameOver, fetchBatch]);

  const handleStartQuiz = (category: Category) => {
    handleInteraction();
    audioService.playSfx('ui_click');
    setGameState(prev => ({ 
      ...prev, 
      selectedCategory: category, 
      score: 0, 
      questionsAnswered: 0, 
      correctAnswers: 0, 
      mistakes: 0, 
      isGameOver: false, 
      history: [] 
    }));
    setSessionTimeLeft(0);
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setIsPaused(false);
    setShowExitConfirm(false);
    setLoading(true);
    setStep('QUIZ');
  };

  const handleAnswer = (answer: string, timeLeft: number) => {
    if (isPaused || showExitConfirm) return;
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;

    const speedMultiplier = 1 + (timeLeft / 20);
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * speedMultiplier * (1 + Math.floor(newStreak / 5) * 0.5)) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 30) || newMistakes >= 5;

    setSessionTimeLeft(prev => prev + timeLeft);

    const updatedStats = {
      ...userStats,
      totalPoints: userStats.totalPoints + points,
      totalCorrect: isCorrect ? userStats.totalCorrect + 1 : userStats.totalCorrect,
      totalAnswered: userStats.totalAnswered + 1,
      maxStreak: Math.max(userStats.maxStreak, newStreak)
    };
    setUserStats(updatedStats);
    checkAchievements(updatedStats, newStreak);

    if (isOver) {
      const isPerfect = newMistakes === 0 && (gameState.questionsAnswered + 1 >= 30);
      if (isPerfect) checkAchievements(updatedStats, newStreak, true);

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setUserStats(prev => ({
          ...prev,
          levelsCompleted: [...new Set([...prev.levelsCompleted, gameState.currentLevel])]
        }));
      }

      setLeaderboard(prev => {
        const updated = [...prev, { name: gameState.nickname || 'Player', score: gameState.score + points, country: LANGUAGE_FLAGS[gameState.language], timestamp: Date.now(), isUser: true }].sort((a, b) => b.score - a.score).slice(0, 20);
        localStorage.setItem('quiz_leaderboard', JSON.stringify(updated));
        return updated;
      });

      if (gameState.questionsAnswered + 1 >= 30 && newMistakes < 5) {
        setLevels(prev => prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l));
      }
    }

    setGameState(prev => ({
      ...prev,
      score: prev.score + points,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  };

  const resetAllProgress = () => {
    if (window.confirm(t('resetConfirm'))) {
      audioService.playSfx('ui_back');
      localStorage.clear();
      window.location.reload();
    }
  };

  const handleShare = async () => {
    const accuracy = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);
    const text = t('shareText')
      .replace('{score}', gameState.score.toString())
      .replace('{accuracy}', accuracy.toString());

    const url = window.location.href;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'TAP FOOTBALL 2026',
          text: text,
          url: url,
        });
      } catch (err: any) {
        if (err.name === 'TypeError' || err.message?.includes('URL')) {
          try {
            await navigator.share({
              title: 'TAP FOOTBALL 2026',
              text: `${text} ${url}`,
            });
          } catch (secondErr) {
            console.error('Share fallback failed:', secondErr);
          }
        } else if (err.name !== 'AbortError') {
          console.error('Share failed:', err);
        }
      }
    } else {
      const shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text + " " + url)}`;
      window.open(shareUrl, '_blank');
      navigator.clipboard.writeText(`${text} ${url}`);
      alert(t('copied'));
    }
  };

  const handleExitGame = () => {
    audioService.playSfx('ui_click');
    setIsPaused(false);
    setShowExitConfirm(true);
  };

  const confirmExit = () => {
    audioService.playSfx('ui_back');
    setStep('HOME');
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setLoading(false);
    setIsPaused(false);
    setShowExitConfirm(false);
    setGameState(prev => ({ ...prev, isGameOver: false }));
  };

  const t = (key: keyof typeof TRANSLATIONS) => {
    const lang = gameState.language || 'English';
    const entry = TRANSLATIONS[key];
    if (!entry) return key;
    return entry[lang] || entry['English'] || key;
  };

  const isWin = gameState.questionsAnswered >= 30 && gameState.mistakes < 5;
  const accuracyPercent = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);

  // Common button interaction variants
  const btnInteraction = {
    hover: { scale: 1.02, transition: { duration: 0.2 } },
    tap: { scale: 0.92, transition: { duration: 0.1 } }
  };

  return (
    <div className="flex-1 flex flex-col h-full grass-pattern relative overflow-hidden" onClick={handleInteraction}>
      <AnimatePresence>
        {unlockedToast && (
          <motion.div initial={{ y: -100, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ y: -100, opacity: 0 }} className="fixed top-0 left-1/2 -translate-x-1/2 z-[200] w-[90%] max-w-sm pointer-events-none">
            <div className="bg-emerald-500 rounded-2xl p-4 shadow-[0_20px_40px_rgba(16,185,129,0.4)] border border-emerald-400 flex items-center space-x-4">
              <span className="text-3xl shrink-0">{unlockedToast.icon}</span>
              <div>
                <p className="text-[10px] font-black text-white/60 uppercase tracking-widest leading-none mb-1">{t('unlockedToast')}</p>
                <p className="text-sm font-bold uppercase">{unlockedToast.name[gameState.language] || unlockedToast.name['English']}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div key="landing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 1.1 }} className="flex-1 flex flex-col items-center justify-center p-4 md:p-8 safe-pt safe-pb">
            <div className="mb-6 md:mb-10 flex flex-col items-center w-full max-w-md">
              <div className="grid grid-cols-3 gap-3 w-full mb-8">
                {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => {
                  const isSelected = gameState.language === lang;
                  return (
                    <motion.button 
                      key={lang} 
                      whileHover={btnInteraction.hover}
                      whileTap={btnInteraction.tap}
                      onClick={(e) => { 
                        e.stopPropagation();
                        setGameState(prev => ({ ...prev, language: lang })); 
                        audioService.playSfx('ui_click'); 
                        handleInteraction(); 
                      }} 
                      className={`relative flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all duration-300 ${isSelected ? 'bg-emerald-500/10 border-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.2)]' : 'bg-white/5 border-white/5 opacity-50'}`}
                    >
                      <span className="text-2xl md:text-3xl mb-1">{LANGUAGE_FLAGS[lang]}</span>
                      <span className={`text-[8px] md:text-[10px] font-black uppercase tracking-widest ${isSelected ? 'text-emerald-400' : 'text-white/40'}`}>
                        {lang.substring(0, 3)}
                      </span>
                      {isSelected && (
                        <motion.div layoutId="lang-active" className="absolute -bottom-1 w-1 h-1 bg-emerald-500 rounded-full" />
                      )}
                    </motion.button>
                  );
                })}
              </div>
              <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="w-14 h-14 md:w-20 md:h-20 mx-auto mb-6 drop-shadow-[0_0_30px_rgba(16,185,129,0.5)]" />
              <motion.h1 className="text-4xl md:text-7xl font-black tracking-tighter uppercase leading-[0.9] text-center mb-2 drop-shadow-2xl mobile-title">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></motion.h1>
              <motion.p className="text-[10px] md:text-xs font-bold text-white/40 tracking-[0.3em] uppercase">{t('subTitle')}</motion.p>
            </div>
            <div className="w-full max-w-[320px] space-y-3 md:space-y-4 mobile-compact">
              <motion.button 
                whileHover={btnInteraction.hover} 
                whileTap={btnInteraction.tap} 
                onClick={(e) => { 
                  e.stopPropagation();
                  setStep('LEVEL_SELECT'); 
                  audioService.playSfx('ui_click'); 
                  handleInteraction(); 
                }} 
                className="w-full h-16 md:h-20 bg-emerald-500 text-white font-black rounded-2xl md:rounded-3xl shadow-[0_15px_40px_rgba(16,185,129,0.3)] uppercase text-sm md:text-base tracking-[0.2em] btn-glow"
              >
                {t('startGame')}
              </motion.button>
              <div className="grid grid-cols-2 gap-3">
                <motion.button 
                  whileHover={btnInteraction.hover}
                  whileTap={btnInteraction.tap}
                  onClick={(e) => { e.stopPropagation(); audioService.playSfx('ui_click'); setShowLeaderboard(true); handleInteraction(); }} 
                  className="h-14 md:h-16 bg-white/5 border border-white/10 text-white/60 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md hover:bg-white/10 transition-colors"
                >
                  🏆 RANK
                </motion.button>
                <motion.button 
                  whileHover={btnInteraction.hover}
                  whileTap={btnInteraction.tap}
                  onClick={(e) => { e.stopPropagation(); audioService.playSfx('ui_click'); setShowTrophyRoom(true); handleInteraction(); }} 
                  className="h-14 md:h-16 bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black rounded-xl md:rounded-2xl uppercase text-[10px] tracking-widest backdrop-blur-md hover:bg-yellow-500/20 transition-colors"
                >
                  🏅 ROOM
                </motion.button>
              </div>
            </div>
            <motion.button 
              whileHover={btnInteraction.hover}
              whileTap={btnInteraction.tap}
              onClick={(e) => { e.stopPropagation(); toggleMute(); }} 
              className={`mt-8 text-xl p-3 rounded-full border border-white/10 backdrop-blur-md w-14 h-14 flex items-center justify-center transition-all ${isMuted ? 'bg-rose-500/20 text-rose-500' : 'bg-emerald-500/20 text-emerald-500'}`}
            >
              {isMuted ? '🔇' : '🔊'}
            </motion.button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto">
            <h2 className="text-2xl md:text-4xl font-black uppercase tracking-tighter my-8">{t('pickLevel')}</h2>
            <div className="w-full max-sm space-y-3 md:space-y-4 mb-10">
              {levels.map(level => (
                <motion.div 
                  key={level.id} 
                  whileHover={level.unlocked ? btnInteraction.hover : {}}
                  whileTap={level.unlocked ? btnInteraction.tap : {}}
                  onClick={() => { if(level.unlocked) { audioService.playSfx('ui_click'); handleInteraction(); setGameState(prev => ({...prev, currentLevel: level.id})); setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'); } }} 
                  className={`p-5 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] border transition-all cursor-pointer flex justify-between items-center ${level.unlocked ? 'bg-black/40 border-emerald-500/30 hover:border-emerald-500/60' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}
                >
                  <div><span className="text-white/30 text-[9px] md:text-[10px] font-black uppercase block mb-1">LVL {level.id}</span><h3 className="text-xl md:text-3xl font-black uppercase">{level.name[gameState.language] || level.name['English']}</h3></div>
                  {level.unlocked ? <span className="text-emerald-500 font-black text-sm md:text-base">GO →</span> : <span className="text-lg">🔒</span>}
                </motion.div>
              ))}
            </div>
            <motion.button 
              whileHover={btnInteraction.hover}
              whileTap={btnInteraction.tap}
              onClick={() => { audioService.playSfx('ui_back'); setStep('HOME'); }} 
              className="mt-auto mb-4 text-[11px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-4 px-8 active:text-white"
            >
              {t('back')}
            </motion.button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4 safe-pt safe-pb">
            <div className="bg-black/60 backdrop-blur-2xl p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] border border-white/10 w-full max-w-[360px] text-center shadow-2xl">
              <h2 className="text-2xl md:text-3xl font-black mb-8 uppercase tracking-tighter">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} placeholder="Messi10..." onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))} className="w-full h-16 md:h-20 bg-white/5 border border-white/10 rounded-2xl md:rounded-3xl px-6 text-white text-xl font-bold mb-8 focus:outline-none focus:border-emerald-500 text-center placeholder:text-white/10" />
              <motion.button 
                whileHover={gameState.nickname.trim() ? btnInteraction.hover : {}}
                whileTap={gameState.nickname.trim() ? btnInteraction.tap : {}}
                onClick={() => { audioService.playSfx('ui_click'); handleInteraction(); setStep('CATEGORY_SELECT'); }} 
                disabled={!gameState.nickname.trim()} 
                className="w-full h-16 md:h-20 bg-emerald-500 font-black rounded-2xl md:rounded-3xl uppercase text-sm tracking-widest disabled:opacity-20 transition-all"
              >
                {t('start')}
              </motion.button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto w-full max-w-2xl mx-auto">
             <h2 className="text-2xl md:text-4xl font-black my-8 uppercase tracking-tighter text-white/80 text-center">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 md:grid-cols-3 gap-3 md:gap-5 w-full mb-10 px-2">
                {Object.values(Category).map(cat => {
                  const config = CATEGORY_UI_CONFIG[cat];
                  const isAll = cat === Category.ALL;
                  return (
                    <motion.button 
                      key={cat} 
                      whileHover={{ ...btnInteraction.hover, y: -4 }}
