                  <button key={lang} onClick={(e) => { e.stopPropagation(); handleInteraction(); setGameState(prev => ({ ...prev, language: lang })); }} className={`w-10 h-10 flex items-center justify-center rounded-full text-xl transition-all ${gameState.language === lang ? 'bg-white/10 scale-110 drop-shadow-xl' : 'opacity-40 grayscale'}`}>{LANGUAGE_FLAGS[lang]}</button>
