              <motion.p className="text-[10px] md:text-xs font-bold text-white/40 tracking-[0.3em] uppercase">{t('subTitle')}</motion.p>
            </div>

            <div className="w-full max-w-[320px] space-y-3 md:space-y-4 mobile-compact">
              <motion.button whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => { handleInteraction(); setStep('LEVEL_SELECT'); }} className="w-full h-16 md:h-20 bg-emerald-500 text-white font-black rounded-2xl md:rounded-3xl shadow-[0_15px_40px_rgba(16,185,129,0.3)] uppercase text-sm md:text-base tracking-[0.2em] btn-glow">{t('startGame')}</motion.button>
