const SFX_URLS = {
  correct: 'https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3', // Win/Success
  wrong: 'https://assets.mixkit.co/active_storage/sfx/2019/2019-preview.mp3',   // Error/Buzzer
  tick: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',    // Clock tick
  timesUp: 'https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3',   // Time out
  playAgain: 'https://assets.mixkit.co/active_storage/sfx/2013/2013-preview.mp3', // Level start/Restart
  exit: 'https://assets.mixkit.co/active_storage/sfx/2017/2017-preview.mp3',      // Back/Transition
  click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'     // Standard UI click
};

type SfxType = keyof typeof SFX_URLS;

class AudioService {
  private sfx: Record<string, HTMLAudioElement> = {};
  private isMuted: boolean = false;

  constructor() {
    if (typeof window !== 'undefined') {
      Object.entries(SFX_URLS).forEach(([key, url]) => {
        this.sfx[key] = new Audio(url);
      });
    }
  }

  unlock() {
    if (typeof window !== 'undefined') {
      Object.values(this.sfx).forEach(audio => {
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.then(() => {
            audio.pause();
            audio.currentTime = 0;
          }).catch(err => console.debug('Audio unlock skipped:', err));
        }
      });
    }
  }

  setMute(muted: boolean) {
    this.isMuted = muted;
  }

  playSfx(type: SfxType | string, volume: number = 0.3) {
    if (this.isMuted) return;
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
      audio.volume = volume;
      audio.play().catch(err => console.debug('SFX blocked:', err));
    }
  }

  stopSfx(type: SfxType | string) {
    const audio = this.sfx[type];
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
  }

  setBgMusic(playing: boolean) {
    // Background music is currently disabled as per previous requests
  }
}

