                    <button onClick={() => { handleInteraction(); audioService.playSfx('playAgain'); setStep('HOME'); }} className="w-full h-16 bg-emerald-500 font-black rounded-2xl uppercase text-xs tracking-widest active:scale-95 transition-all">{t('playAgain')}</button>
