                    else if (ach.type === 'streak') progress = userStats.maxStreak;
                    else if (ach.type === 'category_mastery' && ach.category) progress = userStats.categoryCorrect[ach.category] || 0;
                    else if (ach.type === 'high_score') progress = 0; // Not a cumulative stat for room display
                    else if (ach.type === 'perfect_game') progress = isUnlocked ? 1 : 0;

                    const progressPercent = Math.min(100, (progress / ach.requirement) * 100);

                    return (
                      <div key={ach.id} className={`p-4 rounded-2xl border flex flex-col items-center text-center transition-all ${isUnlocked ? 'bg-yellow-500/10 border-yellow-500/30 shadow-xl' : 'bg-white/5 border-white/5 opacity-60'}`}>
