             <h2 className="text-xl md:text-4xl font-black my-6 md:my-8 uppercase tracking-tighter text-white/40">{t('selectCategory')}</h2>
             <div className="grid grid-cols-2 gap-3 md:gap-6 w-full max-w-[480px] mb-12">
                {Object.values(Category).map((cat, index) => {
                  const visual = CATEGORY_VISUALS[cat];
                  const isAll = cat === Category.ALL;
                  const isDoneInCurrentLevel = (userStats.completedLevelCategories[gameState.currentLevel] || []).includes(cat);

                  return (
                    <motion.div
                      key={cat}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.05 }}
                      onClick={() => handleStartQuiz(cat)}
                      className={`group relative overflow-hidden cursor-pointer rounded-2xl md:rounded-[2rem] border p-4 md:p-8 transition-all active:scale-95 shadow-xl ${
                        isAll 
                        ? 'col-span-2 bg-emerald-500 border-emerald-400 shadow-[0_10px_30px_rgba(16,185,129,0.3)]' 
                        : 'bg-white/5 border-white/10 hover:bg-white/10 hover:border-white/20'
                      }`}
                    >
                      <div className={`absolute inset-0 bg-gradient-to-br ${visual.gradient} opacity-0 group-hover:opacity-100 transition-opacity`} />

                      <div className="relative z-10 flex flex-col items-center text-center">
                        <span className="text-3xl md:text-6xl mb-3 transform group-hover:scale-110 transition-transform duration-300 drop-shadow-lg">
                          {visual.icon}
                        </span>
                        <div className="flex items-center gap-2">
                          <span className={`text-[9px] md:text-xs font-black tracking-widest uppercase ${isAll ? 'text-white' : 'text-white/60 group-hover:text-white'}`}>
                            {CATEGORY_TRANSLATIONS[cat][gameState.language] || CATEGORY_TRANSLATIONS[cat]['English']}
                          </span>
                          {isDoneInCurrentLevel && <span className="text-emerald-400 text-[8px] md:text-xs shrink-0">✅</span>}
                        </div>
                      </div>

                      <div className="absolute -top-1/2 -left-1/2 w-[200%] h-[200%] bg-gradient-to-br from-white/5 to-transparent rotate-45 pointer-events-none transform translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
                    </motion.div>
                  );
                })}
             </div>
             <button onClick={() => { audioService.playSfx('exit', 0.5, true); setStep('LEVEL_SELECT'); }} className="mt-auto mb-4 text-[10px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-3 px-8">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col w-full max-w-xl mx-auto safe-pt safe-pb h-full overflow-hidden">
            {gameState.isGameOver ? (
              <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4">
                <div className={`bg-black/90 backdrop-blur-3xl p-6 md:p-12 rounded-[2rem] md:rounded-[4rem] border ${isWin ? 'border-emerald-500/40 shadow-[0_0_80px_rgba(16,185,129,0.15)]' : 'border-rose-500/40 shadow-[0_0_80px_rgba(244,63,94,0.15)]'} text-center w-full max-w-[360px] shadow-2xl relative overflow-hidden`}>
                  <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="w-10 h-10 md:w-16 mx-auto mb-4 md:mb-6" />
                  <h1 className={`text-2xl md:text-5xl font-black mb-4 md:mb-6 uppercase tracking-tighter leading-none ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
