import { LOCAL_QUESTIONS } from "../data/localQuestions";

/**
 * Provides a professional, category-specific fallback explanation if one is missing.
 */
const getEnhancedExplanation = (q: Partial<Question>, lang: Language): string => {
  if (q.explanation) return q.explanation;

  const category = q.category || Category.ALL;

  const explanations: Record<Language, Record<string, string[]>> = {
    'Bosanski': {
      [Category.PLAYERS]: ["Ovaj podatak je potvrđen kroz zvaničnu statistiku."],
      [Category.CLUBS]: ["Klupska historija potvrđuje tačnost ovog odgovora."],
      [Category.STADIUMS]: ["Stadion je postao legendaran zbog ovih činjenica."],
      [Category.NATIONAL_TEAMS]: ["Reprezentativni uspjesi su dokumentovani u FIFA arhivi."],
      [Category.COACHES]: ["Karijera ovog trenera je obilježena ovim dostignućem."],
      [Category.ALL]: ["Fudbalske činjenice govore u prilog ovom tačnom rješenju."]
    },
    'English': {
      [Category.PLAYERS]: ["This record is officially documented in league statistics."],
      [Category.CLUBS]: ["The club's trophy cabinet confirms the accuracy of this answer."],
      [Category.STADIUMS]: ["Official capacities follow the highest football standards."],
      [Category.NATIONAL_TEAMS]: ["National team triumphs are documented in FIFA world rankings."],
      [Category.COACHES]: ["The coach's tactical innovations validate this response."],
      [Category.ALL]: ["Football facts strongly support this correct solution."]
    },
    'Deutsch': {
      [Category.PLAYERS]: ["Dieser Rekord ist offiziell in den Statistiken dokumentiert."],
      [Category.CLUBS]: ["Die Geschichte des Vereins bestätigt die Richtigkeit."],
      [Category.STADIUMS]: ["Offizielle Kapazitäten entsprechen den höchsten Standards."],
      [Category.NATIONAL_TEAMS]: ["Nationalmannschaftserfolge sind dokumentiert."],
      [Category.COACHES]: ["Trainerkarriere und Titel bestätigen diese Antwort."],
      [Category.ALL]: ["Fußballfakten stützen diese korrekte Lösung eindeutig."]
    }
  };

  const pool = explanations[lang] || explanations['English'];
  const categoryPool = pool[category] || pool[Category.ALL];

  const text = q.text || "";
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = text.charCodeAt(i) + ((hash << 5) - hash);
  }
  const index = Math.abs(hash) % categoryPool.length;

  return categoryPool[index];
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number, excludeIds: string[] = []): Question[] => {
  // Ensure we have a pool, default to English if specific language is missing
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'] || [];

  if (langPool.length === 0) return [];

  // 1. Try to filter by category and unused IDs
  let filtered = langPool.filter(q => 
    (category === Category.ALL || q.category === category) &&
    !excludeIds.includes(q.id)
  );

  // 2. If no unused category-specific questions, ignore category but keep unused
  if (filtered.length === 0 && category !== Category.ALL) {
    filtered = langPool.filter(q => !excludeIds.includes(q.id));
  }

  // 3. If still nothing (all questions used), just use the whole pool
  if (filtered.length === 0) {
    filtered = langPool;
  }

  const shuffled = [...filtered].sort(() => 0.5 - Math.random());

  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: q.id || `offline-${Date.now()}-${Math.random()}`,
    difficulty: q.difficulty || difficulty,
    explanation: q.explanation || getEnhancedExplanation(q, language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5,
  excludeIds: string[] = []
): Promise<{ questions: Question[], isOffline: boolean }> => {

  if (!navigator.onLine) {
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count, excludeIds), 
      isOffline: true 
    };
  }

  const targetLang = language === 'Bosanski' ? 'Bosnian' : language === 'Deutsch' ? 'German' : 'English';

  const prompt = `Generate ${count} football trivia questions. 
  CRITICAL: The entire content (question text, all 4 options, and the explanation) MUST be written in ${targetLang}.
  Category: ${category}.
  Difficulty: ${difficulty}/10.
  Unique IDs to avoid: ${excludeIds.slice(-20).join(', ')}.
  Output strictly as JSON: [{"id": string, "text": string, "options": [4 strings], "correctAnswer": string, "explanation": string}]`;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response");

    const cleanJson = resultText.replace(/```json/g, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleanJson);

    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        id: q.id || `ai-${Date.now()}-${Math.random()}`,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.error(`Gemini fetch failed for ${language}:`, error);
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count, excludeIds), 
      isOffline: true 
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Question, Language } from '../types';
import { audioService } from '../services/audioService';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
  isMuted: boolean;
  language: Language;
  isPaused?: boolean;
  categoryLabel: string;
}

const TRANSLATIONS = {
  correct: { Bosanski: "TAČNO!", English: "CORRECT!", Deutsch: "RICHTIG!" },
  wrong: { Bosanski: "NETAČNO!", English: "WRONG!", Deutsch: "FALSCH!" },
  difficulty: { Bosanski: "TEŽINA", English: "DIFF", Deutsch: "DIFF" },
  timesUp: { Bosanski: "VRIJEME!", English: "TIME!", Deutsch: "ZEIT!" }
};

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled, isMuted, language, isPaused, categoryLabel }) => {
  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isPaused || selected) {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
      return;
    }

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          audioService.stopSfx('tick');
          audioService.playSfx('timesUp', 0.8, true);
          handleTimeout();
          return 0;
        }

        const nextVal = prev - 1;
        if (nextVal <= 3) {
          audioService.playSfx('tick', 0.8);
        } else if (nextVal <= 6) {
          audioService.playSfx('tick', 0.4);
        } else {
          audioService.playSfx('tick', 0.15);
        }

        return nextVal;
      });
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
    };
  }, [question.id, isPaused, selected]);

  useEffect(() => {
    setTimeLeft(10);
    setSelected(null);
    setIsWrong(false);
  }, [question.id]);

  const handleTimeout = () => {
    if (selected) return;
    setIsWrong(true);
    setTimeout(() => audioService.playSfx('wrong', 0.6, true), 200);
    setSelected("");
    setTimeout(() => { onAnswer(""); }, 2500);
  };

  const handleSelect = (option: string) => {
    if (disabled || selected || timeLeft <= 0 || isPaused) return;

    if (timerRef.current) clearInterval(timerRef.current);
    audioService.stopSfx('tick');

    audioService.playSfx('click', 0.4);

    const correct = option === question.correctAnswer;
    setSelected(option);

    setTimeout(() => {
      if (correct) {
        audioService.playSfx('correct', 0.7, true);
      } else {
        setIsWrong(true);
        audioService.playSfx('wrong', 0.7, true);
      }
    }, 150);

    setTimeout(() => { onAnswer(option); }, 3000);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  // Dynamic font sizing for long questions
  const getQuestionFontSize = (text: string) => {
    if (text.length > 80) return 'text-sm md:text-xl';
    if (text.length > 50) return 'text-base md:text-2xl';
    return 'text-lg md:text-3xl';
  };

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      className={`relative w-full bg-black/80 backdrop-blur-3xl rounded-[1.5rem] md:rounded-[3rem] p-4 md:p-8 border border-white/10 shadow-2xl ${isWrong ? 'animate-shake border-rose-500/30' : ''}`}
    >
      <div className="absolute top-0 left-0 w-full h-1 overflow-hidden rounded-t-[1.5rem] md:rounded-t-[3rem]">
        <motion.div className={`h-full ${timeLeft <= 3 ? 'bg-rose-500' : 'bg-emerald-500'}`}
          initial={{ width: "100%" }} animate={{ width: selected ? "0%" : `${(timeLeft / 10) * 100}%` }}
          transition={{ duration: selected || isPaused ? 0 : 1, ease: "linear" }}
        />
      </div>

      <div className="flex justify-between items-center mb-4 md:mb-8">
        <span className="bg-white/5 text-white/40 border border-white/5 px-3 py-1 rounded-full text-[8px] md:text-[10px] font-black uppercase tracking-widest leading-none">
          {categoryLabel}
        </span>
        <div className="flex items-center space-x-2 md:space-x-3">
          <span className={`text-[10px] md:text-xs font-black tabular-nums ${timeLeft <= 3 ? 'text-rose-500 animate-pulse' : 'text-white/40'}`}>{timeLeft}s</span>
          <div className="flex space-x-0.5 md:space-x-1">
            {[...Array(5)].map((_, i) => (
              <div key={i} className={`w-0.5 h-2 md:w-1.5 md:h-4 rounded-full ${i < question.difficulty / 2 ? 'bg-emerald-500' : 'bg-white/5'}`} />
            ))}
          </div>
        </div>
      </div>

      <h2 className={`font-bold text-white text-center mb-6 md:mb-12 leading-[1.3] min-h-[3rem] px-1 md:px-4 ${getQuestionFontSize(question.text)}`}>
        {question.text}
      </h2>

      <div className="grid grid-cols-1 gap-2 md:gap-4">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <button key={idx} onClick={() => handleSelect(option)} disabled={!!selected || isPaused}
              className={`p-3 md:p-6 rounded-xl md:rounded-3xl border text-[11px] md:text-base font-bold transition-all text-left flex items-center min-h-[48px] md:min-h-[72px]
                ${!selected ? 'bg-white/5 border-white/10 text-white/70 active:scale-98' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-lg shadow-emerald-500/10' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white shadow-lg shadow-rose-500/10' : ''}
                ${showCorrectIfMissed ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-5 grayscale scale-[0.98]' : ''}
              `}
            >
              <span className="w-5 h-5 md:w-8 md:h-8 flex items-center justify-center rounded-md md:rounded-lg bg-black/20 text-[9px] md:text-sm mr-3 md:mr-4 shrink-0 font-black">{String.fromCharCode(65 + idx)}</span>
              <span className="flex-1 overflow-hidden text-ellipsis line-clamp-2">{option}</span>
            </button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected !== null && (
           <motion.div initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} className="mt-4 md:mt-8 p-3 md:p-6 bg-white/5 border border-white/10 rounded-xl md:rounded-[2rem]">
              {selected === "" && <p className="text-rose-500 font-black text-center text-[9px] md:text-xs uppercase mb-1 tracking-widest">{t('timesUp')}</p>}
              <p className="text-white/40 text-[10px] md:text-sm text-center italic font-medium leading-tight md:leading-relaxed">"{question.explanation}"</p>
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default QuizCard;

