                      <div className="absolute bottom-0 left-0 h-1 bg-white/5 w-full">
                        <motion.div className="h-full bg-emerald-500/40" initial={{ width: 0 }} animate={{ width: `${(completedCatsCount / 6) * 100}%` }} />
                      </div>
                    </motion.div>
                  );
