            <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="bg-black/40 border border-white/10 w-full max-w-[300px] rounded-[2rem] p-8 text-center shadow-2xl" onClick={e => e.stopPropagation()}>
