                <p>Korištenjem ove aplikacije pristajete na lokalno skladištenje podataka (LocalStorage) neophodno za funkcionisanje igre i leaderboarda.</p>
                <div className="h-px bg-white/10 w-full" />
                <p className="text-[8px]">Kontakt: tapfootball@gmail.com</p>
              </div>
              <button onClick={() => setShowPrivacy(false)} className="w-full mt-6 h-12 bg-white text-black font-black rounded-xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-4 safe-pt safe-pb" onClick={() => { audioService.playSfx('exit', 0.5, true); setShowLeaderboard(false); }}>
