const App: React.FC = () => {
  // --- 1. STATE & STORAGE INICIJALIZACIJA (Safe-mode) ---
  const getSafeStorage = (key: string, defaultValue: string): string => {
    try {
      return localStorage.getItem(key) || defaultValue;
    } catch {
      return defaultValue;
    }
  };

  const [isMuted, setIsMuted] = useState<boolean>(() => JSON.parse(getSafeStorage('quiz_muted', 'false')));
  const [showPrivacy, setShowPrivacy] = useState(false);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [loading, setLoading] = useState(false);
  const fetchingRef = useRef(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [unlockedToast, setUnlockedToast] = useState<Achievement | null>(null);
  const [streak, setStreak] = useState(0);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [visibleLeaderboardCount, setVisibleLeaderboardCount] = useState(10);

  const [levels, setLevels] = useState<LevelConfig[]>(() => {
    try {
      const saved = localStorage.getItem('quiz_levels');
      return saved ? JSON.parse(saved) : INITIAL_LEVELS;
    } catch {
      return INITIAL_LEVELS;
    }
  });

  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    try {
      const saved = localStorage.getItem('quiz_leaderboard');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const defaultStats = { 
      totalPoints: 0, totalCorrect: 0, totalAnswered: 0, maxStreak: 0, 
      levelsCompleted: [], unlockedAchievements: [], categoryCorrect: {},
      completedLevelCategories: {} 
    };
    try {
      const saved = localStorage.getItem('quiz_user_stats');
      return saved ? JSON.parse(saved) : defaultStats;
    } catch {
      return defaultStats;
    }
  });

  const [gameState, setGameState] = useState<GameState>(() => {
    const savedLang = getSafeStorage('quiz_language', 'English') as Language;
    return {
      nickname: getSafeStorage('quiz_nickname', ''),
      currentLevel: 1,
      selectedCategory: Category.ALL,
      score: 0,
      questionsAnswered: 0,
      correctAnswers: 0,
      mistakes: 0,
      isGameOver: false,
      language: (['Bosanski', 'English', 'Deutsch'].includes(savedLang) ? savedLang : 'English') as Language,
      history: [],
    };
  });

  // --- 2. CALLBACKS (Memoized) ---
  const handleInteraction = useCallback(() => {
    if (!hasInteracted) {
      setHasInteracted(true);
      audioService.unlock();
    }
  }, [hasInteracted]);

  // Added toggleMute function to handle audio mute toggling and state update.
  const toggleMute = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    setIsMuted(prev => !prev);
    audioService.playSfx('click', 0.2);
  }, []);

  const checkAchievements = useCallback((newStats: UserStats, currentStreak: number, currentScore: number, isPerfect: boolean = false, lang: Language) => {
    const newUnlocks: string[] = [];
    ACHIEVEMENTS.forEach(ach => {
      if (newStats.unlockedAchievements.includes(ach.id)) return;

      let condition = false;
      if (ach.type === 'total_correct') condition = newStats.totalCorrect >= ach.requirement;
      if (ach.type === 'streak') condition = currentStreak >= ach.requirement;
      if (ach.type === 'perfect_game') condition = isPerfect;
      if (ach.type === 'level_completed') condition = newStats.levelsCompleted.includes(ach.requirement);
      if (ach.type === 'high_score') condition = currentScore >= ach.requirement;
      if (ach.type === 'category_mastery' && ach.category) {
        condition = (newStats.categoryCorrect[ach.category] || 0) >= ach.requirement;
      }

      if (condition) {
        newUnlocks.push(ach.id);
        setUnlockedToast(ach);
        audioService.playSfx('correct', 1, true);
        setTimeout(() => setUnlockedToast(null), 4000);
      }
    });

    if (newUnlocks.length > 0) {
      setUserStats(prev => ({ ...prev, unlockedAchievements: [...prev.unlockedAchievements, ...newUnlocks] }));
    }
  }, []);

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number, history: string[], levelConfigs: LevelConfig[]) => {
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    setLoading(true);

    try {
      const config = levelConfigs.find(l => l.id === level) || levelConfigs[0];
      const progressRatio = progress / 20;
      const dynamicDiff = Math.min(
        config.maxDifficulty,
        Math.max(config.minDifficulty, Math.round(config.minDifficulty + (config.maxDifficulty - config.minDifficulty) * progressRatio))
      );

      const result = await generateQuestions(category, dynamicDiff, lang, 5, history);

      if (result.questions && result.questions.length > 0) {
        setQuestions(prev => [...prev, ...result.questions]);
      }
    } catch (error) {
      console.error("fetchBatch failed:", error);
    } finally {
      setLoading(false);
      fetchingRef.current = false;
    }
  }, []);

  const handleStartQuiz = useCallback((category: Category) => {
    handleInteraction();
    audioService.playSfx('playAgain', 0.6, true);
    setQuestions([]);
    setStreak(0);
    setCurrentQuestionIndex(0);
    setIsPaused(false);
    setGameState(prev => ({ 
      ...prev, 
      selectedCategory: category, 
      score: 0, 
      questionsAnswered: 0, 
      correctAnswers: 0, 
      mistakes: 0, 
      isGameOver: false, 
      history: [] 
    }));
    setStep('QUIZ');
  }, [handleInteraction]);

  const handleExitGame = useCallback(() => {
    audioService.playSfx('exit', 0.6, true);
    setGameState(prev => ({
      ...prev,
      score: 0,
      questionsAnswered: 0,
      correctAnswers: 0,
      mistakes: 0,
      isGameOver: false,
      history: []
    }));
    setStep('HOME');
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setStreak(0);
    setIsPaused(false);
  }, []);

  const handleAnswer = useCallback((answer: string) => {
    if (isPaused) return;
    const currentQ = questions[currentQuestionIndex];
    if (!currentQ) return;

    const isCorrect = answer === currentQ.correctAnswer;
    const newStreak = isCorrect ? streak + 1 : 0;
    const points = isCorrect ? Math.round((currentQ.difficulty || 1) * 10 * (1 + Math.floor(newStreak / 5) * 0.5)) : 0;

    const newMistakes = isCorrect ? gameState.mistakes : gameState.mistakes + 1;
    const isOver = (gameState.questionsAnswered + 1 >= 20) || newMistakes >= 5;
    const finalScore = gameState.score + points;

    const updatedStats = {
      ...userStats,
      totalPoints: userStats.totalPoints + points,
      totalCorrect: isCorrect ? userStats.totalCorrect + 1 : userStats.totalCorrect,
      totalAnswered: userStats.totalAnswered + 1,
      maxStreak: Math.max(userStats.maxStreak, newStreak),
      categoryCorrect: {
        ...userStats.categoryCorrect,
        [currentQ.category]: (userStats.categoryCorrect[currentQ.category] || 0) + (isCorrect ? 1 : 0)
      }
    };

    if (isOver) {
      const isPerfect = newMistakes === 0 && (gameState.questionsAnswered + 1 >= 20);
      const isSuccess = (gameState.questionsAnswered + 1 >= 20) && newMistakes < 5;

      if (isSuccess) {
        const currentLevelCats = updatedStats.completedLevelCategories[gameState.currentLevel] || [];
        if (!currentLevelCats.includes(gameState.selectedCategory)) {
          const newLevelCats = [...currentLevelCats, gameState.selectedCategory];
          updatedStats.completedLevelCategories = {
            ...updatedStats.completedLevelCategories,
            [gameState.currentLevel]: newLevelCats
          };

          if (newLevelCats.length >= 6) {
            updatedStats.levelsCompleted = [...new Set([...updatedStats.levelsCompleted, gameState.currentLevel])];
            setLevels(prev => prev.map(l => l.id === gameState.currentLevel + 1 ? {...l, unlocked: true} : l));
          }
        }
      }

      checkAchievements(updatedStats, newStreak, finalScore, isPerfect, gameState.language);

      setLeaderboard(prev => {
        const updated = [...prev, { 
          name: gameState.nickname || 'Player', 
          score: finalScore, 
          country: LANGUAGE_FLAGS[gameState.language], 
          timestamp: Date.now(), 
          isUser: true 
        }].sort((a, b) => b.score - a.score).slice(0, 100);
        return updated;
      });
    } else {
      checkAchievements(updatedStats, newStreak, finalScore, false, gameState.language);
    }

    setUserStats(updatedStats);
    setGameState(prev => ({
      ...prev,
      score: finalScore,
      questionsAnswered: prev.questionsAnswered + 1,
      correctAnswers: isCorrect ? prev.correctAnswers + 1 : prev.correctAnswers,
      mistakes: newMistakes,
      isGameOver: isOver,
      history: [...prev.history, { questionId: currentQ.id, isCorrect }]
    }));

    setStreak(newStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  }, [isPaused, questions, currentQuestionIndex, streak, gameState, userStats, checkAchievements]);

  const handleShare = useCallback(() => {
    const accuracy = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);
    const textTemplate = TRANSLATIONS.shareText[gameState.language] || TRANSLATIONS.shareText['English'];
    const shareText = textTemplate.replace('{score}', gameState.score.toString()).replace('{accuracy}', accuracy.toString());

    if (navigator.share) {
      navigator.share({ title: 'TAP FOOTBALL 2026', text: shareText, url: window.location.href }).catch(console.error);
    } else {
      navigator.clipboard.writeText(shareText).then(() => alert(TRANSLATIONS.copied[gameState.language] || TRANSLATIONS.copied['English']));
    }
  }, [gameState.score, gameState.correctAnswers, gameState.questionsAnswered, gameState.language]);

  const resetAllProgress = useCallback(() => {
    if (window.confirm(TRANSLATIONS.resetConfirm[gameState.language] || TRANSLATIONS.resetConfirm['English'])) {
      localStorage.clear();
      window.location.reload();
    }
  }, [gameState.language]);

  // --- 3. EFFECTS (Side-effects) ---
  useEffect(() => {
    try {
      localStorage.setItem('quiz_muted', JSON.stringify(isMuted));
      audioService.setMute(isMuted);
    } catch {}
  }, [isMuted]);

  useEffect(() => {
    try {
      localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
      localStorage.setItem('quiz_levels', JSON.stringify(levels));
      localStorage.setItem('quiz_leaderboard', JSON.stringify(leaderboard));
      localStorage.setItem('quiz_nickname', gameState.nickname);
      localStorage.setItem('quiz_language', gameState.language);
    } catch {}
  }, [userStats, levels, leaderboard, gameState.nickname, gameState.language]);

  useEffect(() => {
    const handlePopState = (e: PopStateEvent) => {
      e.preventDefault();
      if (step === 'QUIZ' && !gameState.isGameOver) {
        setIsPaused(true);
        window.history.pushState(null, '', window.location.pathname);
      } else if (step !== 'HOME') {
        setStep('HOME');
        window.history.pushState(null, '', window.location.pathname);
      }
    };
    window.history.pushState(null, '', window.location.pathname);
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [step, gameState.isGameOver]);

  useEffect(() => {
    if (step === 'QUIZ' && !loading && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 20 && !gameState.isGameOver) {
      const historyIds = gameState.history.map(h => h.questionId);
      const currentIds = questions.map(q => q.id);
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, [...historyIds, ...currentIds], levels);
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch, loading, levels]);

  const t = (key: keyof typeof TRANSLATIONS) => {
    const entry = (TRANSLATIONS as any)[key];
    if (!entry) return key;
    return entry[gameState.language] || entry['English'] || key;
  };

  const isWin = gameState.questionsAnswered >= 20 && gameState.mistakes < 5;
  const accuracyPercent = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);
  const langTheme = LANGUAGE_THEMES[gameState.language] || LANGUAGE_THEMES['English'];

  return (
    <div className="flex-1 flex flex-col h-full grass-pattern relative overflow-hidden" onClick={handleInteraction}>
      <StadiumAtmosphere />

      <AnimatePresence>
        {unlockedToast && (
          <motion.div initial={{ y: -100, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ y: -100, opacity: 0 }} className="fixed top-0 left-1/2 -translate-x-1/2 z-[200] w-[90%] max-w-sm pointer-events-none">
            <div className="bg-emerald-500 rounded-2xl p-4 shadow-[0_20px_40px_rgba(16,185,129,0.4)] border border-emerald-400 flex items-center space-x-4">
              <span className="text-2xl md:text-3xl shrink-0">{unlockedToast.icon}</span>
              <div>
                <p className="text-[9px] md:text-[10px] font-black text-white/60 uppercase tracking-widest leading-none mb-1">{t('unlockedToast')}</p>
                <p className="text-xs md:text-sm font-bold uppercase">{unlockedToast.name[gameState.language] || unlockedToast.name['English']}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="relative z-10 flex-1 flex flex-col h-full">
        <AnimatePresence mode="wait">
          {step === 'HOME' ? (
            <motion.div key="landing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 1.1 }} className="flex-1 flex flex-col items-center justify-center p-4 md:p-8 safe-pt safe-pb">
              <div className="mb-4 md:mb-10 flex flex-col items-center w-full max-w-md">
                <div className="flex gap-2 bg-white/5 backdrop-blur-xl p-1 rounded-full border border-white/10 mb-6 scale-90 md:scale-100">
                  {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(lang => (
                    <button key={lang} onClick={(e) => { e.stopPropagation(); audioService.playSfx('click', 0.3); handleInteraction(); setGameState(prev => ({ ...prev, language: lang })); }} className={`w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-full text-lg transition-all ${gameState.language === lang ? 'bg-white/10 scale-110 border-white/20' : 'opacity-40 grayscale'}`}>{LANGUAGE_FLAGS[lang]}</button>
                  ))}
                </div>
                <motion.img initial={{ scale: 0 }} animate={{ scale: 1 }} src={GAME_LOGO} className="mobile-logo w-14 h-14 md:w-20 md:h-20 mx-auto mb-4 md:mb-6 drop-shadow-[0_0_30px_rgba(16,185,129,0.5)]" />
                <motion.h1 className="mobile-title text-4xl md:text-7xl font-black tracking-tighter uppercase leading-[0.9] text-center mb-1 drop-shadow-2xl">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></motion.h1>
                <motion.p className="text-[9px] md:text-xs font-bold text-white/30 tracking-[0.2em] uppercase text-center">{t('subTitle')}</motion.p>
              </div>

              <div className="w-full max-w-[300px] md:max-w-[340px] space-y-2 md:space-y-4 mobile-compact">
                <motion.button whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => { handleInteraction(); audioService.playSfx('playAgain', 0.5, true); setStep('LEVEL_SELECT'); }} className="mobile-btn-height w-full h-14 md:h-20 bg-emerald-500 text-white font-black rounded-2xl md:rounded-3xl shadow-[0_15px_40px_rgba(16,185,129,0.3)] uppercase text-sm md:text-base tracking-[0.2em] btn-glow">{t('startGame')}</motion.button>
                <div className="grid grid-cols-2 gap-2 md:gap-3">
                  <button onClick={() => { handleInteraction(); audioService.playSfx('click', 0.3); setShowLeaderboard(true); setVisibleLeaderboardCount(10); }} className="h-12 md:h-16 bg-white/5 border border-white/10 text-white/60 font-black rounded-xl md:rounded-2xl uppercase text-[9px] md:text-[10px] tracking-widest backdrop-blur-md">🏆 RANK</button>
                  <button onClick={() => { handleInteraction(); audioService.playSfx('click', 0.3); setShowTrophyRoom(true); }} className="h-12 md:h-16 bg-yellow-500/10 border border-yellow-500/20 text-yellow-500 font-black rounded-xl md:rounded-2xl uppercase text-[9px] md:text-[10px] tracking-widest backdrop-blur-md">🏅 ROOM</button>
                </div>
              </div>

              <div className="mt-6 md:mt-8 flex flex-col items-center gap-4">
                <button onClick={(e) => toggleMute(e)} className="text-sm p-3 bg-black/40 rounded-full border border-white/10 backdrop-blur-md w-10 h-10 md:w-12 md:h-12 flex items-center justify-center transition-all active:scale-90">{isMuted ? '🔇' : '🔊'}</button>
                <button onClick={() => setShowPrivacy(true)} className="text-[8px] font-black text-white/20 uppercase tracking-widest hover:text-white/40">{t('privacyTitle')}</button>
              </div>
            </motion.div>
          ) : step === 'LEVEL_SELECT' ? (
            <motion.div key="level-select" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto custom-scrollbar">
              <h2 className="text-xl md:text-4xl font-black uppercase tracking-tighter my-6 md:my-8">{t('pickLevel')}</h2>
              <div className="w-full max-w-sm space-y-2 md:space-y-4 mb-10">
                {levels.map(level => {
                  const completedCatsCount = (userStats.completedLevelCategories[level.id] || []).length;
                  return (
                    <motion.div 
                      key={level.id} 
                      onClick={() => { if(level.unlocked) { audioService.playSfx('click', 0.4); setGameState(prev => ({...prev, currentLevel: level.id})); setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'); } }} 
                      className={`p-4 md:p-8 rounded-[1.2rem] md:rounded-[2.5rem] border transition-all cursor-pointer flex justify-between items-center relative overflow-hidden ${level.unlocked ? 'bg-black/40 border-emerald-500/30 active:scale-95' : 'bg-black/20 border-white/5 opacity-40 grayscale'}`}
                    >
                      <div>
                        <span className="text-white/30 text-[8px] md:text-[10px] font-black uppercase block mb-0.5">{t('lvl')} {level.id}</span>
                        <h3 className="text-lg md:text-3xl font-black uppercase">{level.name[gameState.language] || level.name['English']}</h3>
                        <p className="text-[9px] md:text-xs text-white/50 font-bold uppercase mt-1">
                          {t('categoriesDone').replace('{done}', completedCatsCount.toString())}
                        </p>
                      </div>
                      {level.unlocked ? <span className="text-emerald-500 font-black text-xs md:text-base">GO →</span> : <span className="text-sm md:text-lg">🔒</span>}
                      <div className="absolute bottom-0 left-0 h-1 bg-white/5 w-full">
                        <motion.div className="h-full bg-emerald-500/40" initial={{ width: 0 }} animate={{ width: `${Math.min(100, (completedCatsCount / 6) * 100)}%` }} />
                      </div>
                    </motion.div>
                  );
                })}
              </div>
              <button onClick={() => { audioService.playSfx('exit', 0.5, true); setStep('HOME'); }} className="mt-auto mb-4 text-[10px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-3 px-8 active:text-white">{t('back')}</button>
            </motion.div>
          ) : step === 'NICKNAME_INPUT' ? (
            <motion.div key="nick" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4 safe-pt safe-pb">
              <div className="bg-black/60 backdrop-blur-2xl p-6 md:p-12 rounded-[2rem] md:rounded-[4rem] border border-white/10 w-full max-w-[340px] text-center shadow-2xl">
                <h2 className="text-xl md:text-3xl font-black mb-6 md:mb-8 uppercase tracking-tighter">{t('enterNickname')}</h2>
                <input type="text" value={gameState.nickname} placeholder="Messi10..." onChange={(e) => setGameState(p => ({...p, nickname: e.target.value.substring(0, 15)}))} className="w-full h-14 md:h-20 bg-white/5 border border-white/10 rounded-xl md:rounded-3xl px-6 text-white text-lg md:text-xl font-bold mb-6 md:mb-8 focus:outline-none focus:border-emerald-500 text-center placeholder:text-white/10" />
                <button onClick={() => { audioService.playSfx('click', 0.4); setStep('CATEGORY_SELECT'); }} disabled={!gameState.nickname.trim()} className="w-full h-14 md:h-20 bg-emerald-500 font-black rounded-xl md:rounded-3xl uppercase text-xs md:text-sm tracking-widest disabled:opacity-20 active:scale-95 transition-all">{t('start')}</button>
              </div>
            </motion.div>
          ) : step === 'CATEGORY_SELECT' ? (
            <motion.div key="cat" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center p-4 md:p-8 safe-pt safe-pb overflow-y-auto custom-scrollbar">
               <h2 className="text-xl md:text-4xl font-black my-6 md:my-8 uppercase tracking-tighter text-white/40">{t('selectCategory')}</h2>
               <div className="grid grid-cols-2 gap-3 md:gap-6 w-full max-w-[500px] mb-12 px-2">
                  {Object.values(Category).map((cat, index) => {
                    if (cat === Category.ALL && index !== Object.values(Category).length - 1) return null;
                    const isAll = cat === Category.ALL;
                    const isDoneInCurrentLevel = (userStats.completedLevelCategories[gameState.currentLevel] || []).includes(cat);
                    const icon = CATEGORY_VISUALS[cat].icon;
                    return (
                      <motion.div
                        key={cat}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                        onClick={() => handleStartQuiz(cat)}
                        className={`group relative overflow-hidden cursor-pointer rounded-2xl md:rounded-[2.5rem] border-2 shadow-xl backdrop-blur-3xl p-4 md:p-8 transition-shadow ${
                          isAll 
                          ? `col-span-2 bg-gradient-to-br ${langTheme.gradient} border-white/20 shadow-lg ${langTheme.glow}` 
                          : `bg-black/40 border-white/10 hover:border-white/40 shadow-md`
                        }`}
                      >
                        <div className="relative z-10 flex flex-col items-center text-center">
                          <span className="text-4xl sm:text-5xl md:text-7xl mb-4 group-hover:scale-125 transition-transform">{icon}</span>
                          <span className="text-[10px] sm:text-xs md:text-sm font-black tracking-[0.2em] uppercase text-white/70 group-hover:text-white">
                            {CATEGORY_TRANSLATIONS[cat][gameState.language] || CATEGORY_TRANSLATIONS[cat]['English']}
                          </span>
                          {isDoneInCurrentLevel && <span className="text-emerald-400 text-[10px] md:text-sm font-bold mt-1 uppercase tracking-widest">{t('completedBadge')}</span>}
                        </div>
                      </motion.div>
                    );
                  })}
               </div>
               <button onClick={() => { audioService.playSfx('exit', 0.5, true); setStep('LEVEL_SELECT'); }} className="mt-auto mb-4 text-[10px] md:text-xs font-black text-white/30 uppercase tracking-[0.4em] py-3 px-8 hover:text-white transition-colors">{t('back')}</button>
            </motion.div>
          ) : (
            <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col w-full max-w-xl mx-auto safe-pt safe-pb h-full overflow-hidden">
              {gameState.isGameOver ? (
                <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4">
                  <div className={`bg-black/90 backdrop-blur-3xl p-6 md:p-12 rounded-[2rem] md:rounded-[4rem] border ${isWin ? 'border-emerald-500/40' : 'border-rose-500/40'} text-center w-full max-w-[360px] shadow-2xl`}>
                    <motion.img src={GAME_LOGO} className="w-10 h-10 md:w-16 mx-auto mb-4" />
                    <h1 className={`text-2xl md:text-5xl font-black mb-4 uppercase tracking-tighter ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                    <div className="grid grid-cols-2 gap-2 mb-6">
                      <div className="bg-white/5 p-3 rounded-xl"><span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('totalScoreLabel')}</span><p className="text-xl font-black">{gameState.score}</p></div>
                      <div className="bg-white/5 p-3 rounded-xl"><span className="text-[7px] font-black text-white/30 uppercase block mb-1">{t('accuracyLabel')}</span><p className="text-xl font-black">{accuracyPercent}%</p></div>
                    </div>
                    <div className="space-y-2">
                      <button onClick={handleExitGame} className="w-full h-12 bg-emerald-500 font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">{t('playAgain')}</button>
                      <button onClick={handleShare} className="w-full h-10 bg-white/10 border border-white/10 text-white font-black rounded-lg uppercase text-[9px] tracking-widest active:bg-white/20">📤 {t('shareBtn')}</button>
                      <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full h-10 text-white/40 font-black uppercase text-[9px] tracking-widest">{t('retry')}</button>
                    </div>
                  </div>
                </motion.div>
              ) : (
                <div className="flex-1 flex flex-col p-3 md:p-4 h-full overflow-hidden">
                  <header className="flex justify-between items-center mb-2 md:mb-4 bg-black/40 p-2 md:p-4 rounded-xl md:rounded-[2.5rem] border border-white/10 backdrop-blur-xl shrink-0">
                     <button onClick={() => setIsPaused(true)} className="w-8 h-8 md:w-12 md:h-12 bg-white/5 border border-white/10 rounded-full flex items-center justify-center text-[10px] md:text-sm active:scale-90">⏸</button>
                     <div className="text-center">
                       <p className="text-white/30 text-[7px] md:text-[8px] font-black uppercase mb-0.5">{t('lvl')} {gameState.currentLevel} • {gameState.score}</p>
                       <div className="flex gap-0.5">{[...Array(5)].map((_, i) => (<span key={i} className={`text-[10px] md:text-xs ${i >= (5 - gameState.mistakes) ? 'opacity-20 grayscale' : ''}`}>❤️</span>))}</div>
                     </div>
                     <div className="text-right">
                       <p className="text-white/30 text-[7px] md:text-[8px] font-black uppercase mb-0.5">{t('questionLabel')} {gameState.questionsAnswered + 1}/20</p>
                       <div className={`inline-block px-1.5 py-0.5 rounded-full text-[8px] md:text-[10px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/10 text-white/30'}`}>x{streak}</div>
                     </div>
                  </header>

                  <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mb-4 shrink-0"><motion.div className="h-full bg-emerald-500" initial={{ width: 0 }} animate={{ width: `${(gameState.questionsAnswered / 20) * 100}%` }} /></div>

                  <div className="flex-1 flex flex-col justify-start md:justify-center overflow-y-auto custom-scrollbar">
                    <AnimatePresence mode="wait">
                      {loading && questions.length <= currentQuestionIndex ? (
                        <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center space-y-4 py-10 w-full">
                          <QuizSkeleton />
                          <div className="flex flex-col items-center gap-4">
                            <div className="w-12 h-12 border-3 border-emerald-500/10 border-t-emerald-500 rounded-full animate-spin" />
                            <p className="text-emerald-500 font-black text-[9px] uppercase tracking-[0.4em] animate-pulse">{t('generating')}</p>
                          </div>
                        </motion.div>
                      ) : questions[currentQuestionIndex] ? (
                        <div className="w-full pb-4">
                          <QuizCard 
                            key={questions[currentQuestionIndex].id} 
                            question={questions[currentQuestionIndex]} 
                            onAnswer={handleAnswer} 
                            disabled={isPaused} 
                            isMuted={isMuted} 
                            language={gameState.language} 
                            isPaused={isPaused}
                            categoryLabel={CATEGORY_TRANSLATIONS[questions[currentQuestionIndex].category][gameState.language] || questions[currentQuestionIndex].category}
                          />
                        </div>
                      ) : null}
                    </AnimatePresence>
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <AnimatePresence>
        {isPaused && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6" onClick={() => setIsPaused(false)}>
            <div className="bg-black/40 border border-white/10 w-full max-w-[300px] rounded-[2rem] p-8 text-center" onClick={e => e.stopPropagation()}>
               <span className="text-4xl block mb-6">⚽</span>
               <h3 className="text-xl font-black uppercase mb-8 tracking-tighter">PAUSED</h3>
               <div className="space-y-3">
                 <button onClick={() => setIsPaused(false)} className="w-full h-14 bg-emerald-500 text-white font-black rounded-xl uppercase text-xs tracking-widest active:scale-95">{t('resume')}</button>
                 <button onClick={handleExitGame} className="w-full h-12 bg-rose-500/20 text-rose-500 font-black rounded-lg uppercase text-[9px] tracking-widest active:scale-95">{t('exit')}</button>
               </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showPrivacy && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-4" onClick={() => setShowPrivacy(false)}>
            <div className="bg-black/60 border border-white/10 w-full max-w-[340px] rounded-[2rem] p-6 max-h-[80vh] overflow-y-auto custom-scrollbar" onClick={e => e.stopPropagation()}>
              <h3 className="text-lg font-black uppercase mb-4 tracking-tighter">{t('privacyTitle')}</h3>
              <div className="text-[10px] text-white/50 space-y-4 font-medium leading-relaxed">
                <p><strong>V{VERSION} - Tap Football 2026</strong></p>
                <p>Ova igra koristi Google Gemini AI za generisanje pitanja. Vaši podaci se čuvaju isključivo lokalno na vašem uređaju.</p>
                <p>Kontakt: tapfootball@gmail.com</p>
              </div>
              <button onClick={() => setShowPrivacy(false)} className="w-full mt-6 h-12 bg-white text-black font-black rounded-xl uppercase text-[10px] tracking-widest">{t('close')}</button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showLeaderboard && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-4 safe-pt safe-pb" onClick={() => setShowLeaderboard(false)}>
            <div className="bg-black/60 border border-white/10 w-full max-w-[340px] rounded-[2rem] p-6 max-h-[85vh] flex flex-col" onClick={e => e.stopPropagation()}>
              <h3 className="text-center text-white font-black text-lg uppercase mb-6 tracking-tighter">{t('leaderboard')}</h3>
              <div className="flex-1 overflow-y-auto pr-1 custom-scrollbar mb-6 space-y-2">
                {leaderboard.slice(0, visibleLeaderboardCount).map((user, i) => (
                  <div key={i} className={`flex items-center justify-between p-3 rounded-xl border ${user.isUser ? 'bg-emerald-500/20 border-emerald-500/40' : 'bg-white/5 border-white/5'}`}>
                    <div className="flex items-center space-x-2">
                      <span className="font-black text-[9px] w-4 opacity-30">{i + 1}.</span>
                      <span className="font-bold text-xs truncate max-w-[120px]">{user.name}</span>
                      <span className="text-[10px]">{user.country}</span>
                    </div>
                    <span className="text-emerald-400 font-black text-xs">{user.score}</span>
                  </div>
                ))}
                {visibleLeaderboardCount < leaderboard.length && (
                  <button onClick={() => setVisibleLeaderboardCount(prev => prev + 10)} className="w-full py-4 text-[9px] font-black text-white/30 uppercase tracking-[0.3em]">{t('loadMore')}</button>
                )}
              </div>
              <button onClick={() => setShowLeaderboard(false)} className="w-full h-12 bg-white text-black font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 shrink-0">{t('close')}</button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showTrophyRoom && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[110] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-4 safe-pt safe-pb" onClick={() => setShowTrophyRoom(false)}>
            <div className="bg-black/60 border border-yellow-500/20 w-full max-w-[380px] rounded-[2rem] p-5 md:p-8 max-h-[85vh] flex flex-col" onClick={e => e.stopPropagation()}>
              <div className="text-center mb-6 shrink-0"><span className="text-3xl block mb-1">🏆</span><h3 className="text-white font-black text-lg uppercase tracking-tighter">{t('trophyRoom')}</h3></div>
              <div className="flex-1 overflow-y-auto pr-1 custom-scrollbar mb-6">
                <div className="grid grid-cols-2 gap-2">
                  {ACHIEVEMENTS.map((ach) => {
                    const isUnlocked = userStats.unlockedAchievements.includes(ach.id);
                    let progress = 0;
                    if (ach.type === 'total_correct') progress = userStats.totalCorrect;
                    else if (ach.type === 'streak') progress = userStats.maxStreak;
                    else if (ach.type === 'category_mastery' && ach.category) progress = userStats.categoryCorrect[ach.category] || 0;
                    else if (ach.type === 'high_score') progress = isUnlocked ? ach.requirement : 0;
                    else if (ach.type === 'perfect_game') progress = isUnlocked ? 1 : 0;
                    const progressPercent = Math.min(100, (progress / ach.requirement) * 100);
                    return (
                      <div key={ach.id} className={`p-3 rounded-xl border flex flex-col items-center text-center ${isUnlocked ? 'bg-yellow-500/10 border-yellow-500/30' : 'bg-white/5 border-white/5 opacity-60'}`}>
                        <span className={`text-2xl mb-2 ${isUnlocked ? '' : 'grayscale'}`}>{ach.icon}</span>
                        <p className="text-[9px] font-black uppercase mb-1 leading-tight h-5 flex items-center">{ach.name[gameState.language] || ach.name['English']}</p>
                        {!isUnlocked && <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mb-1"><div className="h-full bg-yellow-500/40" style={{ width: `${progressPercent}%` }} /></div>}
                        {isUnlocked && <span className="text-[6px] font-black text-yellow-500 uppercase mt-0.5 tracking-widest">{t('unlockedBadge')}</span>}
                      </div>
                    );
                  })}
                </div>
              </div>
              <div className="space-y-3 shrink-0">
                <button onClick={resetAllProgress} className="w-full h-10 bg-rose-500/10 border border-rose-500/20 text-rose-500 font-black rounded-lg uppercase text-[8px] tracking-widest active:scale-95">{t('resetData')}</button>
                <button onClick={() => setShowTrophyRoom(false)} className="w-full h-12 bg-white text-black font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">{t('close')}</button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="relative z-10 py-4 text-center mt-auto safe-pb shrink-0">
        <p className="text-[7px] font-black text-white/10 uppercase tracking-[0.4em] mb-0.5">TAP FOOTBALL QUIZ 2026 • v{VERSION}</p>
        <p className="text-[6px] font-medium text-white/5 uppercase tracking-widest">© 2026 tapfootball@gmail.com</p>
      </footer>
    </div>
  );
};

export default App;

