import { GoogleGenAI, Type } from "@google/genai";
import { Category, Question, Language } from "../types";
import { LOCAL_QUESTIONS } from "../data/localQuestions";

const getEnhancedExplanation = (q: Partial<Question>, lang: Language): string => {
  if (q.explanation) return q.explanation;
  const pool: Record<Language, string> = {
    'Bosanski': "Fudbalske činjenice govore u prilog ovom tačnom rješenju.",
    'English': "Football facts strongly support this correct solution.",
    'Deutsch': "Fußballfakten stützen diese korrekte Lösung eindeutig."
  };
  return pool[lang] || pool['English'];
};

const getOfflineQuestions = (category: Category, language: Language, difficulty: number, count: number, excludeIds: string[] = []): Question[] => {
  const langPool = LOCAL_QUESTIONS[language] || LOCAL_QUESTIONS['English'] || [];
  if (langPool.length === 0) return [];

  let filtered = langPool.filter(q => 
    (category === Category.ALL || q.category === category) &&
    !excludeIds.includes(q.id)
  );

  if (filtered.length === 0) {
    filtered = langPool.filter(q => !excludeIds.includes(q.id));
  }

  if (filtered.length === 0) filtered = langPool;

  const shuffled = [...filtered].sort(() => 0.5 - Math.random());

  return shuffled.slice(0, count).map(q => ({
    ...q,
    id: q.id || `offline-${Date.now()}-${Math.random()}`,
    difficulty: q.difficulty || difficulty,
    explanation: q.explanation || getEnhancedExplanation(q, language)
  }));
};

export const generateQuestions = async (
  category: Category,
  difficulty: number,
  language: Language,
  count: number = 5,
  excludeIds: string[] = []
): Promise<{ questions: Question[], isOffline: boolean }> => {

  // Safely check for API Key to avoid ReferenceError: process is not defined
  let apiKey = '';
  try {
    if (typeof process !== 'undefined' && process.env) {
      apiKey = process.env.API_KEY || '';
    }
  } catch (e) {}

  if (!navigator.onLine || !apiKey) {
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count, excludeIds), 
      isOffline: true 
    };
  }

  const targetLang = language === 'Bosanski' ? 'Bosnian' : language === 'Deutsch' ? 'German' : 'English';
  const prompt = `Generate ${count} football trivia questions in ${targetLang}. Category: ${category}. Difficulty: ${difficulty}/10. Unique IDs to avoid: ${excludeIds.slice(-20).join(', ')}. Output strictly as JSON array with properties: id, text, options (array of 4), correctAnswer, explanation.`;

  try {
    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation"]
          }
        }
      }
    });

    const parsed = JSON.parse(response.text || "[]");
    return {
      isOffline: false,
      questions: parsed.map((q: any) => ({
        ...q,
        id: q.id || `ai-${Date.now()}-${Math.random()}`,
        category: category,
        difficulty: difficulty
      }))
    };
  } catch (error) {
    console.error(`Gemini failed:`, error);
    return { 
      questions: getOfflineQuestions(category, language, difficulty, count, excludeIds), 
      isOffline: true 
    };
  }
};

