            <button onClick={toggleMute} className="mt-8 p-3 bg-black/40 rounded-full border border-white/10">{isMuted ? '🔇' : '🔊'}</button>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="l" initial={{ x: 50, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="flex-1 flex flex-col items-center p-4">
            <h2 className="text-2xl font-black my-8 uppercase">{t('pickLevel')}</h2>
            <div className="w-full max-w-sm space-y-3">
              {levels.map(lvl => (
                <div key={lvl.id} onClick={() => lvl.unlocked && (setGameState(p => ({ ...p, currentLevel: lvl.id })), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} className={`p-6 rounded-3xl border ${lvl.unlocked ? 'bg-black/40 border-emerald-500/30' : 'opacity-40 grayscale bg-black/20'} transition-all`}>
                  <p className="text-[10px] font-black opacity-30 uppercase">{t('lvl')} {lvl.id}</p>
                  <h3 className="text-xl font-black uppercase">{lvl.name[gameState.language]}</h3>
                </div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="mt-auto mb-8 text-xs font-black opacity-30 uppercase">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="n" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-4">
            <div className="bg-black/60 p-8 rounded-[2rem] border border-white/10 w-full max-w-[340px] text-center">
              <h2 className="text-2xl font-black mb-6 uppercase">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} onChange={e => setGameState(p => ({ ...p, nickname: e.target.value.substring(0, 12) }))} className="w-full h-14 bg-white/5 border border-white/10 rounded-xl px-4 text-white font-bold text-center mb-6 focus:outline-none focus:border-emerald-500" />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} className="w-full h-14 bg-emerald-500 rounded-xl font-black uppercase disabled:opacity-20">{t('back')}</button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="c" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center p-4 overflow-y-auto">
            <h2 className="text-2xl font-black my-8 uppercase opacity-40">{t('selectCategory')}</h2>
            <div className="grid grid-cols-2 gap-3 w-full max-w-sm mb-8">
              {Object.values(Category).map(cat => cat !== Category.ALL && (
                <div key={cat} onClick={() => handleStartQuiz(cat)} className="bg-black/40 border border-white/10 p-6 rounded-2xl flex flex-col items-center text-center">
                  <span className="text-4xl mb-2">{CATEGORY_VISUALS[cat].icon}</span>
                  <span className="text-[10px] font-black uppercase opacity-60">{CATEGORY_TRANSLATIONS[cat][gameState.language]}</span>
                </div>
              ))}
              <div onClick={() => handleStartQuiz(Category.ALL)} className="col-span-2 bg-emerald-500/20 border border-emerald-500/40 p-6 rounded-2xl flex flex-col items-center">
                <span className="text-4xl mb-2">⚽</span>
                <span className="text-[10px] font-black uppercase">{CATEGORY_TRANSLATIONS[Category.ALL][gameState.language]}</span>
              </div>
            </div>
            <button onClick={() => setStep('LEVEL_SELECT')} className="mt-auto mb-8 text-xs font-black opacity-30 uppercase">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="q" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-xl mx-auto h-full overflow-hidden">
            {gameState.isGameOver ? (
              <div className="flex-1 flex flex-col items-center justify-center">
                <div className={`bg-black/90 p-8 rounded-[2rem] border ${isWin ? 'border-emerald-500/40' : 'border-rose-500/40'} text-center w-full max-w-[360px]`}>
                  <h1 className={`text-4xl font-black mb-4 ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                  <div className="grid grid-cols-2 gap-2 mb-8">
                    <div className="bg-white/5 p-4 rounded-xl"><span className="text-[8px] font-black opacity-30 block">{t('totalScoreLabel')}</span><p className="text-2xl font-black">{gameState.score}</p></div>
                    <div className="bg-white/5 p-4 rounded-xl"><span className="text-[8px] font-black opacity-30 block">{t('accuracyLabel')}</span><p className="text-2xl font-black">{acc}%</p></div>
                  </div>
                  <button onClick={handleExitGame} className="w-full h-14 bg-emerald-500 rounded-xl font-black uppercase">{t('playAgain')}</button>
                </div>
              </div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-4 bg-black/40 p-4 rounded-2xl border border-white/10 shrink-0">
                  <button onClick={() => setIsPaused(true)} className="w-10 h-10 bg-white/5 rounded-full">⏸</button>
                  <div className="text-center">
                    <p className="text-[8px] font-black opacity-30">{t('lvl')} {gameState.currentLevel} • {gameState.score}</p>
                    <div className="flex gap-1">{'❤️'.repeat(5 - gameState.mistakes)}</div>
                  </div>
                  <p className="text-[8px] font-black opacity-30">{t('questionLabel')} {gameState.questionsAnswered + 1}/20</p>
                </header>
                <div className="flex-1 flex flex-col justify-center">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? <QuizSkeleton /> : questions[currentQuestionIndex] ? (
                      <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={isPaused} isMuted={isMuted} language={gameState.language} isPaused={isPaused} categoryLabel={CATEGORY_TRANSLATIONS[questions[currentQuestionIndex].category][gameState.language]} />
                    ) : null}
                  </AnimatePresence>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isPaused && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6">
            <div className="bg-black/40 border border-white/10 w-full max-w-[300px] rounded-[2rem] p-8 text-center">
               <h3 className="text-xl font-black uppercase mb-8">PAUSED</h3>
               <button onClick={() => setIsPaused(false)} className="w-full h-14 bg-emerald-500 rounded-xl font-black uppercase mb-4">{t('resume')}</button>
               <button onClick={handleExitGame} className="w-full h-12 bg-rose-500/20 text-rose-500 rounded-lg font-black uppercase text-xs">{t('exit')}</button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Category, Question, GameState, LevelConfig, Language, LeaderboardEntry, Achievement, UserStats } from './types';
import { generateQuestions } from './services/geminiService';
import { audioService } from './services/audioService';
