  const getSafeStorage = (key: string, defaultValue: string) => {
    try { return localStorage.getItem(key) || defaultValue; } catch { return defaultValue; }
  };

  const [isMuted, setIsMuted] = useState<boolean>(() => {
    try { return JSON.parse(getSafeStorage('quiz_muted', 'false')); } catch { return false; }
  });

  const [hasInteracted, setHasInteracted] = useState(false);
  const [loading, setLoading] = useState(false);
  const fetchingRef = useRef(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showTrophyRoom, setShowTrophyRoom] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [step, setStep] = useState<'HOME' | 'LEVEL_SELECT' | 'NICKNAME_INPUT' | 'CATEGORY_SELECT' | 'QUIZ'>('HOME');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [visibleLeaderboardCount, setVisibleLeaderboardCount] = useState(10);
  const [streak, setStreak] = useState(0);

  const [levels, setLevels] = useState<LevelConfig[]>(() => {
    try { const saved = localStorage.getItem('quiz_levels'); return saved ? JSON.parse(saved) : INITIAL_LEVELS; } catch { return INITIAL_LEVELS; }
  });

  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>(() => {
    try { const saved = localStorage.getItem('quiz_leaderboard'); return saved ? JSON.parse(saved) : []; } catch { return []; }
  });

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const d = { totalPoints: 0, totalCorrect: 0, totalAnswered: 0, maxStreak: 0, levelsCompleted: [], unlockedAchievements: [], categoryCorrect: {}, completedLevelCategories: {} };
    try { const s = localStorage.getItem('quiz_user_stats'); return s ? JSON.parse(s) : d; } catch { return d; }
  });

  const [gameState, setGameState] = useState<GameState>(() => {
    const l = getSafeStorage('quiz_language', 'English') as Language;
    return {
      nickname: getSafeStorage('quiz_nickname', ''),
      currentLevel: 1, selectedCategory: Category.ALL, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false,
      language: (['Bosanski', 'English', 'Deutsch'].includes(l) ? l : 'English') as Language, history: []
    };
  });

  const handleInteraction = useCallback(() => { if (!hasInteracted) { setHasInteracted(true); audioService.unlock(); } }, [hasInteracted]);
  const toggleMute = useCallback((e: React.MouseEvent) => { e.stopPropagation(); setIsMuted(p => !p); audioService.playSfx('click', 0.2); }, []);

  const fetchBatch = useCallback(async (level: number, category: Category, lang: Language, progress: number, history: string[]) => {
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    setLoading(true);
    try {
      const config = levels.find(l => l.id === level) || levels[0];
      const res = await generateQuestions(category, config.minDifficulty, lang, 5, history);
      if (res.questions?.length > 0) setQuestions(prev => [...prev, ...res.questions]);
    } catch (e) { console.error(e); } finally { setLoading(false); fetchingRef.current = false; }
  }, [levels]);

  const handleStartQuiz = useCallback((category: Category) => {
    handleInteraction();
    audioService.playSfx('playAgain', 0.6, true);
    setQuestions([]); setStreak(0); setCurrentQuestionIndex(0); setIsPaused(false);
    setGameState(p => ({ ...p, selectedCategory: category, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setStep('QUIZ');
  }, [handleInteraction]);

  const handleExitGame = useCallback(() => {
    audioService.playSfx('exit', 0.6, true);
    setGameState(p => ({ ...p, score: 0, questionsAnswered: 0, correctAnswers: 0, mistakes: 0, isGameOver: false, history: [] }));
    setStep('HOME'); setQuestions([]); setCurrentQuestionIndex(0); setStreak(0); setIsPaused(false);
  }, []);

  const handleAnswer = useCallback((answer: string) => {
    if (isPaused || !questions[currentQuestionIndex]) return;
    const q = questions[currentQuestionIndex];
    const isCorrect = answer === q.correctAnswer;
    const nStreak = isCorrect ? streak + 1 : 0;
    const pts = isCorrect ? Math.round(10 * (1 + Math.floor(nStreak / 5) * 0.5)) : 0;
    const isOver = (gameState.questionsAnswered + 1 >= 20) || (isCorrect ? gameState.mistakes : gameState.mistakes + 1) >= 5;

    if (isOver) {
      setLeaderboard(prev => [...prev, { name: gameState.nickname || 'Player', score: gameState.score + pts, country: LANGUAGE_FLAGS[gameState.language], timestamp: Date.now(), isUser: true }].sort((a, b) => b.score - a.score).slice(0, 100));

      if (!isCorrect && gameState.mistakes + 1 < 5 && gameState.questionsAnswered + 1 >= 20) {
        // Win logic: Unlock next level
        const currentLvlIdx = levels.findIndex(l => l.id === gameState.currentLevel);
        if (currentLvlIdx !== -1 && currentLvlIdx < levels.length - 1) {
          const nextLevels = [...levels];
          nextLevels[currentLvlIdx + 1].unlocked = true;
          setLevels(nextLevels);
        }
      }
    }

    setGameState(p => ({ ...p, score: p.score + pts, questionsAnswered: p.questionsAnswered + 1, correctAnswers: isCorrect ? p.correctAnswers + 1 : p.correctAnswers, mistakes: isCorrect ? p.mistakes : p.mistakes + 1, isGameOver: isOver }));
    setStreak(nStreak);
    if (!isOver) setCurrentQuestionIndex(prev => prev + 1);
  }, [isPaused, questions, currentQuestionIndex, streak, gameState, levels]);

  useEffect(() => {
    try { localStorage.setItem('quiz_muted', JSON.stringify(isMuted)); audioService.setMute(isMuted); } catch {}
  }, [isMuted]);

  useEffect(() => {
    try {
      localStorage.setItem('quiz_user_stats', JSON.stringify(userStats));
      localStorage.setItem('quiz_levels', JSON.stringify(levels));
      localStorage.setItem('quiz_leaderboard', JSON.stringify(leaderboard));
      localStorage.setItem('quiz_nickname', gameState.nickname);
      localStorage.setItem('quiz_language', gameState.language);
    } catch {}
  }, [userStats, levels, leaderboard, gameState.nickname, gameState.language]);

  useEffect(() => {
    if (step === 'QUIZ' && !loading && questions.length - currentQuestionIndex < 3 && gameState.questionsAnswered < 20 && !gameState.isGameOver) {
      fetchBatch(gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, questions.map(q => q.id));
    }
  }, [step, questions.length, currentQuestionIndex, gameState.currentLevel, gameState.selectedCategory, gameState.language, gameState.questionsAnswered, gameState.isGameOver, fetchBatch, loading]);

  const t = (key: keyof typeof TRANSLATIONS) => (TRANSLATIONS as any)[key][gameState.language] || (TRANSLATIONS as any)[key]['English'] || key;
  const isWin = gameState.questionsAnswered >= 20 && gameState.mistakes < 5;
  const acc = Math.round((gameState.correctAnswers / Math.max(1, gameState.questionsAnswered)) * 100);

  const StarRating = ({ count }: { count: number }) => (
    <div className="flex gap-0.5">
      {[...Array(5)].map((_, i) => (
        <span key={i} className={i < count ? "star-active" : "star-inactive"}>★</span>
      ))}
    </div>
  );

  return (
    <div className="relative flex-1 flex flex-col h-full safe-px" onClick={handleInteraction}>
      <AnimatePresence mode="wait">
        {step === 'HOME' ? (
          <motion.div key="h" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9 }} className="flex-1 flex flex-col items-center justify-center p-6 text-center">
            <div className="glass-panel p-2 rounded-full flex gap-2 mb-12">
              {(Object.keys(LANGUAGE_FLAGS) as Language[]).map(l => (
                <button key={l} onClick={() => setGameState(p => ({ ...p, language: l }))} className={`w-12 h-12 rounded-full transition-all flex items-center justify-center text-xl ${gameState.language === l ? 'bg-emerald-500 scale-110 shadow-lg' : 'opacity-40 grayscale hover:opacity-100 hover:grayscale-0'}`}>{LANGUAGE_FLAGS[l]}</button>
              ))}
            </div>

            <motion.div initial={{ scale: 0.8 }} animate={{ scale: 1 }} className="relative mb-6">
              <div className="absolute inset-0 bg-emerald-500/20 blur-3xl rounded-full"></div>
              <img src={GAME_LOGO} className="w-32 h-32 relative z-10 drop-shadow-2xl" />
            </motion.div>

            <h1 className="text-5xl md:text-7xl font-black tracking-tighter mb-2 leading-none">TAP FOOTBALL<br/><span className="text-emerald-500">2026</span></h1>
            <p className="text-sm font-bold opacity-30 tracking-[0.3em] uppercase mb-12">{t('subTitle')}</p>

            <div className="w-full max-w-[340px] space-y-4">
              <button onClick={() => setStep('LEVEL_SELECT')} className="btn-premium w-full h-20 bg-emerald-500 rounded-3xl font-black text-xl uppercase tracking-widest neon-glow">{t('startGame')}</button>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setShowLeaderboard(true)} className="glass-panel h-16 rounded-2xl font-black text-xs uppercase hover:bg-white/10 transition-colors">🏆 RANKING</button>
                <button onClick={() => setShowTrophyRoom(true)} className="glass-panel h-16 rounded-2xl font-black text-xs uppercase text-yellow-500 hover:bg-yellow-500/5 transition-colors">🏅 TROFEJI</button>
              </div>
            </div>

            <div className="mt-12 flex gap-4">
              <button onClick={toggleMute} className="w-14 h-14 glass-panel rounded-full flex items-center justify-center text-2xl hover:scale-110 active:scale-95 transition-all">{isMuted ? '🔇' : '🔊'}</button>
            </div>
          </motion.div>
        ) : step === 'LEVEL_SELECT' ? (
          <motion.div key="l" initial={{ x: 100, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -100, opacity: 0 }} className="flex-1 flex flex-col items-center p-6 overflow-y-auto custom-scrollbar">
            <h2 className="text-3xl font-black my-12 uppercase tracking-tight">{t('pickLevel')}</h2>
            <div className="w-full max-w-md space-y-4 pb-24">
              {levels.map(lvl => (
                <div key={lvl.id} onClick={() => lvl.unlocked && (setGameState(p => ({ ...p, currentLevel: lvl.id })), setStep(gameState.nickname ? 'CATEGORY_SELECT' : 'NICKNAME_INPUT'))} 
                     className={`level-card glass-panel p-6 rounded-[2rem] flex items-center justify-between group cursor-pointer ${!lvl.unlocked ? 'locked opacity-40 grayscale cursor-not-allowed' : ''}`}>
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-[10px] font-black opacity-30 uppercase tracking-widest">{t('lvl')} {lvl.id}</span>
                      <StarRating count={lvl.id} />
                    </div>
                    <h3 className="text-2xl font-black uppercase group-hover:text-emerald-400 transition-colors">{lvl.name[gameState.language]}</h3>
                    <p className="text-xs font-bold opacity-30 uppercase">{lvl.minDifficulty}-{lvl.maxDifficulty} DIFFICULTY</p>
                  </div>
                  <div className="text-right">
                    {lvl.unlocked ? (
                      <span className="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center text-emerald-500 group-hover:bg-emerald-500 group-hover:text-white transition-all">➔</span>
                    ) : (
                      <span className="text-2xl opacity-20">🔒</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
            <button onClick={() => setStep('HOME')} className="fixed bottom-8 left-1/2 -translate-x-1/2 glass-panel px-12 py-4 rounded-full font-black text-xs uppercase tracking-widest">{t('back')}</button>
          </motion.div>
        ) : step === 'NICKNAME_INPUT' ? (
          <motion.div key="n" initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="glass-panel p-10 rounded-[3rem] w-full max-w-[360px] text-center">
              <div className="text-4xl mb-6">👤</div>
              <h2 className="text-2xl font-black mb-8 uppercase tracking-tight">{t('enterNickname')}</h2>
              <input type="text" value={gameState.nickname} placeholder="MESSI_10" 
                     onChange={e => setGameState(p => ({ ...p, nickname: e.target.value.substring(0, 12).toUpperCase() }))} 
                     className="w-full h-16 bg-white/5 border border-white/10 rounded-2xl px-6 text-white font-black text-center mb-8 focus:outline-none focus:border-emerald-500 focus:bg-white/10 transition-all placeholder:opacity-20" />
              <button onClick={() => setStep('CATEGORY_SELECT')} disabled={!gameState.nickname.trim()} 
                      className="btn-premium w-full h-16 bg-emerald-500 rounded-2xl font-black uppercase disabled:opacity-20 neon-glow">ZAPOČNI</button>
            </div>
          </motion.div>
        ) : step === 'CATEGORY_SELECT' ? (
          <motion.div key="c" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center p-6 overflow-y-auto custom-scrollbar">
            <h2 className="text-2xl font-black my-12 uppercase opacity-40 tracking-widest">{t('selectCategory')}</h2>
            <div className="grid grid-cols-2 gap-4 w-full max-w-md mb-24">
              {Object.values(Category).map(cat => cat !== Category.ALL && (
                <div key={cat} onClick={() => handleStartQuiz(cat)} className="glass-panel p-8 rounded-3xl flex flex-col items-center text-center cursor-pointer group hover:bg-white/10 transition-all active:scale-95">
                  <div className={`w-16 h-16 ${CATEGORY_VISUALS[cat].color} rounded-2xl flex items-center justify-center text-3xl mb-4 group-hover:scale-110 transition-transform shadow-lg shadow-black/20`}>{CATEGORY_VISUALS[cat].icon}</div>
                  <span className="text-[10px] font-black uppercase tracking-widest opacity-60 group-hover:opacity-100">{CATEGORY_TRANSLATIONS[cat][gameState.language]}</span>
                </div>
              ))}
              <div onClick={() => handleStartQuiz(Category.ALL)} className="col-span-2 btn-premium bg-emerald-500/10 border-2 border-emerald-500/40 p-10 rounded-[2.5rem] flex flex-col items-center cursor-pointer group hover:bg-emerald-500/20 active:scale-95">
                <span className="text-5xl mb-4 group-hover:rotate-12 transition-transform drop-shadow-lg">⚽</span>
                <span className="text-sm font-black uppercase tracking-[0.4em]">{CATEGORY_TRANSLATIONS[Category.ALL][gameState.language]}</span>
              </div>
            </div>
            <button onClick={() => setStep('LEVEL_SELECT')} className="fixed bottom-8 left-1/2 -translate-x-1/2 glass-panel px-12 py-4 rounded-full font-black text-xs uppercase tracking-widest">{t('back')}</button>
          </motion.div>
        ) : (
          <motion.div key="q" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-4 w-full max-w-xl mx-auto h-full overflow-hidden">
            {gameState.isGameOver ? (
              <div className="flex-1 flex flex-col items-center justify-center">
                <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className={`glass-panel p-10 rounded-[3rem] border-2 ${isWin ? 'border-emerald-500/40 shadow-[0_0_50px_rgba(16,185,129,0.2)]' : 'border-rose-500/40'} text-center w-full max-w-[380px]`}>
                  <img src={GAME_LOGO} className="w-20 h-20 mx-auto mb-6" />
                  <h1 className={`text-4xl font-black mb-6 tracking-tighter ${isWin ? 'text-emerald-400' : 'text-rose-500'}`}>{isWin ? t('success') : t('gameOver')}</h1>
                  <div className="grid grid-cols-2 gap-3 mb-10">
                    <div className="bg-white/5 p-5 rounded-2xl border border-white/5"><span className="text-[10px] font-black opacity-30 block uppercase mb-1">{t('totalScoreLabel')}</span><p className="text-3xl font-black">{gameState.score}</p></div>
                    <div className="bg-white/5 p-5 rounded-2xl border border-white/5"><span className="text-[10px] font-black opacity-30 block uppercase mb-1">{t('accuracyLabel')}</span><p className="text-3xl font-black">{acc}%</p></div>
                  </div>
                  <div className="space-y-3">
                    <button onClick={handleExitGame} className="btn-premium w-full h-16 bg-emerald-500 rounded-2xl font-black uppercase tracking-widest">{t('playAgain')}</button>
                    <button onClick={() => handleStartQuiz(gameState.selectedCategory)} className="w-full h-12 glass-panel rounded-xl font-black uppercase text-xs opacity-60 hover:opacity-100">{t('retry')}</button>
                  </div>
                </motion.div>
              </div>
            ) : (
              <>
                <header className="flex justify-between items-center mb-4 glass-panel p-5 rounded-[2rem] shrink-0">
                  <button onClick={() => setIsPaused(true)} className="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center text-xl active:scale-90 transition-all">⏸</button>
                  <div className="text-center">
                    <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">{t('lvl')} {gameState.currentLevel} • {gameState.score} PTS</p>
                    <div className="flex gap-1 justify-center mt-1">
                      {[...Array(5)].map((_, i) => (
                        <span key={i} className={`text-sm ${i < (5 - gameState.mistakes) ? 'opacity-100 drop-shadow-[0_0_5px_rgba(244,63,94,0.5)]' : 'opacity-10 grayscale'}`}>❤️</span>
                      ))}
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">{t('questionLabel')} {gameState.questionsAnswered + 1}/20</p>
                    <div className={`mt-1 inline-block px-2 py-0.5 rounded-full text-[10px] font-black ${streak >= 5 ? 'bg-orange-500 text-white animate-pulse' : 'bg-white/10 text-white/30'}`}>x{streak}</div>
                  </div>
                </header>
                <div className="flex-1 flex flex-col justify-center pb-8 overflow-y-auto custom-scrollbar">
                  <AnimatePresence mode="wait">
                    {loading && questions.length <= currentQuestionIndex ? (
                      <div className="py-10"><QuizSkeleton /></div>
                    ) : questions[currentQuestionIndex] ? (
                      <QuizCard key={questions[currentQuestionIndex].id} question={questions[currentQuestionIndex]} onAnswer={handleAnswer} disabled={isPaused} isMuted={isMuted} language={gameState.language} isPaused={isPaused} categoryLabel={CATEGORY_TRANSLATIONS[questions[currentQuestionIndex].category][gameState.language]} />
                    ) : null}
                  </AnimatePresence>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isPaused && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-3xl flex items-center justify-center p-6" onClick={() => setIsPaused(false)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="glass-panel border-2 border-white/10 w-full max-w-[320px] rounded-[3rem] p-10 text-center shadow-2xl" onClick={e => e.stopPropagation()}>
               <div className="text-5xl mb-6">⚽</div>
               <h3 className="text-2xl font-black uppercase mb-10 tracking-tighter">PAUZA</h3>
               <div className="space-y-4">
                 <button onClick={() => setIsPaused(false)} className="btn-premium w-full h-16 bg-emerald-500 rounded-2xl font-black uppercase tracking-widest">{t('resume')}</button>
                 <button onClick={handleExitGame} className="w-full h-12 bg-rose-500/10 text-rose-500 rounded-xl font-black uppercase text-[10px] border border-rose-500/20">{t('exit')}</button>
               </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

