  score: { Bosanski: "BODOVI", English: "SCORE", Deutsch: "PUNKTE" },
  gameOver: { Bosanski: "KRAJ UTAKMICE!", English: "FULL TIME!", Deutsch: "SPIEL VORBEI!" },
