  [Category.PLAYERS]: { Bosanski: "Igrači", English: "Players", Deutsch: "Spieler" },
  [Category.STADIUMS]: { Bosanski: "Stadioni", English: "Stadiums", Deutsch: "Stadien" },
  [Category.CLUBS]: { Bosanski: "Klubovi", English: "Clubs", Deutsch: "Klubs" },
  [Category.NATIONAL_TEAMS]: { Bosanski: "Reprezentacije", English: "National Teams", Deutsch: "Nationalteams" },
  [Category.COACHES]: { Bosanski: "Treneri", English: "Coaches", Deutsch: "Trainer" },
  [Category.ALL]: { Bosanski: "Sve Kategorije", English: "All Categories", Deutsch: "Alle Kategorien" }
};

const LANGUAGE_FLAGS: Record<Language, string> = { 'Bosanski': '🇧🇦', 'English': '🇬🇧', 'Deutsch': '🇩🇪' };
const GAME_LOGO = "https://i.imgur.com/EgHOWpF.png";

const QuizSkeleton: React.FC = () => (
  <div className="glass-panel rounded-[2.5rem] p-6 md:p-8 border-2 border-white/5 overflow-hidden w-full max-w-xl">
    <div className="h-2 w-full bg-white/5 mb-8 rounded-full overflow-hidden">
        <motion.div className="h-full bg-emerald-500/20" animate={{ x: ["-100%", "100%"] }} transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }} />
    </div>
    <div className="flex justify-between items-center mb-10 pt-2">
      <div className="h-8 w-24 bg-white/10 rounded-full shimmer" />
      <div className="h-8 w-16 bg-white/10 rounded-full shimmer" />
