import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Question, Language } from '../types';
import { audioService } from '../services/audioService';

interface QuizCardProps {
  question: Question;
  onAnswer: (answer: string) => void;
  disabled: boolean;
  isMuted: boolean;
  language: Language;
  isPaused?: boolean;
  categoryLabel: string;
}

const TRANSLATIONS = {
  correct: { Bosanski: "TAČNO!", English: "CORRECT!", Deutsch: "RICHTIG!" },
  wrong: { Bosanski: "NETAČNO!", English: "WRONG!", Deutsch: "FALSCH!" },
  difficulty: { Bosanski: "TEŽINA", English: "DIFF", Deutsch: "DIFF" },
  timesUp: { Bosanski: "VRIJEME!", English: "TIME!", Deutsch: "ZEIT!" }
};

const QuizCard: React.FC<QuizCardProps> = ({ question, onAnswer, disabled, isMuted, language, isPaused, categoryLabel }) => {
  const [selected, setSelected] = useState<string | null>(null);
  const [isWrong, setIsWrong] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isPaused || selected) {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
      return;
    }

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          audioService.stopSfx('tick');
          audioService.playSfx('timesUp', 0.8, true);
          handleTimeout();
          return 0;
        }
        const nextVal = prev - 1;
        if (nextVal <= 3) audioService.playSfx('tick', 0.8);
        else if (nextVal <= 6) audioService.playSfx('tick', 0.4);
        else audioService.playSfx('tick', 0.15);
        return nextVal;
      });
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      audioService.stopSfx('tick');
    };
  }, [question.id, isPaused, selected]);

  useEffect(() => {
    setTimeLeft(10);
    setSelected(null);
    setIsWrong(false);
  }, [question.id]);

  const handleTimeout = () => {
    if (selected) return;
    setIsWrong(true);
    setTimeout(() => audioService.playSfx('wrong', 0.6, true), 200);
    setSelected("");
    setTimeout(() => { onAnswer(""); }, 2500);
  };

  const handleSelect = (option: string) => {
    if (disabled || selected || timeLeft <= 0 || isPaused) return;
    if (timerRef.current) clearInterval(timerRef.current);
    audioService.stopSfx('tick');
    audioService.playSfx('click', 0.4);
    const correct = option === question.correctAnswer;
    setSelected(option);
    setTimeout(() => {
      if (correct) audioService.playSfx('correct', 0.7, true);
      else { setIsWrong(true); audioService.playSfx('wrong', 0.7, true); }
    }, 150);
    setTimeout(() => { onAnswer(option); }, 3000);
  };

  const t = (key: keyof typeof TRANSLATIONS) => TRANSLATIONS[key][language];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className={`glass-panel rounded-[2.5rem] p-6 md:p-10 border-2 ${isWrong ? 'animate-shake border-rose-500/30' : 'border-white/10'} transition-all relative overflow-hidden`}
    >
      <div className="absolute top-0 left-0 w-full h-1.5 bg-white/5">
        <motion.div className={`h-full ${timeLeft <= 3 ? 'bg-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.5)]' : 'bg-emerald-500'}`}
          initial={{ width: "100%" }} animate={{ width: selected ? "0%" : `${(timeLeft / 10) * 100}%` }}
          transition={{ duration: selected || isPaused ? 0 : 1, ease: "linear" }}
        />
      </div>

      <div className="flex justify-between items-center mb-10 pt-2">
        <motion.span initial={{ x: -10 }} animate={{ x: 0 }} className="bg-white/5 text-white/60 border border-white/10 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest">{categoryLabel}</motion.span>
        <div className="flex items-center gap-3">
          <span className={`text-xs font-black tabular-nums transition-colors ${timeLeft <= 3 ? 'text-rose-500 animate-pulse' : 'text-white/40'}`}>{timeLeft}S</span>
          <div className="flex gap-1">
            {[...Array(5)].map((_, i) => (
              <div key={i} className={`w-1 h-3 rounded-full transition-all duration-500 ${i < question.difficulty / 2 ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-white/5'}`} />
            ))}
          </div>
        </div>
      </div>

      <h2 className="text-xl md:text-3xl font-black text-white text-center mb-12 leading-tight px-2 drop-shadow-lg min-h-[4rem] flex items-center justify-center">
        {question.text}
      </h2>

      <div className="grid grid-cols-1 gap-4">
        {question.options.map((option, idx) => {
          const isSelected = selected === option;
          const isCorrect = isSelected && option === question.correctAnswer;
          const isWrongOption = isSelected && option !== question.correctAnswer;
          const showCorrectIfMissed = selected && !isSelected && option === question.correctAnswer;

          return (
            <motion.button 
              key={idx} 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: idx * 0.1 }}
              onClick={() => handleSelect(option)} 
              disabled={!!selected || isPaused}
              className={`p-5 md:p-7 rounded-[1.5rem] md:rounded-[2rem] border-2 text-sm md:text-lg font-bold transition-all text-left flex items-center group
                ${!selected ? 'bg-white/5 border-white/5 text-white/70 hover:bg-white/10 hover:border-white/20 active:scale-95' : ''}
                ${isCorrect ? 'bg-emerald-500 border-emerald-400 text-white shadow-xl shadow-emerald-500/30' : ''}
                ${isWrongOption ? 'bg-rose-500 border-rose-400 text-white shadow-xl shadow-rose-500/30' : ''}
                ${showCorrectIfMissed ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : ''}
                ${selected && !isSelected && !showCorrectIfMissed ? 'opacity-10 grayscale scale-[0.98]' : ''}
              `}
            >
              <span className={`w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-xl bg-black/20 text-xs md:text-sm mr-5 shrink-0 font-black transition-colors ${isSelected ? 'bg-white/20' : 'group-hover:bg-white/10'}`}>
                {String.fromCharCode(65 + idx)}
              </span>
              <span className="flex-1 leading-snug">{option}</span>
            </motion.button>
          );
        })}
      </div>

      <AnimatePresence>
        {selected !== null && (
           <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="mt-8 p-6 bg-white/5 border border-white/10 rounded-3xl relative overflow-hidden">
              <div className="absolute inset-0 shimmer opacity-10"></div>
              {selected === "" && <p className="text-rose-500 font-black text-center text-[10px] uppercase mb-2 tracking-[0.2em]">{t('timesUp')}</p>}
              <p className="text-white/60 text-xs md:text-base text-center italic font-medium leading-relaxed relative z-10">"{question.explanation}"</p>
           </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

