                      </div>
                    </div>
                    <h3 className="text-2xl font-black uppercase group-hover:text-emerald-400 transition-colors">{lvl.name[gameState.language]}</h3>
                    <p className="text-xs font-bold opacity-30 uppercase">{lvl.minDifficulty}-{lvl.maxDifficulty} DIFFICULTY</p>
                  </div>
