                  <span className="text-[10px] font-black uppercase tracking-widest opacity-60 group-hover:opacity-100">{CATEGORY_TRANSLATIONS[cat][gameState.language]}</span>
                </motion.div>
              ))}
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => handleStartQuiz(Category.ALL)} className="col-span-2 btn-premium bg-emerald-500/10 border-2 border-emerald-500/40 p-10 rounded-[2.5rem] flex flex-col items-center cursor-pointer group">
