                            isMuted={isMuted} 
                            language={gameState.language} 
                            isPaused={isPaused}
                            categoryLabel={CATEGORY_TRANSLATIONS[questions[currentQuestionIndex].category][gameState.language] || questions[currentQuestionIndex].category}
                          />
                        </div>
                      ) : null}
                    </AnimatePresence>
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <AnimatePresence>
        {isPaused && (
