                 <button onClick={handleExitGame} className="w-full h-12 bg-rose-500/10 border border-rose-500/20 text-rose-500 font-black rounded-lg uppercase text-[9px] tracking-widest">{t('exitGame')}</button>
               </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
